\label{mumford-IV18-source}
\dcref{M:ch4:IV.18}

\begin{theorem}[Serre--Lang]
\label{mumford-thm-etale-cover-abelian-structure}
\dcref{M:ch4:IV.18}
If $X$ is an abelian variety, $Y$ a variety, and $f:Y\to X$ an etale
covering, then $Y$ has a unique abelian-variety structure for which $f$ is
a separable isogeny.
\source{mumford-abelian-varieties:page-0178}
\source{mumford-abelian-varieties:page-0179}
\source{mumford-abelian-varieties:page-0180}
\end{theorem}
\begin{proof}
Let $\Gamma_m$ be the graph of multiplication on $X$ and let $\Gamma'$ be
its inverse image in $Y^3$. Let $\Gamma$ be the component containing
$(y_0,y_0,y_0)$, where $f(y_0)=0$. Its projection
$p:\Gamma\to Y\times Y$ is etale. The sections
$\sigma_1(y)=(y_0,y,y)$ and $\sigma_2(y)=(y,y_0,y)$ show that it is enough
to prove $p$ is an isomorphism, or equivalently that the fibre of
$q:\Gamma\to Y$ at $y_0$ is irreducible.

We use the lemma below. Since $\Gamma$ is nonsingular and connected it is
irreducible, and $q$ is proper smooth with a section, so the lemma applies.
Thus $p$ is an isomorphism. The third projection then defines a morphism
$v:Y\times Y\to Y$ with $v(y,y_0)=y=v(y_0,y)$. The appendix theorem on
such a composition makes $Y$ an abelian variety with zero $y_0$; $f$ is a
homomorphism because $f(y_0)=0$.
\end{proof}

\begin{lemma}[Irreducibility of fibres]
\label{mumford-lem-etale-cover-graph}
\dcref{M:ch4:IV.18}
\uses{mumford-thm-etale-cover-abelian-structure}
If $f:X\to Y$ is a proper smooth morphism of irreducible varieties with a
section, all fibres of $f$ are irreducible.
\source{mumford-abelian-varieties:page-0179}
\end{lemma}
\begin{proof}
Take $Y=\operatorname{Spec}A$ affine and $B=\Gamma(X,\mathcal O_X)$.
The factorization $X\to\operatorname{Spec}B\to Y$ and the section imply,
by equality of dimensions, that $A=B$. Smooth fibres are nonsingular, so it
remains to prove connectedness. A universally computing free complex gives,
after completion at a maximal ideal,
\[
\widehat A\simeq\varprojlim_n\ker\left[
 K_0/\mathfrak M^nK_0\to K_1/\mathfrak M^nK_1\right]
\simeq\varprojlim_n H^0(f^{-1}(y),\mathcal O_X/\mathfrak M^n\mathcal O_X).
\]
If a fibre were $Z_1\cup Z_2$ disconnected, a function reducing to $1$ on
$Z_1$ and $0$ on $Z_2$ would give a nontrivial idempotent in the local ring
$\widehat A$, a contradiction.
\end{proof}

\begin{remark}[Quasi-inverse to an isogeny]
\label{mumford-rem-isogeny-quasi-inverse}
\dcref{M:ch4:IV.18}
\uses{mumford-thm-etale-cover-abelian-structure}
If $f:Y\to X$ is an isogeny of abelian varieties, there is an isogeny
$g:X\to Y$ and $n>0$ with $g f=n_Y$ and $f g=n_X$: choose $n$ killing
$\ker f$, and factor multiplication by $n$ through the quotient by $\ker f$.
\source{mumford-abelian-varieties:page-0180}
\end{remark}

\begin{proposition}[Fundamental group and Tate modules]
\label{mumford-prop-etale-coverings-av}
\label{mumford-def-tate-module}
\label{mumford-prop-galois-tate-action}
\dcref{M:ch4:IV.18}
\uses{mumford-thm-etale-cover-abelian-structure}
For a pointed nonsingular variety, the pointed connected finite etale
coverings form an inverse system and
\[
\pi_1(X,x_0)=\varprojlim_{(Y,y_0,\pi)}G_Y.
\]
For an abelian variety $X$ with zero base point,
\[
\pi_1(X)\simeq\prod_lT_l(X),\qquad T_l(X)=\varprojlim_mX_{l^m}.
\]
For $l\ne p$, $T_l(X)\simeq\mathbb Z_l^{2g}$; if $r$ is the $p$-rank,
$T_p(X)=\varprojlim X^r_{p^m}\simeq\mathbb Z_p^r$.
\source{mumford-abelian-varieties:page-0180}
\source{mumford-abelian-varieties:page-0181}
\source{mumford-abelian-varieties:page-0182}
\source{mumford-abelian-varieties:page-0183}
\end{proposition}
\begin{proof}
There is at most one pointed map over $X$ between two coverings; when it
exists it induces a unique surjection of their deck groups. For $l\ne p$,
the coverings $X\xrightarrow{l^m}X$ are cofinal among coverings with
$l$-power kernel, giving the inverse limit. The finite torsion groups are
$X_{l^m}\simeq(\mathbb Z/l^m\mathbb Z)^{2g}$. The characteristic-$p$
statement follows from the reduced part of $X_{p^m}$. Over $\mathbb C$,
for $X=V/U$, the same system is $\varprojlim U/l^mU$, whose full profinite
completion is $\varprojlim U/nU$.
\end{proof}

\section{Structure of $\operatorname{Hom}(X,Y)$}
\label{mumford-IV19-source}
\dcref{M:ch4:IV.19}

\begin{definition}[Homomorphisms up to isogeny]
\label{mumford-def-hom-up-to-isogeny}
\dcref{M:ch4:IV.19}
Put
$\operatorname{Hom}^0(X,Y)=\mathbb Q\otimes_\mathbb Z\operatorname{Hom}(X,Y)$
and $\operatorname{End}^0X=\mathbb Q\otimes_\mathbb Z\operatorname{End}X$.
Composition makes abelian varieties up to isogeny a category, in which
isogenies are isomorphisms, and
\[
\operatorname{Hom}^0(X,Y)=\varinjlim_{X'\to X}\operatorname{Hom}(X',Y).
\]
\source{mumford-abelian-varieties:page-0183}
\end{definition}

\begin{theorem}[Poincare complete reducibility]
\label{mumford-thm-poincare-complete-reducibility}
\dcref{M:ch4:IV.19}
\uses{mumford-cor-line-bundle-morphism}
If $Y$ is an abelian subvariety of $X$, there is an abelian subvariety $Z$
with $Y\cap Z$ finite and $Y+Z=X$; equivalently $X$ is isogenous to
$Y\times Z$.
\source{mumford-abelian-varieties:page-0184}
\end{theorem}
\begin{proof}
Let $i:Y\to X$ be inclusion, $\widehat i:\widehat X\to\widehat Y$ its
dual, and choose ample $L$ on $X$. Put $Z$ equal to the connected component
of zero in $\phi_L^{-1}(\ker\widehat i)$. Then
$\dim Z\ge\dim X-\dim Y$, while
$Z\cap Y=K(L|_Y)$ is finite. Therefore $Z\times Y\to X$ is surjective
with finite kernel.
\end{proof}

\begin{definition}[Simple abelian variety]
\label{mumford-def-simple-abelian-variety}
\dcref{M:ch4:IV.19}
An abelian variety is simple if it has no abelian subvariety other than zero
and itself.
\source{mumford-abelian-varieties:page-0185}
\end{definition}

\begin{corollary}[Simple decomposition]
\label{mumford-cor-simple-decomposition}
\label{mumford-cor-simple-endomorphism-algebra}
\dcref{M:ch4:IV.19}
Every abelian variety is isogenous to
$X_1^{n_1}\times\cdots\times X_k^{n_k}$ with the $X_i$ simple and pairwise
non-isogenous; the types and multiplicities are unique. If $X$ is simple,
$\operatorname{End}^0X$ is a division ring, and in general
\[
\operatorname{End}^0(X)=\bigoplus_iM_{n_i}(\operatorname{End}^0X_i).
\]
\source{mumford-abelian-varieties:page-0185}
\uses{mumford-thm-poincare-complete-reducibility}
% Source prints these as corollaries without proofs.
\notready
\end{corollary}

\begin{theorem}[Degree polynomial]
\label{mumford-thm-degree-polynomial}
\dcref{M:ch4:IV.19}
\uses{mumford-thm-poincare-complete-reducibility,mumford-thm-riemann-roch}
The function $\phi\mapsto\deg\phi$ on $\operatorname{End}X$ extends to a
homogeneous polynomial of degree $2g$ on $\operatorname{End}^0X$.
\source{mumford-abelian-varieties:page-0185}
\source{mumford-abelian-varieties:page-0186}
\end{theorem}
\begin{proof}
For $P(n)=\deg(n\phi+\psi)$, the ample bundle formula gives
$P(n)=\chi((n\phi+\psi)^*L)/\chi(L)$. The theorem of the cube supplies
line bundles $L_1,L_2,L_3$ with
\[
L_{n+2}\otimes L_{n+1}^{-2}\otimes L_n\otimes(2\phi)^*L^{-1}
\otimes\phi^*L\otimes\phi^*L=1,
\]
and induction gives
$L_n=L_1^{n(n-1)/2}\otimes L_2^n\otimes L_3$. Since Euler characteristic
is polynomial on line bundles, $P(n)$ is polynomial; homogeneity follows
from $\deg(n\phi)=n^{2g}\deg\phi$.
\end{proof}

\begin{theorem}[Tate representation]
\label{mumford-thm-hom-tate-injective}
\dcref{M:ch4:IV.19}
\uses{mumford-prop-etale-coverings-av,mumford-thm-degree-polynomial}
For abelian varieties $X,Y$, $\operatorname{Hom}(X,Y)$ is a finitely
generated free abelian group, and for $l\ne\operatorname{char}k$,
\[
\mathbb Z_l\otimes_\mathbb Z\operatorname{Hom}(X,Y)\longrightarrow
\operatorname{Hom}_{\mathbb Z_l}(T_l(X),T_l(Y))
\]
is injective. In characteristic zero over $\mathbb C$, restriction to the
lattices in $X_i=V_i/U_i$ injects Hom into
$\operatorname{Hom}_{\mathbb Z}(U_1,U_2)$.
\source{mumford-abelian-varieties:page-0186}
\source{mumford-abelian-varieties:page-0187}
\source{mumford-abelian-varieties:page-0188}
\source{mumford-abelian-varieties:page-0189}
\end{theorem}
\begin{proof}
Complex homomorphisms lift to complex-linear maps $V_1\to V_2$ carrying
$U_1$ into $U_2$, so the lattice map is injective and gives the stated
finite rank bound. For arbitrary $k$, use $T_l$. For a finitely generated
subgroup $M$, Step I shows its saturation
$\mathbb QM\cap\operatorname{Hom}(X,Y)$ is finitely generated: reduce by
isogenies to simple factors and use the degree polynomial, whose nonzero
values are bounded away from zero on a lattice. For a saturated $M$ with
basis $f_i$, a nontrivial $l$-adic relation in the Tate representation can
be approximated by an integral relation $\sum n_if_i$ not all divisible by
$l$. Its Tate map is zero, so it factors through multiplication by $l$,
contradicting saturation. Thus the Tate map is injective. Finite generation
and torsion-freeness give freeness.
\end{proof}

\begin{corollary}[Neron--Severi and endomorphism algebras]
\label{mumford-cor-ns-finite-free}
\dcref{M:ch4:IV.19}
$\operatorname{NS}(X)=\operatorname{Pic}X/\operatorname{Pic}^0X$ is free of
finite rank, and $\operatorname{End}X$ is a finite-dimensional semisimple
algebra over $\mathbb Q$.
\source{mumford-abelian-varieties:page-0189}
\uses{mumford-thm-hom-tate-injective}
\end{corollary}
\begin{proof}
The map $L\mapsto\phi_L$ injects $\operatorname{NS}(X)$ into
$\operatorname{Hom}(X,\widehat X)$, so the first assertion follows. The
second follows from the simple decomposition and the division-ring assertion
for a simple factor.
\end{proof}

\begin{lemma}[Norms and traces of simple algebras]
\label{mumford-lem-reduced-norm-simple-algebra}
\dcref{M:ch4:IV.19}
\uses{mumford-cor-simple-decomposition}
For a finite-dimensional associative simple separable algebra $A$ over
$\Gamma$, with center $\Lambda$, there are canonical reduced norm and trace
forms. Every norm is
$(\operatorname{Nm}_{\Lambda/\Gamma}\circ N^0)^k$ and every trace is
$\phi\circ\operatorname{Tr}^0$; if $[A:\Lambda]=d^2$, $N^0$ has degree $d$.
\source{mumford-abelian-varieties:page-0189}
\source{mumford-abelian-varieties:page-0190}
\source{mumford-abelian-varieties:page-0191}
\end{lemma}
\begin{proof}
After a separable closure, $A$ becomes a product of matrix algebras, where
the assertion is determinant and trace. Writing the factors using the
embeddings $\sigma_i:\Lambda\to\overline\Gamma$, a norm is
$\prod_iN_i^0(\phi_i(\alpha))^{n_i}$. Galois transitivity forces all
$n_i$ equal, giving the displayed norm; the trace argument is analogous.
\end{proof}

\begin{theorem}[Degree and Tate determinant]
\label{mumford-thm-degree-tate-determinant}
\dcref{M:ch4:IV.19}
\uses{mumford-lem-reduced-norm-simple-algebra,mumford-thm-hom-tate-injective}
For $f\in\operatorname{End}X$ and $l\ne\operatorname{char}k$,
\[
\deg f=\det T_l(f).
\]
Thus $\deg(n_X-f)=P(n)$, where $P(t)=\det(t-T_l(f))$ is monic of degree
$2g$ with integral rational coefficients and $P(f)=0$.
\source{mumford-abelian-varieties:page-0191}
\source{mumford-abelian-varieties:page-0192}
\end{theorem}
\begin{proof}
Both sides extend to norm forms of degree $2g$ on
$\mathbb Q_l\otimes\operatorname{End}X$. Their $l$-adic absolute values
agree because the power of $l$ in $\deg f$ is the order of the kernel on
$X_{l^n}$, hence the order of the cokernel of $T_l(f)$. Decomposition into
simple factors and the preceding norm lemma give equality. The
characteristic-polynomial assertions follow.
\end{proof}

\begin{remark}[Characteristic and CM type]
\label{mumford-rem-endomorphism-characteristic}
\dcref{M:ch4:IV.19}
\uses{mumford-thm-degree-tate-determinant}
The constant term and negative coefficient of $t^{2g-1}$ in the polynomial
above are respectively the norm and trace. If $X$ is simple, with center
$K$, $[K:\mathbb Q]=e$, and $[\operatorname{End}^0X:K]=d^2$, then $de\mid2g$.
It is of CM type precisely when $de=2g$, equivalently when
$\operatorname{End}^0X$ contains a field of degree $2g$ over $\mathbb Q$.
\source{mumford-abelian-varieties:page-0193}
\source{mumford-abelian-varieties:page-0194}
\end{remark}

\section{Riemann forms}
\label{mumford-IV20-opening-source}
\dcref{M:ch4:IV.20}

\begin{definition}[Tate pairing]
\label{mumford-def-weil-pairing-ladic}
\dcref{M:ch4:IV.20}
\uses{mumford-prop-etale-coverings-av}
For $l\ne\operatorname{char}k$, put
$M_l=\varprojlim\mu_{l^n}\simeq\mathbb Z_l$. For $n$ prime to the
characteristic, the kernels of $n_X$ and $n_{\widehat X}$ have a canonical
pairing $\bar e_n:X_n\times(\widehat X)_n\to\mu_n$.
\source{mumford-abelian-varieties:page-0194}
\end{definition}

\begin{lemma}[Divisor formula for the pairing]
\label{mumford-lem-riemann-pairing-divisor}
\dcref{M:ch4:IV.20}
\uses{mumford-def-weil-pairing-ladic}
If $(f)=nD$ and $(g)=n_X^{-1}(D)$, then
\[
\bar e_n(a,\lambda)=g(x)/g(x+a).
\]
\source{mumford-abelian-varieties:page-0195}
\end{lemma}
\begin{proof}
Since $L^n$ and $n_X^*L$ are trivial, choose $f,g$ as stated. Then
$n_X^*f=(g^n)$, so $g^n(x)=\alpha f(nx)$; hence the ratio is a constant
$n$th root of unity, equal to the pairing.
\end{proof}

\begin{proposition}[Compatibility of pairings]
\label{mumford-prop-riemann-pairing-compatibility}
\dcref{M:ch4:IV.20}
\uses{mumford-lem-riemann-pairing-divisor}
For coprime $m,n$, $x\in X_{mn}$ and $y\in(\widehat X)_{mn}$,
\[
\bar e_n(mx,my)=\bar e_{mn}(x,y)^m.
\]
\source{mumford-abelian-varieties:page-0196}
\end{proposition}
\begin{proof}
For a complete variety with a free action of a finite group $G$, and a
normal subgroup $H$, a line bundle on the quotient by $G$ which becomes
trivial on the quotient by $H$ has its $G/H$ character pulled back to a
$G$-character. Apply this with $G=X_{mn}$ and $H=X_m$; the quotient maps
are multiplication maps, giving the formula.
\end{proof}

% Source-faithful assembly: Mumford, Abelian Varieties, Chapter IV,
% Horizon transcription pages 0197--0206.

\label{mumford-IV20-source}
\dcref{M:ch4:IV.20}

\begin{proposition}[Tate pairing and Riemann form]
\label{mumford-prop-tate-riemann-pairing}
\dcref{M:ch4:IV.20}
\uses{mumford-def-weil-pairing-ladic}
There is a natural non-degenerate $\mathbb Z_l$-bilinear pairing
\[
e_l:T_l(X)\times T_l(\widehat X)\longrightarrow M_l.
\]
If $f:X\to Y$ has dual $\widehat f$, then
\[
e_l(T_l(f)\xi,\eta)=e_l(\xi,T_l(\widehat f)\eta).
\]
For a line bundle $L$ on $X$, define
\[
E^L(x,y)=e_l(x,T_l(\phi_L)(y)).
\]
\source{mumford-abelian-varieties:page-0197}
\end{proposition}

\begin{theorem}[Skew-symmetry of the Riemann form]
\label{mumford-thm-riemann-form-skew}
\dcref{M:ch4:IV.20}
\uses{mumford-prop-tate-riemann-pairing}
The form $E^L$ is skew-symmetric for every line bundle $L$.
Consequently $L\mapsto E^L$ injects
\[
\operatorname{NS}(X)\longrightarrow
\{\text{alternating forms }T_l(X)\times T_l(X)\to M_l\}.
\]
\source{mumford-abelian-varieties:page-0197}
\source{mumford-abelian-varieties:page-0198}
\end{theorem}
\begin{proof}
It suffices to show $e_l(a,\phi_L(a))=1$ for $a\in X_l$. If $a\in X_n$
and $(g)=n_X^{-1}(T_aD-D)$ for a divisor $D$ representing $L$, choose
$b$ with $nb=a$. Then $h(x)=\prod_{i=0}^{n-1}g(x+ib)$ is constant, and
\[
1=\frac{h(x+b)}{h(x)}=\frac{g(x+a)}{g(x)}.
\]
Thus the pairing is trivial on the diagonal. If $E^L=0$, then
$T_l(\phi_L)=0$, and faithfulness of the Tate representation gives
$\phi_L=0$, proving injectivity modulo $\operatorname{Pic}^0$.
\end{proof}

\begin{proposition}[Pullback of Riemann forms]
\label{mumford-prop-riemann-form-pullback}
\dcref{M:ch4:IV.20}
\uses{mumford-prop-tate-riemann-pairing}
For a homomorphism $f:X\to Y$ and a line bundle $L$ on $Y$,
\[
E^{f^*L}(x,y)=E^L(T_l(f)x,T_l(f)y).
\]
\source{mumford-abelian-varieties:page-0198}
\end{proposition}
\begin{proof}
Using $\phi_{f^*L}=\widehat f\phi_Lf$ and adjointness,
\[
\begin{aligned}
E^{f^*L}(x,y)&=e_l(x,\phi_{f^*L}(y))\\
&=e_l(x,T_l(\widehat f\phi_Lf)(y))
=e_l(T_l(f)x,\phi_L(T_l(f)y)).
\end{aligned}
\]
\end{proof}

\begin{proposition}[The Poincare Riemann form]
\label{mumford-prop-poincare-riemann-form}
\dcref{M:ch4:IV.20}
\uses{mumford-thm-riemann-form-skew,mumford-thm-poincare-universal-mapping}
Under $T_l(X\times\widehat X)=T_l(X)\times T_l(\widehat X)$,
\[
E^P((x,\widehat x),(y,\widehat y))
=e_l(x,\widehat y)-e_l(y,\widehat x).
\]
\source{mumford-abelian-varieties:page-0198}
\source{mumford-abelian-varieties:page-0199}
\end{proposition}
\begin{proof}
By skew-symmetry and linearity it suffices to consider the two factors
separately. The first two restrictions of $P$ are trivial. The canonical
identification $\widehat{X\times Y}\simeq\widehat X\times\widehat Y$ gives
$\phi_P(x,\widehat x)=(\widehat x,\phi(x))$, and hence the cross term is
$e_l(x,\widehat y)$; skew-symmetry supplies the other cross term.
\end{proof}

\begin{theorem}[Skew forms and line bundles]
\label{mumford-thm-riemann-form-line-bundle}
\dcref{M:ch4:IV.20}
\uses{mumford-prop-poincare-riemann-form}
For a homomorphism $\phi:X\to\widehat X$, the form
$e_l(x,\phi(y))$ is skew-symmetric if and only if there is a line bundle
$L$ with $2\phi=\phi_L$.
\source{mumford-abelian-varieties:page-0199}
\end{theorem}
\begin{proof}
The forward implication follows from Theorem 1. Conversely, pull back $P$
along $(1,\phi):X\to X\times\widehat X$ to obtain $L$. Then
\[
e_l(x,\phi_L(y))=E^P((x,\phi x),(y,\phi y))
=e_l(x,\phi y)-e_l(y,\phi x)=2e_l(x,\phi y),
\]
so faithfulness gives $2\phi=\phi_L$.
\end{proof}

\begin{proposition}[Rosati involution]
\label{mumford-prop-rosati-involution}
\dcref{M:ch4:IV.20}
\uses{mumford-prop-tate-riemann-pairing}
For ample $L$ on $X$, define
\[
\phi'=\phi_L^{-1}\widehat\phi\phi_L.
\]
Then $'$ is a $\mathbb Q$-linear involution,
$(\phi\psi)'=\psi'\phi'$, and
\[
E^L(\phi x,y)=E^L(x,\phi'y).
\]
\source{mumford-abelian-varieties:page-0200}
\end{proposition}
\begin{proof}
Extend $T_l$ to $\operatorname{End}^0X$. The displayed identity follows
from the Tate adjunction:
\[
E^L(x,\phi'y)=e_l(x,\widehat\phi\phi_L(y))
=e_l(\phi x,\phi_L(y))=E^L(\phi x,y).
\]
Non-degeneracy gives all involution identities.
\end{proof}

\begin{theorem}[Neron--Severi classes and Rosati fixed points]
\label{mumford-thm-ns-rosati-fixed}
\dcref{M:ch4:IV.20}
\uses{mumford-thm-riemann-form-line-bundle,mumford-prop-rosati-involution}
Under $\operatorname{Hom}^0(X,\widehat X)\simeq\operatorname{End}^0X$ via
$\psi\mapsto\phi_L^{-1}\psi$, the space
$\mathbb Q\otimes\operatorname{NS}(X)$ is exactly the fixed subspace of
the Rosati involution.
\source{mumford-abelian-varieties:page-0201}
\end{theorem}
\begin{proof}
By the preceding skew-form theorem, $\psi$ comes from a divisor precisely
when $e_l(x,\psi y)=-e_l(y,\psi x)$. This is equivalent to
\[
E^L(x,\psi y)=E^L(\psi x,y)=E^L(x,\psi'y).
\]
Non-degeneracy and faithfulness give $\psi=\psi'$.
\end{proof}

\begin{theorem}[Wedge and intersection numbers]
\label{mumford-thm-riemann-wedge-intersection}
\dcref{M:ch4:IV.20}
\uses{mumford-thm-riemann-roch,mumford-thm-degree-tate-determinant}
There is a generator
$v\in\operatorname{Hom}_{\mathbb Z_l}(\Lambda^2T_l(X),M_l)$ such that
for divisors $D_i$ and $E_i=E^{\mathcal O_X(D_i)}$,
\[
E_1\wedge\cdots\wedge E_g=(D_1\cdots D_g)v.
\]
\source{mumford-abelian-varieties:page-0201}
\source{mumford-abelian-varieties:page-0202}
\end{theorem}
\begin{proof}
Both sides are polynomial in the Neron--Severi classes, so polarization
reduces to one bundle $L$. Riemann--Roch gives
$[E^L]^{\wedge g}=g!\chi(L)v$. In a basis,
\[
([E^L]^{\wedge g})^2=(\det E^L)(g!)^2.
\]
Since $\det E^L=\det T_l(\phi_L)$ and the degree/determinant comparison
differs only by an $l$-adic unit, the normalization of $v$ gives the result.
\end{proof}

\begin{corollary}[Degree of a fixed subalgebra]
\label{mumford-cor-rosati-subalgebra-degree}
\dcref{M:ch4:IV.20}
\uses{mumford-thm-riemann-wedge-intersection}
If $X$ is simple and $K\subset\operatorname{End}^0X$ is a $\mathbb Q$-subalgebra
fixed by Rosati, then $[K:\mathbb Q]$ divides $\dim X$.
\source{mumford-abelian-varieties:page-0202}
\source{mumford-abelian-varieties:page-0203}
\end{corollary}
\begin{proof}
The ratio $\chi(M)/\chi(L)$ is a norm form on $K$ of degree $g$, since its
square is $\deg(\phi_L^{-1}\phi_M)$. The degree of a field therefore divides
the degree of this norm form.
\end{proof}

\section{Positivity of the Rosati involution}
\label{mumford-IV21-source}
\dcref{M:ch4:IV.21}

\begin{theorem}[Positive Rosati trace]
\label{mumford-thm-rosati-positive}
\dcref{M:ch4:IV.21}
\uses{mumford-thm-riemann-wedge-intersection,mumford-prop-rosati-involution}
For an ample divisor $H$, $L=\mathcal O_X(H)$, and the Rosati involution
defined by $L$,
\[
\operatorname{Tr}(\phi\phi')
=\frac{2g}{(H^g)}(H^{g-1}\cdot\phi^*H),
\]
and $\phi\mapsto\operatorname{Tr}(\phi\phi')$ is positive definite.
\source{mumford-abelian-varieties:page-0203}
\source{mumford-abelian-varieties:page-0204}
\end{theorem}
\begin{proof}
The wedge/intersection theorem gives
\[
\frac{(E^L)^{\wedge(2g-1)}\wedge E^{\phi^*L}}
     {(E^L)^{\wedge2g}}
=\frac{(H^{g-1}\cdot\phi^*H)}{(H^g)}
=\frac1{2g}\operatorname{Tr}(\phi\phi').
\]
Choose a symplectic basis for $E^L$ and expand exterior multiplication. The
resulting quadratic form is a sum of squares, hence positive definite.
\end{proof}

\begin{proposition}[Simple endomorphism algebras: initial classification]
\label{mumford-prop-simple-endomorphism-classification}
\dcref{M:ch4:IV.21}
\uses{mumford-thm-rosati-positive,mumford-cor-simple-decomposition}
For simple $X$, $D=\operatorname{End}^0X$ is a division algebra with a
positive involution. If $K$ is its center, $K_0=\{x\in K:x'=x\}$,
$[D:K]=d^2$, and $[K:\mathbb Q]=e$, then $K_0$ is totally real. If
$K\ne K_0$, it is totally imaginary over $K_0$ and the involution is of the
second kind; otherwise it is of the first kind. In the nontrivial Brauer
class case of the first kind, $D$ is a quaternion division algebra.
\source{mumford-abelian-varieties:page-0204}
\source{mumford-abelian-varieties:page-0205}
\source{mumford-abelian-varieties:page-0206}
\end{proposition}
\begin{proof}
Write the real algebra of $K_0$ as
$\mathbb R^{r_1}\times\mathbb C^{r_2}$. Positivity of
$\operatorname{Tr}(xx')$ rules out complex embeddings, so $K_0$ is totally
real. If $K\ne K_0$, positivity forces the quadratic extension to be
totally imaginary. For an involution of the first kind, $D$ is identified
with its opposite algebra, so its Brauer class has order one or two. In the
order-two case its rank over $K$ is four. The canonical quaternion
involution is $x^*=\operatorname{Tr}^0_{D/K}x-x$; Skolem--Noether gives
$x'=ax^*a^{-1}$ with $a^*=\epsilon a$. Extending to the real factors,
positivity excludes $M_2(\mathbb R)$ and leaves Hamilton quaternion factors
with the corresponding positive involutions.
\end{proof}

% Source-faithful assembly: Mumford, Abelian Varieties, Chapter IV,
% Horizon transcription pages 0207--0236.

\label{mumford-IV21-classification-source}
\dcref{M:ch4:IV.21}

\begin{theorem}[Brauer groups and positive involutions]
\label{mumford-thm-positive-involution-classification}
For a division algebra $D$ with positive involution, the involution is one of
the Albert types: (I) a totally real field with identity involution; (II)
a quaternion division algebra over a totally real field with an orthogonal
involution; (III) a quaternion division algebra with its canonical
involution; or (IV) an algebra with totally imaginary quadratic center over
a totally real fixed field, with conjugation on the complex factors.
\source{mumford-abelian-varieties:page-0207}
\source{mumford-abelian-varieties:page-0208}
\source{mumford-abelian-varieties:page-0209}
\source{mumford-abelian-varieties:page-0210}
\source{mumford-abelian-varieties:page-0211}
\source{mumford-abelian-varieties:page-0212}
\source{mumford-abelian-varieties:page-0213}
\end{theorem}
\begin{proof}
For an involution of the second kind, class field theory gives
\[
0\to\operatorname{Br}(K)\to\prod_v\operatorname{Br}(K_v)
\to\mathbb Q/\mathbb Z\to0,
\]
with $\operatorname{Br}(\mathbb R)$ of order two and
$\operatorname{Br}(\mathbb C)=0$. If $\sigma$ is the involution on the
center, local invariants satisfy
$\operatorname{Inv}_v(D)+\operatorname{Inv}_{\sigma v}(D)=0$.
Skolem--Noether writes $x'=ax^*a^{-1}$, and the norm condition
$a^*a\in N_{K/K_0}K^*$ is equivalent to the existence of the involution.
For a first-kind involution, the Brauer class has order one or two; the
nontrivial case is quaternionic. Extending to the real factors, positivity
rules out $M_2(\mathbb R)$ in the canonical case and leaves Hamilton factors.
For complex factors the involution is $(X_i)\mapsto
A_i\overline{X_i}A_i^{-1}$; positivity makes $A_i$ positive definite,
and an inner change reduces to standard conjugation. These calculations give
the four listed types.
\end{proof}

\begin{proposition}[Albert numerical table]
\label{mumford-prop-albert-invariants}
For $S=\{x\in D:x'=x\}$, $\eta=\dim_{\mathbb Q}S/\dim_{\mathbb Q}D$,
and $[D:K]=d^2$, $[K_0:\mathbb Q]=e_0$, the four types have
\[
\begin{array}{c|c|c|c}
\text{type}&e&d&\eta\\ \hline
I&e_0&1&1\\ II&e_0&2&1/2\\ III&e_0&2&1/2\\ IV&2e_0&d&1/2.
\end{array}
\]
For endomorphism algebras of simple abelian varieties these invariants obey
the divisibility restrictions by $g=\dim X$.
\source{mumford-abelian-varieties:page-0212}
\source{mumford-abelian-varieties:page-0213}
% Source states the table and explicitly says the remaining restrictions are not proved here.
\notready
\end{proposition}

\section{The Riemann hypothesis}
\label{mumford-IV-rh-source}
\dcref{M:ch4:IV.21}

\begin{proposition}[Characteristic roots]
\label{mumford-prop-characteristic-root-modulus}
If $\alpha'\alpha=a\in\mathbb Z$ and $\omega_i$ are the roots of the
characteristic polynomial of $\alpha$, then $\mathbb Q[\alpha]$ is
semisimple, $|\omega_i|^2=a$, and $\omega_i\mapsto a/\omega_i$ permutes
the roots.
\source{mumford-abelian-varieties:page-0214}
\source{mumford-abelian-varieties:page-0215}
\end{proposition}
\begin{proof}
The minimal polynomial divides the characteristic polynomial and has the
same roots. The trace restricted to $\mathbb Q[\alpha]$ is positive; an
ideal and its trace-orthogonal complement split the algebra, proving
semisimplicity. Its simple factors are totally real fields or totally
imaginary quadratic extensions. The involution sends each root to its
complex conjugate, while $\alpha'\alpha=a$, hence
$a=\omega_i\overline{\omega_i}=|\omega_i|^2$.
\end{proof}

\begin{theorem}[Lang and Weil]
\label{mumford-thm-lang-frobenius-rh}
If $X_0$ is a scheme over $\mathbb F_q$ whose base change $X$ is an abelian
variety, then $X_0(\mathbb F_q)\ne\varnothing$. If $\pi$ is Frobenius and
$\omega_i$ are its characteristic roots, then
\[
\#X(\mathbb F_{q^n})=\prod_i(1-\omega_i^n),
\qquad |\omega_i|=\sqrt q,
\qquad \omega_{\pi(i)}=q/\omega_i.
\]
\source{mumford-abelian-varieties:page-0215}
\source{mumford-abelian-varieties:page-0216}
\source{mumford-abelian-varieties:page-0217}
\end{theorem}
\begin{proof}
Frobenius is the identity on the underlying space, is functorial, and has
zero differential. Write it as $\pi(x)=x_0+f(x)$. Then $1-f$ has identity
differential, hence zero-dimensional kernel and is surjective. Choose
$x_1$ with $(1-f)x_1=x_0$; then $x_1=\pi(x_1)$.
Thus $\#X(\mathbb F_{q^n})=\deg(1-\pi^n)$. After replacing the field,
choose an ample bundle; Rosati gives $\pi'\pi=q$, yielding the reciprocal
root relation and $|\omega_i|=\sqrt q$.
\end{proof}

\begin{corollary}[Weil estimate]
\label{mumford-cor-weil-point-count-estimate}
For some constant $C$,
$|\#X(\mathbb F_{q^n})-q^{ng}|\le Cq^{n(g-1/2)}$.
\source{mumford-abelian-varieties:page-0218}
\uses{mumford-thm-lang-frobenius-rh}
\end{corollary}

\begin{theorem}[Serre torsion restriction]
\label{mumford-thm-serre-torsion-restriction}
For $n\ge3$ and ample $L$, the restriction from automorphisms preserving
$L$ modulo $\operatorname{Pic}^0X$ to $\operatorname{Aut}(X_n)$ is injective.
\source{mumford-abelian-varieties:page-0218}
\end{theorem}
\begin{proof}
The characteristic roots are algebraic integers all of whose conjugates
have absolute value one, hence roots of unity. If $\alpha$ is the identity
on $X_n$, write $\alpha-1=n\beta$; the root-of-unity lemma forces
$\alpha=1$ for $n>3$.
\end{proof}

\section{The Jordan algebra of $NS^0(X)$}
\label{mumford-IV21-jordan-source}
\dcref{M:ch4:IV.21}

\begin{proposition}[Real structure of $NS^0$]
\label{mumford-prop-ns-jordan-structure}
For an ample $L$,
\[
NS^0(X)\simeq\{\alpha\in\operatorname{End}^0X:\alpha'=\alpha\}.
\]
With product $\alpha\circ\beta=(\alpha\beta+\beta\alpha)/2$, this is a
formally real Jordan algebra, a product over $\mathbb R$ of real symmetric,
complex Hermitian, and quaternionic Hermitian matrix algebras. Ample bundles
are exactly its totally positive elements.
\source{mumford-abelian-varieties:page-0219}
\source{mumford-abelian-varieties:page-0220}
\source{mumford-abelian-varieties:page-0221}
\uses{mumford-thm-ns-rosati-fixed,mumford-thm-rosati-positive}
% Source gives the application and numerical formulas but no proof in these pages.
\notready
\end{proposition}

\section{Complex multiplication and finite fields}
\label{mumford-IV22-source}
\dcref{M:ch4:IV.22}

\begin{theorem}[CM complex-torus classification]
\label{mumford-thm-cm-complex-classification}
Let $K_0$ be totally real of degree $g$ and $K$ a totally imaginary quadratic
extension. The pairs $(X,i)$ with $X/\mathbb C$ an abelian variety and
$i:K\hookrightarrow\operatorname{End}^0X$ have exactly $2^g$ isomorphism
classes up to isogeny. Representatives are
$X(K,\Phi)=(\mathbb R\otimes_{\mathbb Q}K)/A_0$, one for each of the
$2^g$ complex-algebra structures $\Phi$ on $\mathbb R\otimes K$.
\source{mumford-abelian-varieties:page-0221}
\source{mumford-abelian-varieties:page-0222}
\source{mumford-abelian-varieties:page-0223}
\source{mumford-abelian-varieties:page-0224}
\end{theorem}
\begin{proof}
The lattice $U$ is a finite-index $A_0$-module; after isogeny it is $A_0$.
The $K$-action pulls the complex structure back to a $\mathbb C$-algebra
structure $\Phi$. There are two embeddings over each real embedding of
$K_0$, hence $2^g$ structures. Choose $\alpha\in K$ with
$\alpha^2\in K_0$ and embeddings $\tau_i(\alpha)=i\beta_i$, $\beta_i>0$.
Then
\[
H(x,y)=2\sum_i\beta_i\tau_i(x)\overline{\tau_i(y)}
\]
is positive definite, and for $x,y\in A_0$,
\[
\operatorname{Im}H(x,y)=-\operatorname{Tr}_{K/\mathbb Q}(\alpha xy)\in\mathbb Z.
\]
Thus the torus is an abelian variety. An equivalence preserving the $K$-
action is $K$-linear and, after normalization, the identity; so distinct
$\Phi$ are inequivalent.
\end{proof}

\begin{theorem}[Deuring]
\label{mumford-thm-deuring-elliptic}
For an elliptic curve in characteristic $p$, non-finite-field definition is
equivalent to $\operatorname{End}^0X=\mathbb Q$. If $X$ is defined over a
finite field, its endomorphism algebra is imaginary quadratic exactly when
the $p$-rank is one; for $p$-rank zero it is the quaternion division algebra
with local invariants $\operatorname{Inv}_p=\operatorname{Inv}_\infty=1/2$
and all other finite invariants zero.
\source{mumford-abelian-varieties:page-0228}
\source{mumford-abelian-varieties:page-0229}
\source{mumford-abelian-varieties:page-0230}
\source{mumford-abelian-varieties:page-0231}
\end{theorem}
\begin{proof}
Let (A) be $p$-rank zero, (B) noncommutative endomorphism algebra, and (C)
finite-field definition with $\pi^n=p_X^m$. The classification table and
the $p$-adic Tate representation give (B)$\Rightarrow$(A). If (A) and the
algebra is commutative, cyclic Tate subgroups and quotients yield an
endomorphism with cyclic $l$-power kernel, contradicting the norm in a
number field; hence (A)$\Rightarrow$(B). Frobenius centrality gives
(A)$\Leftrightarrow$(C), and the local invariants follow from the sum of
invariants. In the non-finite-field case, a quadratic endomorphism acting
scalarly on a Tate module would have rational scalar with negative square,
impossible; hence the algebra is $\mathbb Q$.
\end{proof}

\begin{theorem}[CM over finite fields]
\label{mumford-thm-cm-finite-field-isogeny}
A simple abelian variety in characteristic $p$ is isogenous to one defined
over a finite field if and only if it is of CM type.
\source{mumford-abelian-varieties:page-0231}
% Source attributes the two implications to Tate and Grothendieck without reproducing proofs.
\notready
\end{theorem}

\begin{theorem}[Tate centralizer theorem]
\label{mumford-thm-tate-centralizer}
If $X$ is defined over a finite field $k_0$, with Frobenius $\pi$, then
\[
\operatorname{End}(X,k_0)\otimes\mathbb Q_l
=\operatorname{Cent}_{\operatorname{End}_{\mathbb Q_l}(T_lX)}(T_l\pi).
\]
\source{mumford-abelian-varieties:page-0232}
% Source introduces this as Tate's further theorem without a proof.
\notready
\end{theorem}

\section{The theta group of a line bundle}
\label{mumford-IV23-source}
\dcref{M:ch4:IV.23}

\begin{definition}[Theta group]
\label{mumford-def-theta-group}
A theta-group is an exact sequence
\[
1\to\mathbb G_m\xrightarrow{i}G\xrightarrow{\pi}K\to1
\]
where $K$ is commutative, the sequence is locally split, $i$ is a closed
immersion identifying the kernel, and $\mathbb G_m$ is central. For finite
$K$, a section identifies the underlying scheme with
$\mathbb G_m\times K$ and the group law with
\[
(\alpha,k)(\alpha',k')=(\alpha\alpha'f(k,k'),k+k'),
\]
where $f$ is a 2-cocycle, defined up to coboundary.
\source{mumford-abelian-varieties:page-0232}
\source{mumford-abelian-varieties:page-0233}
\end{definition}

\begin{proposition}[Theta commutator]
\label{mumford-prop-theta-commutator}
The commutator defines a skew-symmetric bihomomorphism
$e:K\times K\to\mathbb G_m$, and hence a homomorphism
$\gamma:K\to\widehat K$ with
$e(k,k')=\langle k,\gamma(k')\rangle$. The center of $G$ maps to
$\ker\gamma$; if $K$ is finite, the center is exactly $\mathbb G_m$ iff
$\gamma$ is an isomorphism.
\source{mumford-abelian-varieties:page-0233}
\source{mumford-abelian-varieties:page-0234}
\end{proposition}
\begin{proof}
The commutator is independent of lifts because $\mathbb G_m$ is central.
The group identities give bihomomorphy and skew-symmetry. Viewing
$(e,p_2):K\times K\to\mathbb G_m\times K$ over $K$ gives $\gamma$.
The displayed universal pairing shows that $\gamma(\pi(x))$ is trivial
exactly when $x$ commutes with every base change of every point of $G$.
\end{proof}

\begin{lemma}[Trivial theta extensions]
\label{mumford-lem-theta-extension-prime-order}
If $K$ is finite and $G$ commutative, then
$G\simeq\mathbb G_m\times K$ as a group. If $K$ has prime order, then $G$
is commutative.
\source{mumford-abelian-varieties:page-0235}
\end{lemma}
\begin{proof}
The first assertion reduces by an Ext sequence to cyclic prime-order,
$\mu_p$, and $\alpha_p$ cases; divisibility of $k^*$ splits the reduced
cases and the height-one Lie algebra calculation splits the latter cases.
For prime order, reduced cases are generated by a central subgroup and one
lift. In the infinitesimal cases the Lie algebra is abelian, so the
height-one subgroup is commutative; together with the central torus this
makes $G$ commutative.
\end{proof}

\begin{theorem}[Theta group of a line bundle]
\label{mumford-thm-line-bundle-theta-group}
For a line bundle $L$ on an abelian variety $X$, the functor of automorphisms
of $S\times L$ covering translations of $S\times X$ is represented by a
group scheme $\mathcal G(L)$, fitting into a theta-group extension
\[
1\to\mathbb G_m\to\mathcal G(L)\to K(L)\to1.
\]
\source{mumford-abelian-varieties:page-0235}
\source{mumford-abelian-varieties:page-0236}
\uses{mumford-def-theta-group}
\end{theorem}
\begin{proof}
Let $L^*$ be the complement of the zero section. Fix $P_0$ over the origin
and set $\mathcal G(L)=p^{-1}(K(L))\cap L^*$. An automorphism over a
translation $T_f$ sends $P_0$ to a morphism $S\to L^*$ over $f$, hence
factors through $\mathcal G(L)$. This gives the representing map; its
inverse is obtained by translating the fibre and using linearity. Scalar
automorphisms form $\mathbb G_m$, and the quotient is $K(L)$.
\end{proof}

% Source-faithful assembly: Mumford, Abelian Varieties, Chapter IV,
% Horizon transcription pages 0237--0246.

\label{mumford-IV23-continuation-source}
\dcref{M:ch4:IV.23}

\begin{proof}[Continuation of the theta-group theorem]
\label{mumford-proof-line-bundle-theta-group-continuation}
If two automorphisms of $S\times L$ covering the same translation have the
same image in $\mathcal G(L)$, their quotient is multiplication by a unit on
$S\times X$ restricting to $1$ over the chosen point. Since
$H^0(S\times X,\mathcal O^*)=H^0(S,\mathcal O_S^*)$, it is the identity.
Conversely, a point $\phi\in\mathcal G(L)(S)$ covers $f\in K(L)(S)$.
Locally on $S$, trivialize the line bundle $M$ in
$T_f^*(S\times L)\simeq(S\times L)\otimes p_1^*M$ and choose liftings
$\chi_i$ of the translations. Since $\mathcal G(L)$ is a principal
$\mathbb G_m$-bundle over $K(L)$, rescale $\chi_i$ by units so their images
are $\phi$. Injectivity makes the rescaled liftings agree on overlaps, hence
they glue. Therefore
$\underline{\operatorname{Aut}}(L/X)\simeq\mathcal G(L)$.
\source{mumford-abelian-varieties:page-0237}
\source{mumford-abelian-varieties:page-0238}
\end{proof}

\begin{definition}[Commutator pairing of a line bundle]
\label{mumford-def-line-bundle-commutator}
The theta group $\mathcal G(L)$ has a skew-symmetric bihomomorphism
\[
e^L:K(L)\times K(L)\to\mathbb G_m
\]
defined by its commutator. If $L\in\operatorname{Pic}^0X$, then $K(L)=X$,
so $e^L=1$ and $\mathcal G(L)$ is commutative.
\source{mumford-abelian-varieties:page-0238}
\end{definition}

\begin{proposition}[Functoriality of commutator pairings]
\label{mumford-prop-line-bundle-commutator-functorial}
For homomorphisms and line bundles as indicated,
\begin{enumerate}
\item $e^{f^*L}(x,y)=e^L(fx,fy)$;
\item $e^{L_1\otimes L_2}(x,y)=e^{L_1}(x,y)e^{L_2}(x,y)$;
\item algebraically equivalent line bundles have equal pairings;
\item $e^{L^n}(x,y)=e^L(x,ny)$ for $x\in K(L)$,
$y\in n_X^{-1}K(L)$;
\item if $x\in X_n$ and $y\in\phi_L^{-1}(X_n)$, then
$\bar e_n(x,\phi_L(y))=e^{L^n}(x,y)$.
\end{enumerate}
\source{mumford-abelian-varieties:page-0239}
\source{mumford-abelian-varieties:page-0240}
\source{mumford-abelian-varieties:page-0241}
\end{proposition}
\begin{proof}
Lift $f(x),f(y)$ to automorphisms in the theta group; their commutator
proves (1). Tensoring liftings proves (2), and (3) follows by writing
$L_1=L_2\otimes L_3$ with $L_3\in\operatorname{Pic}^0X$. For (4), after a
faithfully flat extension write $x=nz$; then
\[
e^L(nz,ny)=e^{n_X^*L}(z,y)=e^{L^{n^2}}(z,y)
=(e^{L^n}(z,y))^n=e^{L^n}(nz,y).
\]
For (5), write $y=nz$ and compare
$n_X^*(T_y^*L\otimes L^{-1})$ with
the line bundle $\operatorname{Hom}[n_X^*L,T_{ny}^*n_X^*L]$. The action of $x\in X_n$ on
the resulting nowhere-vanishing section is conjugation by the natural
translation isomorphism; this is simultaneously the Weil pairing and the
theta-group commutator.
\end{proof}

\begin{theorem}[Descent of line bundles]
\label{mumford-thm-theta-descent}
For an isogeny $\pi:X\to Y$ and a line bundle $L$ on $X$, line bundles $M$
on $Y$ with $\pi^*M\simeq L$ correspond naturally to homomorphisms
$\alpha:\ker\pi\to\mathcal G(L)$ lifting the inclusion into $X$.
Such an $M$ exists iff $\ker\pi\subset K(L)$ and
$e^L$ is trivial on $\ker\pi\times\ker\pi$.
\source{mumford-abelian-varieties:page-0242}
\uses{mumford-def-line-bundle-commutator}
\end{theorem}
\begin{proof}
This is the finite-group-scheme descent theorem applied to the action of
$\ker\pi$ on $L$. The lift is a splitting of the inverse image theta group.
That theta group splits iff it is commutative, equivalently iff the
commutator pairing is trivial.
\end{proof}

\begin{theorem}[Power criterion]
\label{mumford-thm-line-bundle-power-criterion}
For a line bundle $L$ and integer $n$, $L\simeq M^n$ for some $M$ iff
$K(L)\supset X_n$.
\source{mumford-abelian-varieties:page-0242}
\source{mumford-abelian-varieties:page-0243}
\end{theorem}
\begin{proof}
The forward implication follows from $\phi_{M^n}=n\phi_M$. Conversely,
$K(L)\supset X_n$ gives
$e^{L^n}(x,y)=e^L(x,ny)=1$ for $x,y\in X_n$. The descent criterion gives
$L^n\simeq n_X^*N$; then $(L\otimes N^{-n})^n\in\operatorname{Pic}^0X$.
Divisibility of $\operatorname{Pic}^0X$ supplies $P$ with
$L\otimes N^{-n}\simeq P^n$, hence $L\simeq(N\otimes P)^n$.
\end{proof}

\begin{lemma}[Orthogonal subgroup]
\label{mumford-lem-theta-orthogonal-subgroup}
For a skew bihomomorphism $e:K\times K\to\mathbb G_m$ and subgroup $H$,
$H^\perp$ is the kernel of $K\xrightarrow\gamma\widehat K\to\widehat H$;
equivalently it consists of points pairing trivially with every base change of
every point of $H$. If $L=\pi^*M$ and $H=\ker\pi$, then
$K(M)\simeq H^\perp/H$.
\source{mumford-abelian-varieties:page-0243}
\source{mumford-abelian-varieties:page-0244}
\end{lemma}
\begin{proof}
The kernel description is immediate from restriction of characters. Locally
on a base $S$, descent identifies $\pi x\in K(M)$ with an isomorphism of
$T_x^*L$ with $L$ commuting with the $H$-action. A lift $w$ of $x$ in
$\mathcal G(L)$ commutes with that action exactly when
$e^L(x,h)=1$ for all $h\in H$, which is $x\in H^\perp$.
\end{proof}

\begin{theorem}[Maximal isotropic subgroup]
\label{mumford-thm-maximal-isotropic-theta}
If $L$ is non-degenerate and $H\subset K(L)$ is maximal with
$e^L|_{H\times H}=1$, then $H=H^\perp$ and
\[
\operatorname{order}(H)^2=\operatorname{order}(K(L)).
\]
\source{mumford-abelian-varieties:page-0244}
\source{mumford-abelian-varieties:page-0245}
\end{theorem}
\begin{proof}
Put $Y=X/H$ and $L=\pi^*M$. Maximality means $M$ admits no nontrivial
further descent. If a non-degenerate bundle admits no descent of degree
$>1$, then $|\chi(M)|=1$: otherwise a prime-order subgroup of $K(M)$,
whose theta extension is commutative, would give a descent. Hence
$K(M)=0$ and $|\chi(M)|=1$. The orthogonal lemma gives $H=H^\perp$; and
Riemann--Roch gives
$|\chi(L)|=\operatorname{order}(H)$ and
$\chi(L)^2=\operatorname{order}(K(L))$.
\end{proof}

\begin{corollary}[Principal polarization and non-degeneracy]
\label{mumford-cor-principal-polarization-theta}
Every abelian variety is isogenous to a principally polarized one. If $L$ is
non-degenerate, then $\mathcal G(L)$ is a non-degenerate theta group.
\source{mumford-abelian-varieties:page-0245}
\source{mumford-abelian-varieties:page-0246}
\uses{mumford-thm-maximal-isotropic-theta}
\end{corollary}
\begin{proof}
Apply the theorem to an ample $L$ and descend to $X/H$; the descended bundle
has Euler characteristic one. For the second assertion, let $D$ be the
kernel of the commutator map $\gamma$. If $H=H^\perp$, then $D\subset H$ and
the image of $K(L)$ in $\widehat H$ has kernel $D$. Therefore
\[
\operatorname{order}K(L)\leq\operatorname{order}H\cdot
\operatorname{order}(\widehat H/D)=
\frac{\operatorname{order}(H)^2}{\operatorname{order}D}.
\]
Since $\operatorname{order}K(L)=\operatorname{order}(H)^2$, $D=1$.
\end{proof}

