\section{Cohomology and base change}
\label{mumford-II5}
\dcref{M:ch2:II.5}

\begin{definition}[Flatness over a base]
\label{mumford-def-f-flat}
\dcref{M:ch2:II.5}
For a morphism $f:X\to Y$ and a quasi-coherent sheaf $\cF$ on $X$, say that
$\cF$ is $f$-flat if each stalk $\cF_x$ is flat over $\cO_{Y,f(x)}$.
\notready
\end{definition}

\begin{theorem}[Coherence of proper direct images]
\label{mumford-thm-proper-direct-image-coherent}
If $f:X\to Y$ is proper between locally noetherian schemes and $\cF$ is
coherent, then each $R^pf_*\cF$ is coherent.
\dcref{M:ch2:II.5}
\notready
\end{theorem}

\begin{theorem}[Finite complex for a proper flat family]
\label{mumford-thm-grothendieck-complex}
Let $Y=\Spec A$, $f:X\to Y$ proper noetherian, and $\cF$ coherent and
$f$-flat.  There is a bounded complex $K^\bullet$ of finitely generated
projective $A$-modules such that, for every $A$-algebra $B$,
\[
H^p(X\times_Y\Spec B,\cF\otimes_A B)\simeq
H^p(K^\bullet\otimes_A B)
\]
functorially in $B$.
\dcref{M:ch2:II.5.1}
\uses{mumford-def-f-flat,mumford-thm-proper-direct-image-coherent}
\notready
\end{theorem}

\begin{lemma}[Flat replacement of a finite complex]
\label{mumford-lem-flat-complex-replacement}
Let $C^\bullet$ be a bounded complex over a noetherian ring with finitely
generated cohomology.  It admits a quasi-isomorphic complex $K^\bullet$ whose
positive terms are finite free and whose degree-zero term is flat whenever all
$C^p$ are flat.
\dcref{M:ch2:II.5}
\uses{mumford-thm-proper-direct-image-coherent}
\notready
\end{lemma}

\begin{lemma}[Flat quasi-isomorphisms survive base change]
\label{mumford-lem-flat-quasi-iso-base-change}
A quasi-isomorphism between bounded complexes of flat $A$-modules remains a
quasi-isomorphism after tensoring with every $A$-algebra.
\dcref{M:ch2:II.5}
\uses{mumford-lem-flat-complex-replacement}
\notready
\end{lemma}

\begin{theorem}[Semicontinuity and Euler characteristic]
\label{mumford-thm-semicontinuity}
For a proper morphism $f:X\to Y$ of noetherian schemes and a coherent sheaf
flat over $Y$, the function
$y\mapsto\dim_{k(y)}H^p(X_y,\cF_y)$ is upper semicontinuous, while
$\chi(\cF_y)=\sum_p(-1)^p\dim_{k(y)}H^p(X_y,\cF_y)$ is locally constant.
\dcref{M:ch2:II.5}
\uses{mumford-thm-grothendieck-complex,mumford-lem-flat-quasi-iso-base-change}
\notready
\end{theorem}

\begin{theorem}[Cohomology-and-base-change criterion]
\label{mumford-thm-base-change-criterion}
Assume $Y$ is reduced and connected, and let $K^\bullet$ be the finite complex
representing the derived pushforward.  Constancy of $\dim H^p(X_y,\cF_y)$ is equivalent to local freeness of
$R^pf_*\cF$ together with the fibrewise isomorphism
\[
 (R^pf_*\cF)\otimes k(y)\xrightarrow{\sim}H^p(X_y,\cF_y).
\]
Under these conditions the analogous map in degree $p-1$ is also an
isomorphism.
\dcref{M:ch2:II.5}
\uses{mumford-thm-grothendieck-complex,mumford-thm-semicontinuity}
\notready
\end{theorem}

\begin{corollary}[Vanishing and flat base change]
\label{mumford-cor-flat-base-change}
If $H^p(X_y,\cF_y)=0$ for every $y$, then base change in degree $p-1$ is an
isomorphism even when $Y$ is nonreduced.  If $R^kf_*\cF=0$ for $k>k_0$, then
$H^k(X_y,\cF_y)=0$ for $k>k_0$.  Finally, for a flat $A$-algebra $B$,
\[
 H^p(X\times_Y\Spec B,\cF\otimes_A B)\simeq H^p(X,\cF)\otimes_A B.
\]
\dcref{M:ch2:II.5}
\uses{mumford-thm-base-change-criterion,mumford-lem-flat-quasi-iso-base-change}
\notready
\end{corollary}

\begin{theorem}[Seesaw theorem]
\label{mumford-thm-seesaw}
Let $X$ be complete and connected, $T$ a noetherian variety, and $L$ a line
bundle on $X\times T$.  The scheme-theoretic locus
\[
 T_1=\{t\in T\mid L|_{X\times\{t\}}\simeq\cO_X\}
\]
is closed, and there is a line bundle $M$ on $T_1$ with
$L|_{X\times T_1}\simeq p_2^*M$.
\dcref{M:ch2:II.5}
\uses{mumford-thm-semicontinuity,mumford-cor-flat-base-change}
\begin{proof}
Apply the finite-complex description to $L$ and $L^{-1}$.  The simultaneous
rank-one locus for their zeroth cohomology sheaves is represented by a closed
subscheme $T_1$.  On this locus cohomology and base change make
$p_{2*}L$ invertible.  The universal evaluation map from its pullback to $L$
is an isomorphism on every geometric fibre, hence is an isomorphism by the
fibre criterion for coherent maps.  Taking $M=p_{2*}L$ gives the claim.
\end{proof}
\notready
\end{theorem}

\section{The theorem of the cube}
\label{mumford-II6}
\dcref{M:ch2:II.6}

\begin{theorem}[Theorem of the cube for varieties]
\label{mumford-thm-cube-varieties}
Let $X,Y$ be complete varieties, let $Z$ be a variety, and choose points
$x_0,y_0,z_0$.  If a line bundle $L$ on $X\times Y\times Z$ restricts
trivially to each coordinate face
$\{x_0\}\times Y\times Z$, $X\times\{y_0\}\times Z$, and
$X\times Y\times\{z_0\}$, then $L$ is trivial.
\dcref{M:ch2:II.6}
\uses{mumford-thm-seesaw}
\notready
\end{theorem}

\begin{proposition}[Picard splitting and order]
\label{mumford-prop-picard-quadratic}
For a contravariant functor $T$ from complete varieties to abelian groups, use
alternating sums of pullbacks along coordinate faces to form the cross-effects.
The projection and section maps then give a canonical splitting
\[
 T(X_0\times\cdots\times X_n)=\operatorname{im}(\alpha_T^n)\oplus
 \ker(\beta_T^n).
\]
The functor has order at most $n$ when its $(n+1)$-fold cross-effect vanishes.
For $T=\Pic$, the cube theorem is precisely the assertion that this order is
at most two.
\dcref{M:ch2:II.6}
\uses{mumford-thm-cube-varieties}
\notready
\end{proposition}

\section{Dividing varieties by finite groups}
\label{mumford-II7}
\dcref{M:ch2:II.7}

\begin{definition}[Free finite group action]
\label{mumford-def-free-finite-action}
\dcref{M:ch2:II.7}
A finite group $G$ acts freely on a variety $X$ if the map
$G\times X\to X\times X$, $(g,x)\mapsto(gx,x)$ is a closed immersion on
each component and distinct geometric points have distinct translates.
\notready
\end{definition}

\begin{theorem}[Finite quotient]
\label{mumford-thm-finite-group-quotient}
If a finite group acts on a quasi-projective variety $X$, the quotient sheaf
$X/G$ is represented by a variety and the quotient map is finite.  If the
action is free, the map is etale and $X\to X/G$ is a principal $G$-bundle in
the etale topology.
\dcref{M:ch2:II.7}
\uses{mumford-def-free-finite-action,mumford-def-abelian-variety}
\notready
\end{theorem}

\begin{proposition}[Translation quotients and isogenies]
\label{mumford-prop-translation-quotient-isogeny}
If $H\subset A$ is a finite subgroup acting by translations, then $A/H$ is an
abelian variety and the quotient map is an isogeny.  Conversely, every finite
etale isogeny is obtained this way from its kernel.
\dcref{M:ch2:II.7}
\uses{mumford-thm-finite-group-quotient,mumford-prop-multiplication-n}
\notready
\end{proposition}

\section{The dual abelian variety in characteristic zero}
\label{mumford-II8}
\dcref{M:ch2:II.8}

\begin{definition}[Algebraically trivial line bundles]
\label{mumford-def-piczero}
\dcref{M:ch2:II.8}
For a complete variety $X$, write $\Pic^0(X)$ for the connected component of
the identity in the Picard scheme, equivalently the subgroup of line bundles
algebraically equivalent to zero when the Picard scheme is represented.
\notready
\end{definition}

\begin{theorem}[Dual abelian variety in characteristic zero]
\label{mumford-thm-dual-char-zero}
For an abelian variety $A$ over a field of characteristic zero, $\Pic^0(A)$ is
represented by an abelian variety $\Adual$.  There is a normalized Poincare line
bundle $\cP$ on $A\times\Adual$, trivial on both coordinate origins, and it
represents the universal family of algebraically trivial line bundles on $A$.
\dcref{M:ch2:II.8}
\uses{mumford-def-piczero,mumford-thm-cube-varieties,mumford-thm-seesaw}
\notready
\end{theorem}

\begin{proposition}[Biduality and functoriality]
\label{mumford-prop-biduality-char-zero}
The Poincare bundle induces a canonical isomorphism $A\xrightarrow{\sim}
\widehat{\Adual}$ and reverses arrows: a homomorphism $f:A\to B$ has a
dual $\widehat f:\Bdual\to\Adual$ characterized by
$(f\times1)^*\cP_B\simeq(1\times\widehat f)^*\cP_A$.
\dcref{M:ch2:II.8}
\uses{mumford-thm-dual-char-zero}
\notready
\end{proposition}

\section{The case of the complex ground field}
\label{mumford-II9}
\dcref{M:ch2:II.9}

\begin{theorem}[Analytic description of the dual]
\label{mumford-thm-analytic-dual-comparison}
If $A(\C)=V/\Lambda$ is the analytic torus attached to a complex abelian
variety, then $\Adual(\C)$ is the torus whose lattice is dual to $\Lambda$ under
the integral pairing supplied by the Poincare bundle.  The analytic Poincare
bundle agrees with the Appell--Humbert bundle of that pairing.
\dcref{M:ch2:II.9}
\uses{mumford-cor-complex-av-torus,mumford-prop-biduality-char-zero,mumford-thm-appell-humbert}
\notready
\end{theorem}

% Source-faithful assembly: Mumford, Abelian Varieties, Chapter II,
% Sections 4--6 (pages 50--66 of the source PDF). Running headers and
% pedagogical questions/examples are omitted.

\label{mumford-source-II4}
\dcref{M:ch2:II.4}

\begin{definition}[Abelian variety]
\label{mumford-def-abelian-variety}
\dcref{M:ch2:II.4}
An abelian variety $X$ is a complete algebraic variety over an algebraically
closed field $k$ with a group law $m:X\times X\to X$ such that $m$ and the
inverse map are morphisms of varieties.
\source{mumford-abelian-varieties:page-0050}\source{mumford-abelian-varieties:page-0051}
\end{definition}

\begin{proposition}[Basic structure]
\label{mumford-source-basic-structure}
\dcref{M:ch2:II.4}
If $g=\dim X$, then
\[
 X_n\simeq(\mathbf Z/n\mathbf Z)^{2g}\quad(\operatorname{char}k\nmid n),
 \qquad X_{p^m}\simeq(\mathbf Z/p^m\mathbf Z)^i
\]
for $p=\operatorname{char}k$, where $0\le i\le g$; $X$ is commutative and
divisible. Moreover
\[
 H^q(X,\Omega^p)\simeq\bigwedge^p H^1(X,\Omega^1)\otimes_k
 \bigwedge^q H^1(X,\mathcal O_X),
\quad \dim H^1(X,\mathcal O_X)=\dim H^0(X,\Omega^1)=g.
\]
\source{mumford-abelian-varieties:page-0050}
\end{proposition}

\begin{lemma}[Translations]
\label{mumford-lem-abelian-translations}
\dcref{M:ch2:II.4}
For every $a\in X$, the translation $T_a(x)=a+x$ is an automorphism of $X$;
its inverse is $T_{-a}$.  Consequently, local geometric properties are
preserved by translation.
\source{mumford-abelian-varieties:page-0052}\source{mumford-abelian-varieties:page-0053}
\uses{mumford-def-abelian-variety}
\end{lemma}
\begin{proof}
The group identities give $T_{-a}\circ T_a=T_a\circ T_{-a}=\operatorname{id}$,
and both maps are morphisms because the group law and inverse are morphisms.
\end{proof}

\begin{proposition}[Fundamental group and free finite quotients]
\label{mumford-source-II4-roadmap}
\dcref{M:ch2:II.4}
If $g=\dim X$ and $p=\operatorname{char}k$, then the algebraic fundamental group
has the expected form
\[
 \pi_1(X)\simeq\prod_\ell(\mathbf Z_\ell)^{2g}\quad(p=0),\qquad
 \pi_1(X)\simeq\prod_{\ell\ne p}(\mathbf Z_\ell)^{2g}\times\mathbf Z_p^i
 \quad(p>0),
\]
where $i$ is the $p$-rank.  More generally, if a finite group acts freely on a
variety $Y$ with quotient $X$, then some $n>0$ and homomorphisms fit into
\[
\begin{array}{ccccc}&&Y&&\\[-2pt]&\swarrow&&\searrow&\\[-2pt]
X&&\xrightarrow{\,n_X\,}&&X.
\end{array}
\]
The variety $Y$ carries an abelian-variety structure for which both maps are
homomorphisms.
\source{mumford-abelian-varieties:page-0050}\source{mumford-abelian-varieties:page-0051}
% Source states this roadmap result on pp. 50--51 but gives no proof there.
\notready
\end{proposition}

\begin{lemma}[Everywhere nonsingular]
\label{mumford-source-nonsingular}
\dcref{M:ch2:II.4}
An abelian variety is everywhere nonsingular.
\source{mumford-abelian-varieties:page-0052}
\end{lemma}
\begin{proof}
There is a nonsingular point $x_0$. For $x\in X$, the translation morphism
$T_{(x,x_0^{-1})}(y)=x\cdot x_0^{-1}\cdot y$ is an automorphism carrying
$x_0$ to $x$, so $x$ is nonsingular.
\end{proof}

\begin{theorem}[First commutativity proof]
\label{mumford-source-commutativity-I}
\dcref{M:ch2:II.4}
An abelian variety is commutative.
\source{mumford-abelian-varieties:page-0052}
\end{theorem}
\begin{proof}
For $x\in X$, conjugation $C_x(y)=xyx^{-1}$ induces an automorphism
$C^*_{x,n}$ of $\mathcal O_{X,e}/\mathfrak m_{X,e}^n$. The map
$X\to\operatorname{Aut}(\mathcal O_{X,e}/\mathfrak m_{X,e}^n)$ is a morphism
to an affine variety, hence constant because $X$ is complete and connected.
It equals the identity at $e$. Thus $C^*_{x,n}=1$ for every $n$; since
$\bigcap_n\mathfrak m_{X,e}^n=0$, $C_x$ is the identity near $e$, hence on
the irreducible variety $X$.
\end{proof}

We write the group law additively. Let $T_x(y)=x+y$ and let $n_X$ denote
multiplication by $n$.
\source{mumford-abelian-varieties:page-0052}\source{mumford-abelian-varieties:page-0053}

\begin{proposition}[Invariant differentials]
\label{mumford-source-invariant-differentials}
\dcref{M:ch2:II.4}
If $T=T_{X,0}$ and $\Omega_0=T^*_{X,0}$, then
\[
 \Omega_0\otimes_k\mathcal O_X\xrightarrow{\sim}\Omega_X^1.
\]
Every regular differential form on $X$ is translation invariant.
\source{mumford-abelian-varieties:page-0053}
\end{proposition}
\begin{proof}
For $\theta\in\Omega_0$, define $\omega_\theta$ by
$(\omega_\theta)_x=T^*_{-x}(\theta)$. This is regular and gives the map.
At each $x$, $T^*_{-x}$ identifies the fiber with $\Omega_0$, so Nakayama's
lemma proves it is an isomorphism. Since $H^0(X,\mathcal O_X)=k$, the claim
about global forms follows.
\end{proof}

\begin{theorem}[Prime-to-characteristic multiplication]
\label{mumford-prop-multiplication-n}
\dcref{M:ch2:II.4}
For every $n$ not divisible by $\operatorname{char}k$, $n_X$ is surjective.
\source{mumford-abelian-varieties:page-0053}\source{mumford-abelian-varieties:page-0054}
\end{theorem}
\begin{proof}
The tangent space at $(0,0)$ splits as $T\oplus T$, and the differential of
$m$ is addition: $d(m)(t_1,t_2)=t_1+t_2$, since the restrictions to the two
summands are the identity. Induction gives $(dn_X)_0=n$ on $T$. Thus it is an
isomorphism when $\operatorname{char}k\nmid n$. If $n_X$ were not surjective,
the dimension theorem would give a nonzero tangent vector to
$n_X^{-1}(0)$ at $0$, contradicting injectivity of $(dn_X)_0$.
\end{proof}

\begin{lemma}[Rigidity Lemma, Form I]
\label{mumford-lem-rigidity-form-I}
\dcref{M:ch2:II.4}
Let $X$ be complete, $Y,Z$ varieties, and $f:X\times Y\to Z$ a morphism such
that $f(X\times\{y_0\})=\{z_0\}$. Then $f=g\circ p_2$ for a morphism
$g:Y\to Z$.
\source{mumford-abelian-varieties:page-0054}
\end{lemma}
\begin{proof}
Choose $x_0\in X$ and set $g(y)=f(x_0,y)$. Let $U$ be an affine neighborhood
of $z_0$, $F=Z-U$, and $G=p_2(f^{-1}(F))$. Since $X$ is complete, $G$ is
closed; since $y_0\notin G$, $V=Y-G$ is nonempty open. For $y\in V$, the
complete variety $X\times\{y\}$ maps into affine $U$, hence to one point.
Thus $f(x,y)=f(x_0,y)=g(p_2(x,y))$ on a nonempty open, and therefore everywhere.
\end{proof}

\begin{corollary}[Morphisms are homomorphisms up to translation]
\label{mumford-cor-morphism-translation}
\dcref{M:ch2:II.4}
If $X,Y$ are abelian varieties and $f:X\to Y$ is a morphism, then
$f(x)=h(x)+a$ for a homomorphism $h$ and $a\in Y$.
\source{mumford-abelian-varieties:page-0054}
\uses{mumford-lem-rigidity-form-I}
\end{corollary}
\begin{proof}
Replace $f$ by $f-f(0)$. The morphism
$\phi(x,y)=f(x+y)-f(y)-f(x)$ vanishes on both coordinate axes. Rigidity gives
$\phi=0$, so $f$ is a homomorphism.
\end{proof}

\begin{corollary}[Second commutativity proof]
\label{mumford-cor-abelian-commutative}
\dcref{M:ch2:II.4}
An abelian variety is commutative.
\source{mumford-abelian-varieties:page-0055}
\uses{mumford-cor-morphism-translation}
\end{corollary}
\begin{proof}
The inverse map is a homomorphism by the preceding corollary. Hence
$(xy)^{-1}=x^{-1}y^{-1}=y^{-1}x^{-1}$, so $X$ is commutative.
\end{proof}

\begin{corollary}[Linearity of maps into an abelian variety]
\label{mumford-cor-pointed-hom-linear}
\dcref{M:ch2:II.4}
For pointed complete varieties $S,T$ and an abelian variety $X$,
\[
 \Hom(S,X)\times\Hom(T,X)\xrightarrow{\sim}\Hom(S\times T,X),
 \qquad(f,g)\mapsto[(s,t)\mapsto f(s)+g(t)].
\]
\source{mumford-abelian-varieties:page-0055}
\end{corollary}
\begin{proof}
Injectivity follows by setting either variable equal to its base point. Given
$h$, set $f(s)=h(s,t_0)$, $g(t)=h(s_0,t)$ and
$k(s,t)=h(s,t)-f(s)-g(t)$. Rigidity applied to $k$ gives $k=0$.
\end{proof}

\begin{theorem}[Recognition criterion]
\label{mumford-thm-unital-composition}
\dcref{M:ch2:II.4}
Let $X$ be complete, $e\in X$, and $m:X\times X\to X$ satisfy
$m(x,e)=m(e,x)=x$. Then $m$ is an abelian-variety group law with identity $e$.
\source{mumford-abelian-varieties:page-0055}\source{mumford-abelian-varieties:page-0056}
\end{theorem}
\begin{proof}
Write $xy=m(x,y)$ and define $\psi(x,y)=(xy,y)$. Since
$\psi^{-1}(e,e)=\{(e,e)\}$, the dimension theorem and completeness make
$\psi$ surjective. Let $\Gamma'$ be $\{(x,y):xy=e\}$, choose an irreducible
component $\Gamma$ projecting onto the second factor, and then onto the first
factor by the dimension theorem. Rigidity applied to
$\phi((x',x),y)=x'(xy)$ gives
\[
 x'(xy)=y\quad((x',x)\in\Gamma).
 \tag{1}
\]
Choosing $(x'',x')\in\Gamma$ and using (1) shows also $xx'=e$.

Apply rigidity to $\chi(((x',x),y,z))=x'((xy)z)$ to obtain
$x'((xy)z)=yz$. Multiplying on the left by $x'$ and using (1) gives
$(x'y)z=x'(yz)$. Since $x'$ is arbitrary, multiplication is associative.
Translations are then automorphisms, so $X$ is nonsingular; $\psi$ is
bijective. Its tangent map at $(e,e)$ is an isomorphism, so it is inseparable
and, by Zariski's Main Theorem, an isomorphism. Its inverse is
$(x,y)\mapsto(xy^{-1},y)$, proving that inversion is a morphism.
\end{proof}

\section{Cohomology and base change}
\label{mumford-source-II5}
\dcref{M:ch2:II.5}

\begin{theorem}[Coherence of proper direct images]
\label{mumford-thm-proper-direct-image-coherent}
\dcref{M:ch2:II.5}
If $f:X\to Y$ is proper between locally noetherian preschemes and $\mathcal F$
is coherent, then $R^pf_*\mathcal F$ is coherent for all $p\ge0$.
\source{mumford-abelian-varieties:page-0057}
% Source explicitly takes this coherence theorem as a basic result; no proof is given.
\notready
\end{theorem}

\begin{definition}[Flat over the base]
\label{mumford-def-f-flat}
\dcref{M:ch2:II.5}
A quasicoherent $\mathcal F$ on $X$ is $f$-flat if every $\mathcal F_x$ is
$\mathcal O_{Y,f(x)}$-flat; equivalently, sections over affine $U$ mapping into
affine $V$ are flat $\mathcal O_Y(V)$-modules.
\source{mumford-abelian-varieties:page-0057}
\end{definition}

\begin{theorem}[Cohomology and base change complex]
\label{mumford-thm-grothendieck-complex}
\dcref{M:ch2:II.5}
For proper $f:X\to Y$ with $Y=\Spec A$, $X$ noetherian, and coherent
$\mathcal F$ flat over $Y$, there is a finite complex $K^\bullet$ of finitely generated
projective $A$-modules such that, functorially for every $A$-algebra $B$,
\[
 H^p(X\times_Y\Spec B,\mathcal F\otimes_A B)
 \simeq H^p(K^\bullet\otimes_A B).
\]
\source{mumford-abelian-varieties:page-0057}\source{mumford-abelian-varieties:page-0058}\source{mumford-abelian-varieties:page-0059}\source{mumford-abelian-varieties:page-0060}
\end{theorem}
\begin{proof}
Choose a finite affine covering and its Cech complex $C^\bullet$. It is a
finite complex of flat $A$-modules and base change identifies its cohomology
with the fiber cohomology. Lemma~\ref{mumford-source-complex-model} supplies
a finite complex $K^\bullet$ of finite modules, free in positive degrees,
quasi-isomorphic to $C^\bullet$, with $K^0$ flat. Since $A$ is noetherian,
$K^0$ is projective.

For completeness, the construction descends on $m$: choose a free module
mapping onto the kernel of $\ker\partial^{m+1}\to H^{m+1}(C^\bullet)$ and a
free module mapping onto $H^m(C^\bullet)$, lift the latter to cycles, and
take their direct sum. At $m=-1$ quotient $K^0$ by
$\ker\partial^0\cap\ker\phi_0$. The mapping cylinder
$L^p=K^p\oplus C^{p-1}$ is exact; if all $C^p$ are flat, the short exact
sequences $0\to Z^p\to L^p\to Z^{p+1}\to0$ show $K^0=L^0$ is flat.

Lemma~\ref{mumford-lem-flat-quasi-iso-base-change} applied to $K^\bullet\to C^\bullet$
shows that base change preserves the quasi-isomorphism, proving the claim.
\end{proof}

\begin{lemma}[Finite complex model]
\label{mumford-source-complex-model}
\dcref{M:ch2:II.5}
Let $C^\bullet$ be bounded over a noetherian ring $A$, with finitely generated
cohomology. There is a bounded complex $K^\bullet$ of finite modules, free in
positive degrees, mapping quasi-isomorphically to $C^\bullet$; if $C^p$ are
flat, $K^0$ is flat.
\source{mumford-abelian-varieties:page-0058}\source{mumford-abelian-varieties:page-0059}\source{mumford-abelian-varieties:page-0060}
\end{lemma}
\begin{proof}
Construct $K^\bullet$ by descending induction. Put $K^p=0$ for $p>n$.
Assume the maps have been constructed above degree $m$ so that they induce
cohomology isomorphisms above degree $m+1$ and a surjection
$\ker\partial^{m+1}\to H^{m+1}(C^\bullet)$. For $m\ge0$, let
$B^{m+1}$ be the kernel of this surjection. Choose a finite free ${K'}^m$
surjecting onto $B^{m+1}$, and a finite free ${K''}^m$ surjecting onto
$H^m(C^\bullet)$; lift the latter map to cycles. Set
$K^m={K'}^m\oplus{K''}^m$, let the differential vanish on ${K''}^m$ and
map ${K'}^m$ onto $B^{m+1}$, and lift this map to $C^m$. The resulting map
of complexes has the required cohomology properties. For $m=-1$, replace
$K^0$ by $K^0/(\ker\partial^0\cap\ker\phi_0)$.

If all $C^p$ are flat, form the mapping cylinder
$L^p=K^p\oplus C^{p-1}$ with
$\partial(x,0)=(\partial x,\phi(x))$ and
$\partial(0,y)=(0,-\partial y)$. The exact sequence of complexes with the
shifted $C^\bullet$ shows $H^p(L^\bullet)=0$. Hence
$0\to K^0=L^0\to L^1\to\cdots\to L^{n+1}\to0$ is exact; its other terms
are flat, so $K^0$ is flat.
\end{proof}

\begin{lemma}[Flat complexes commute with arbitrary base change]
\label{mumford-lem-flat-quasi-iso-base-change}
\dcref{M:ch2:II.5}
If finite complexes of flat $A$-modules are quasi-isomorphic, then their
cohomologies remain isomorphic after tensoring with every $A$-algebra $B$.
\source{mumford-abelian-varieties:page-0060}
\end{lemma}
\begin{proof}
Construct the mapping cylinder $L^\bullet$ of the quasi-isomorphism. It is an
exact finite complex of flat modules. Its cycles $Z^p$ are flat, and
\[
0\to Z^p\to L^p\to Z^{p+1}\to0
\]
is exact. Tensoring with $B$ remains exact, so $L^\bullet\otimes_A B$ is
exact. It is the mapping cylinder after base change; the cohomology sequence
therefore gives the required isomorphisms.
\end{proof}

\begin{corollary}[Semicontinuity and Euler characteristic]
\label{mumford-thm-semicontinuity}
\dcref{M:ch2:II.5}
For proper $f:X\to Y$ and coherent $\mathcal F$ flat over $Y$, the function
$y\mapsto\dim_{k(y)}H^p(X_y,\mathcal F_y)$ is upper semicontinuous, while
$y\mapsto\chi(\mathcal F_y)$ is locally constant.
\source{mumford-abelian-varieties:page-0061}
\end{corollary}
\begin{proof}
Locally choose the free complex $K^\bullet$ and write $d^p:K^p\to K^{p+1}$.
Then
\[
\dim H^p=\dim K^p\otimes k(y)-\dim\operatorname{Im}(d^p\otimes k(y))
 -\dim\operatorname{Im}(d^{p-1}\otimes k(y)).
\]
The alternating sum is locally constant. The image rank is lower
semicontinuous because its rank-drop locus is cut out by the entries of the
induced exterior-power matrix, proving upper semicontinuity.
\end{proof}

\begin{corollary}[Base-change criterion]
\label{mumford-thm-base-change-criterion}
\dcref{M:ch2:II.5}
If $Y$ is reduced and connected, constancy of
$y\mapsto\dim H^p(X_y,\mathcal F_y)$ is equivalent to $R^pf_*\mathcal F$
being locally free and having fibers $H^p(X_y,\mathcal F_y)$. Under these
conditions the same base-change map is an isomorphism in degree $p-1$.
\source{mumford-abelian-varieties:page-0061}\source{mumford-abelian-varieties:page-0062}\source{mumford-abelian-varieties:page-0063}
\end{corollary}
\begin{proof}
First, on a reduced scheme, a coherent sheaf with constant fiber dimension
$r$ is locally free of rank $r$: lift generators at a point, apply Nakayama,
and observe that the kernel lies in $\mathfrak m_y\mathcal O_y^r$ at every
point, hence vanishes on a reduced scheme. Second, if
$\phi:\mathscr F\to\mathfrak D$ is a map of locally free sheaves with
locally constant image rank, the preceding result makes the cokernel locally
free. Thus the image is projective and both source and target split, with
matrix $\left[\begin{smallmatrix}0&\text{isom.}\\0&0\end{smallmatrix}\right]$.
Applying the splitting to $d_{p-1}$ and $d_p$ in $K^\bullet$ gives projective
modules $B_p,H_p,K'_p$ with
$B_p\oplus H_p=\ker d_p$ and $d_p:K'_p\simeq B_{p+1}$. Hence
$H^p(K^\bullet\otimes B)=H_p\otimes B=H^p(K^\bullet)\otimes B$ and likewise
in degree $p-1$.
\end{proof}

\begin{corollary}[Vanishing in the preceding degree]
\label{mumford-source-base-change-vanishing}
\dcref{M:ch2:II.5}
If $H^p(X_y,\mathcal F_y)=0$ for all $y$, then
$R^{p-1}f_*\mathcal F\otimes k(y)\simeq H^{p-1}(X_y,\mathcal F_y)$ for all $y$.
\source{mumford-abelian-varieties:page-0064}
\end{corollary}
\begin{proof}
Locally write the relevant part of $K^\bullet$ as
$K^{p-1}\to K^p\to K^{p+1}$. Exactness after tensoring with $k(y)$ permits
a splitting $K^p\otimes k(y)=\overline W_1\oplus\overline W_2$, where the
first summand is the image and the second maps injectively. After localizing
at a function nonzero at $y$, lift bases to a splitting $K^p=W_1\oplus W_2$
with $W_1\subset\operatorname{Im}d^{p-1}$; injectivity on $W_2$ persists,
so $W_1=\operatorname{Im}d^{p-1}$. The surjection onto $W_1$ splits, giving
$K^{p-1}=\ker d^{p-1}\oplus W_1$ and exact sequences
\[
 K^{p-2}\to\ker d^{p-1}\to H^{p-1}(X,\mathcal F)\to0,
\quad
 K^{p-2}\otimes k(y)\to\ker d^{p-1}\otimes k(y)\to
 H^{p-1}(X_y,\mathcal F_y)\to0.
\]
This proves the asserted base-change isomorphism.
\end{proof}

\begin{corollary}[Higher vanishing]
\label{mumford-source-higher-vanishing}
\dcref{M:ch2:II.5}
If $R^kf_*\mathcal F=0$ for $k>k_0$, then $H^k(X_y,\mathcal F_y)=0$ for
$k>k_0$ and all $y$.
\source{mumford-abelian-varieties:page-0064}
\end{corollary}
\begin{proof}
Apply the preceding vanishing-in-the-preceding-degree corollary and use
decreasing induction on $k_0$.
\end{proof}

\begin{corollary}[Flat base change]
\label{mumford-cor-flat-base-change}
\dcref{M:ch2:II.5}
If $B$ is flat over $A$, then
\[
 H^p(X\times_Y\Spec B,\mathcal F\otimes_A B)\simeq H^p(X,\mathcal F)\otimes_A B.
\]
\source{mumford-abelian-varieties:page-0064}\source{mumford-abelian-varieties:page-0065}
\end{corollary}
\begin{proof}
For a flat algebra, cohomology of any complex commutes with tensor product.
\end{proof}

\begin{theorem}[Seesaw theorem, provisional form]
\label{mumford-thm-seesaw}
\dcref{M:ch2:II.5}
For complete $X$, any variety $T$, and a line bundle $L$ on $X\times T$, the
set of $t$ for which $L|_{X\times\{t\}}$ is trivial is closed. On this closed
set $T_1$, $L|_{X\times T_1}\simeq p_2^*M$ for a line bundle $M$ on $T_1$.
\source{mumford-abelian-varieties:page-0065}\source{mumford-abelian-varieties:page-0066}
\uses{mumford-thm-base-change-criterion}
\end{theorem}
\begin{proof}
A line bundle $M$ on complete $X$ is trivial iff both $H^0(X,M)$ and
$H^0(X,M^{-1})$ are nonzero: dual nonzero sections compose to a nonzero
constant, giving inverse isomorphisms. Thus $T_1$ is the intersection of the
two closed loci supplied by semicontinuity. After replacing $T$ by $T_1$,
all fibers are trivial and have one-dimensional $H^0$. Base-change criterion
gives $p_{2*}\underline L=\underline M$ invertible and the natural map
$p_2^*\underline M\to\underline L$ is an isomorphism.
\end{proof}

\section{The theorem of the cube: I}
\label{mumford-source-II6}
\dcref{M:ch2:II.6}

\begin{theorem}[Theorem of the cube]
\label{mumford-thm-cube-varieties}
\dcref{M:ch2:II.6}
Let $X,Y$ be complete varieties, $Z$ any variety, with base points
$x_0,y_0,z_0$. If a line bundle $L$ on $X\times Y\times Z$ restricts
trivially to each of $\{x_0\}\times Y\times Z$,
$X\times\{y_0\}\times Z$, and $X\times Y\times\{z_0\}$, then $L$ is trivial.
\source{mumford-abelian-varieties:page-0066}
% The source proof is assembled in ch02-source-part3.tex from pp. 67--70.
\end{theorem}

\begin{remark}[Functorial order]
\label{mumford-source-functor-order}
\dcref{M:ch2:II.6}
For a contravariant functor $T$ on complete varieties, define projections
$\pi_i$ and base-point inclusions $\sigma_i$ by omitting and restoring the
$i$th factor. Then
\[
 \alpha_T^n(\xi_0,\ldots,\xi_n)=\sum_{i=0}^n\pi_i^*(\xi_i),
 \qquad
 \beta_T^n(\eta)=(\sigma_0^*\eta,\sigma_2^*\eta,\ldots,\sigma_n^*\eta),
\]
and induction gives $T(\prod X_i)=\operatorname{Im}\alpha\oplus\ker\beta$.
The functor has order $n$ when $\alpha$ is surjective (equivalently $\beta$
injective). The cube theorem, when $Z$ is complete, says that $\Pic X$ is
quadratic.
\source{mumford-abelian-varieties:page-0066}
\end{remark}

\label{mumford-III10}
\dcref{M:ch3:III.10}

\begin{theorem}[Scheme-theoretic cube theorem]
\label{mumford-thm-cube-schemes}
\dcref{M:ch3:III.10}
Let $X$ and $Y$ be complete varieties, let $Z$ be a connected $k$-scheme with
a chosen section $z_0:\Spec k\to Z$, and let $L$ be a line bundle on
$X\times Y\times Z$.  If the restrictions to
\[
 \{x_0\}\times Y\times Z,\qquad X\times\{y_0\}\times Z,
 \qquad X\times Y\times\{z_0\}
\]
are trivial for chosen base points, then $L$ is trivial.  The proof uses the
maximal closed triviality locus and a nilpotent local-ring argument; the
conclusion is stable under base change that preserves the chosen section.
\uses{mumford-thm-cube-varieties,mumford-thm-seesaw}
\notready
\end{theorem}

\begin{proposition}[Theorem of the square]
\label{mumford-prop-square}
\dcref{M:ch3:III.10}
For an abelian variety $A$ and a line bundle $L$, the rule
\[
 \phi_L(x)=t_x^*L\otimes L^{-1}
\]
defines a homomorphism $\phi_L:A\to\Adual$.  Equivalently,
\[
 t_{x+y}^*L\otimes t_x^*L^{-1}\otimes t_y^*L^{-1}\otimes L
\simeq\cO_A
\]
functorially in $x,y$.
\uses{mumford-thm-cube-schemes,mumford-thm-dual-any-characteristic}
\notready
\end{proposition}

\begin{definition}[Biextension attached to a line bundle]
\label{mumford-def-biextension}
\dcref{M:ch3:III.10}
The line bundle
\[
 \mathcal B_L=m^*L\otimes p_1^*L^{-1}\otimes p_2^*L^{-1}
\]
on $A\times A$ is the biextension associated with $L$.  The cube theorem
gives its additivity in each variable and hence the homomorphism $\phi_L$.
\uses{mumford-prop-square}
\notready
\end{definition}

\section[Group schemes]{Basic theory of group schemes}
\label{mumford-III11}
\dcref{M:ch3:III.11}

\begin{definition}[Group scheme and $S$-points]
\label{mumford-def-group-scheme}
\dcref{M:ch3:III.11}
A group scheme over $k$ is a $k$-scheme $G$ with morphisms
$m:G\times G\to G$, $e:\Spec k\to G$, and $i:G\to G$ satisfying the group
identities as equalities of morphisms.  For every $k$-scheme $S$, the set
$G(S)=\Hom_k(S,G)$ is then a group functorially in $S$.
\notready
\end{definition}

\begin{lemma}[Kernels and subgroup schemes]
\label{mumford-lem-group-scheme-kernel}
\dcref{M:ch3:III.11}
The fibre over the identity of a homomorphism of group schemes is a closed
subgroup scheme.  Formation of this kernel commutes with base change, and a
homomorphism is a monomorphism precisely when its kernel is trivial as a
functor.
\uses{mumford-def-group-scheme}
\notready
\end{lemma}

\begin{proposition}[Invariant differentials and Lie algebra]
\label{mumford-prop-group-scheme-lie}
\dcref{M:ch3:III.11}
For a group scheme $G$ of finite type, translation identifies all tangent
spaces with $\Lie(G)=T_eG$.  Every tangent vector at the identity extends
uniquely to a left-invariant derivation; these derivations form the Lie algebra
of $G$, and a homomorphism induces a Lie-algebra map by its differential.  In
positive characteristic the differential alone does not determine the global
homomorphism (the Frobenius is the standard warning).
\uses{mumford-def-group-scheme,mumford-lem-group-scheme-kernel}
\notready
\end{proposition}

\begin{proposition}[Standard finite group schemes]
\label{mumford-prop-standard-finite-groups}
\dcref{M:ch3:III.11}
The group schemes $\Gm$, $\Ga$, $\mu_n=\Spec k[T]/(T^n-1)$, and
$\alpha_p=\Spec k[T]/(T^p)$ in characteristic $p$ are determined by their
Hopf algebras.  In characteristic $p$, $\mu_p$ and $\alpha_p$ are finite and
nonreduced, while $\Z/p\Z$ is etale.
\uses{mumford-def-group-scheme}
\notready
\end{proposition}

\begin{theorem}[Smoothness of an abelian variety]
\label{mumford-thm-abelian-smooth}
\dcref{M:ch3:III.11}
Every abelian variety is a smooth connected commutative group scheme.  Its
translation action makes the sheaf of differentials free, and
$\dim\Lie(A)=\dim A$.
\uses{mumford-def-abelian-variety,mumford-prop-group-scheme-lie,mumford-cor-abelian-commutative}
\notready
\end{theorem}

\begin{proposition}[Multiplication kernels in characteristic $p$]
\label{mumford-prop-p-rank}
\dcref{M:ch3:III.11}
For an abelian variety $A$ of dimension $g$ in characteristic $p>0$,
$A[p](\bar k)$ is isomorphic to $(\Z/p\Z)^f$ for an integer
$0\leq f\leq g$, called the $p$-rank.  The finite group scheme $A[p]$ has
rank $p^{2g}$ and carries a canonical connected--etale exact sequence.  A
product decomposition requires an additional splitting hypothesis.
\uses{mumford-prop-multiplication-n,mumford-thm-abelian-smooth}
\notready
\end{proposition}

\section{Quotients by finite group schemes}
\label{mumford-III12}
\dcref{M:ch3:III.12}

\begin{definition}[Finite group-scheme action]
\label{mumford-def-group-scheme-action}
\dcref{M:ch3:III.12}
An action of a finite group scheme $G$ on a scheme $X$ is a morphism
$G\times X\to X$ satisfying the unit and associativity diagrams.  It is free
if the graph map $G\times X\to X\times X$ is a monomorphism.
\uses{mumford-def-group-scheme}
\notready
\end{definition}

\begin{theorem}[Finite group-scheme quotient]
\label{mumford-thm-finite-groupscheme-quotient}
If a finite group scheme $G$ acts on a quasi-projective scheme $X$ with affine
orbits, the fppf quotient sheaf $X/G$ is represented by a scheme and
$X\to X/G$ is finite.  If the action is free, this map is a finite locally
free $G$-torsor; only in that torsor case does faithfully flat descent identify
quasi-coherent sheaves on the quotient with $G$-equivariant sheaves on $X$.
\dcref{M:ch3:III.12}
\uses{mumford-def-group-scheme-action,mumford-lem-group-scheme-kernel}
\notready
\end{theorem}

\begin{proposition}[Quotient of an abelian variety]
\label{mumford-prop-abelian-quotient}
\dcref{M:ch3:III.12}
If $H\subset A$ is a finite subgroup scheme, then the quotient $A/H$ is an
abelian variety and the quotient morphism $q:A\to A/H$ is a finite flat
homomorphism with kernel $H$.  Every finite flat homomorphism of abelian
varieties is obtained in this way.
\uses{mumford-thm-finite-groupscheme-quotient,mumford-thm-abelian-smooth}
\notready
\end{proposition}

\begin{theorem}[Isogeny factorization]
\label{mumford-thm-isogeny-factorization}
\dcref{M:ch3:III.12}
For an isogeny $f:A\to B$, there is an isogeny $g:B\to A$ and an integer
$n>0$ with $g\circ f=[n]_A$ and $f\circ g=[n]_B$.  Thus isogenies become
isomorphisms after tensoring Hom groups with $\Q$.
\uses{mumford-prop-abelian-quotient,mumford-prop-multiplication-n}
\notready
\end{theorem}

\section{The dual abelian variety in any characteristic}
\label{mumford-III13}
\dcref{M:ch3:III.13}

\begin{definition}[The stabilizer group scheme of a line bundle]
\label{mumford-def-KL}
\dcref{M:ch3:III.13}
For a line bundle $L$ on an abelian variety $A$, define the closed subgroup
scheme
\[
 K(L)(S)=\{x\in A(S)\mid t_x^*L_S\simeq L_S\}
\]
for every $k$-scheme $S$.
\uses{mumford-def-abelian-variety,mumford-lem-group-scheme-kernel}
\notready
\end{definition}

\begin{proposition}[The homomorphism attached to $L$]
\label{mumford-prop-phi-L}
\dcref{M:ch3:III.13}
The assignment $x\mapsto t_x^*L\otimes L^{-1}$ is a homomorphism
$\phi_L:A\to\Adual$ and its scheme-theoretic kernel is $K(L)$.
\uses{mumford-def-KL,mumford-prop-square}
\notready
\end{proposition}

\begin{theorem}[Representability of the dual]
\label{mumford-thm-dual-any-characteristic}
For every abelian variety $A$ over an algebraically closed field, the functor
of algebraically trivial line bundles rigidified at the origin is represented
by an abelian variety $\Adual$.  It carries a universal normalized Poincare line
bundle $\cP$ on $A\times\Adual$, and the construction is compatible with base
change.
\dcref{M:ch3:III.13}
\uses{mumford-def-KL,mumford-prop-abelian-quotient,mumford-thm-cube-schemes}
\notready
\end{theorem}

\begin{proposition}[Biduality in arbitrary characteristic]
\label{mumford-prop-biduality-any-characteristic}
\dcref{M:ch3:III.13}
The Poincare bundle gives a canonical isomorphism $A\simeq\widehat{\Adual}$;
for $f:A\to B$, the dual morphism $\widehat f:\Bdual\to\Adual$ is compatible
with composition, products, and base change.
\uses{mumford-thm-dual-any-characteristic}
\notready
\end{proposition}

\section[Cartier duality]{Duality of finite commutative group schemes}
\label{mumford-III14}
\dcref{M:ch3:III.14}

\begin{definition}[Cartier dual]
\label{mumford-def-cartier-dual}
\dcref{M:ch3:III.14}
For a finite commutative group scheme $G$, its Cartier dual is
$G^D=\underline{\Hom}(G,\Gm)$.  It represents multiplicative characters and
comes with a universal perfect pairing $G\times G^D\to\Gm$.
\notready
\end{definition}

\begin{theorem}[Cartier biduality]
\label{mumford-thm-cartier-biduality}
For finite commutative $G$, the evaluation map $G\to G^{DD}$ is an
isomorphism.  Cartier duality is exact on finite commutative group schemes and
interchanges etale and multiplicative-type parts.
\dcref{M:ch3:III.14}
\uses{mumford-def-cartier-dual}
\notready
\end{theorem}

\begin{proposition}[Weil pairing]
\label{mumford-prop-weil-pairing}
\dcref{M:ch3:III.14}
If $n$ is invertible in $k$, the commutative group scheme $A[n]$ has a perfect
alternating pairing
\[
 e_n:A[n]\times\Adual[n]\longrightarrow\mu_n
\]
induced by the Poincare bundle.  A polarization identifies the two factors and
produces the usual symplectic Weil pairing on $A[n]$.
\uses{mumford-thm-dual-any-characteristic,mumford-def-cartier-dual}
\notready
\end{proposition}

\section[Applications]{Applications to abelian varieties}
\label{mumford-III15}
\dcref{M:ch3:III.15}

\begin{definition}[Polarization]
\label{mumford-def-polarization}
\dcref{M:ch3:III.15}
A polarization of $A$ is a homomorphism $\lambda:A\to\Adual$ equal to
$\phi_L$ for an ample line bundle $L$.  It is principal when it is an
isomorphism.
\uses{mumford-prop-phi-L,mumford-thm-dual-any-characteristic}
\notready
\end{definition}

\begin{theorem}[Ample line bundles and finite kernels]
\label{mumford-thm-ample-finite-kernel}
\dcref{M:ch3:III.15}
For a line bundle $L$ on $A$, call $L$ nondegenerate when $\phi_L$ is an
isogeny (equivalently, $K(L)$ is finite).  An ample $L$ is nondegenerate, and
$\phi_L$ is a polarization precisely when it is induced by an ample $L$; the
sign matters, since $L^{-1}$ has the same finite kernel but is anti-ample.
\uses{mumford-def-polarization,mumford-def-KL,mumford-prop-abelian-quotient}
\notready
\end{theorem}

\begin{proposition}[Neron--Severi sequence]
\label{mumford-prop-pic-ns-sequence}
\dcref{M:ch3:III.15}
There is an exact sequence
\[
 0\longrightarrow\Piczero(A)\longrightarrow\Pic(A)\longrightarrow
 \NS(A)\longrightarrow0,
\]
where $\NS(A)$ is a finitely generated free abelian group.  Under
$L\mapsto\phi_L$, $\NS(A)$ embeds in $\Hom(A,\Adual)$.
\uses{mumford-thm-dual-any-characteristic,mumford-prop-phi-L}
\notready
\end{proposition}

\begin{corollary}[Dual isogeny]
\label{mumford-cor-dual-isogeny}
\dcref{M:ch3:III.15}
For an isogeny $f:A\to B$ and a polarization $\lambda_B$ on $B$, the pullback
polarization on $A$ is
\[
 \lambda_A=\widehat f\circ\lambda_B\circ f:A\longrightarrow\Adual.
\]
Relative to chosen polarizations one may form the Rosati adjoint
$f^\dagger=\lambda_A^{-1}\widehat f\lambda_B$.  The isogeny-factorization
theorem supplies a quasi-inverse with integral composites; the integer depends
on the chosen normalization and is not identified here with $\deg f$.
\uses{mumford-thm-isogeny-factorization,mumford-def-polarization,mumford-prop-biduality-any-characteristic}
\notready
\end{corollary}

\begin{remark}[Scheme-cube package]
\label{mumford3-cube-theorem-ii}
The second cube theorem is the scheme version with its triviality-locus and
nilpotent-thickening proof interface.
\dcref{M:ch3:III.10}
\uses{mumford-thm-cube-schemes,mumford3-cube-triviality-locus}
\notready
\end{remark}

\section{Supporting dependency interfaces}
\label{mumford-III-coverage-register}
The detailed scheme-theoretic constructions in this register support the
duality and arithmetic results.  Their proofs are treated as external inputs
where the available evidence is insufficient for reconstruction.

\begin{convention}[Scheme conventions]
\label{mumford3-standing-scheme-conventions}
The ground field is algebraically closed, schemes are of finite type over it,
and a point means a closed point unless an $S$-valued point is displayed.
\dcref{M:ch3:III.10}
\notready
\end{convention}

\begin{definition}[Maximal triviality locus]
\label{mumford3-cube-triviality-locus}
For $L$ on $X\times Y$ with $X$ complete, there is a maximal closed subscheme
$Y_L\subseteq Y$ such that the restriction of $L$ is pulled back from $Y_L$.
A map $S\to Y$ factors through $Y_L$ exactly when the corresponding family is
trivial along $X$ up to a bundle from $S$.
\dcref{M:ch3:III.10}
\uses{mumford-thm-seesaw}
\notready
\end{definition}

\begin{lemma}[Nilpotent step in the cube proof]
\label{mumford3-complete-connected-local-argument}
To prove that the triviality locus fills a connected base, pass to an Artinian
local thickening at a boundary point.  The first nonzero graded piece of its
ideal would define a class in the Kunneth decomposition of $H^1(X\times Y)$;
the three face trivializations force that class to vanish.
\dcref{M:ch3:III.10}
\uses{mumford3-cube-triviality-locus,mumford-thm-cube-schemes}
\notready
\end{lemma}

\begin{definition}[Functor of points]
\label{mumford3-functor-of-points}
A scheme $X$ determines the contravariant functor $S\mapsto\Hom(S,X)$.
Yoneda identifies natural transformations between representable functors with
unique morphisms of schemes.
\dcref{M:ch3:III.11}
\notready
\end{definition}

\begin{definition}[Translations and actions]
\label{mumford3-translations-and-actions}
An $S$-point of a group scheme acting on $X$ induces an automorphism of $X_S$;
translations compose according to the group law, and invariant morphisms are
constant on these functorial orbits.
\dcref{M:ch3:III.11}
\uses{mumford3-functor-of-points,mumford-def-group-scheme}
\notready
\end{definition}

\begin{definition}[Tangent vectors and invariant fields]
\label{mumford3-tangent-space-and-vector-field}
A tangent vector at $x$ is a derivation $\cO_{X,x}\to k$.  For a group scheme,
left-invariant vector fields are derivations compatible with multiplication.
\dcref{M:ch3:III.11}
\uses{mumford3-functor-of-points}
\notready
\end{definition}

\begin{proposition}[Invariant extension]
\label{mumford3-invariant-field-extension}
Every tangent vector at the identity extends uniquely to a left-invariant
vector field.  Evaluation at the identity therefore identifies such fields
with $\Lie(G)$.
\dcref{M:ch3:III.11}
\uses{mumford3-tangent-space-and-vector-field,mumford-prop-group-scheme-lie}
\notready
\end{proposition}

\begin{proposition}[Commutative Lie algebra]
\label{mumford3-commutative-lie-algebra}
For a commutative group scheme the bracket of invariant fields is zero.  In
characteristic $p$, the restricted $p$-operation retains infinitesimal data.
\dcref{M:ch3:III.11}
\uses{mumford3-invariant-field-extension}
\notready
\end{proposition}

\begin{theorem}[Characteristic-zero smoothness]
\label{mumford3-char-zero-smoothness}
Every finite-type group scheme over a characteristic-zero field is smooth and
reduced; invariant fields transport smoothness from the identity to all points.
\dcref{M:ch3:III.11}
\uses{mumford3-invariant-field-extension}
\notready
\end{theorem}

\begin{definition}[Infinitesimal subgroup neighbourhoods]
\label{mumford3-subgroup-kernel-neighborhoods}
The scheme-theoretic kernel of a homomorphism is the identity fibre.  In
characteristic $p$, suitable powers of the maximal ideal at the identity define
finite infinitesimal subgroup schemes with the same Lie algebra at high order.
\dcref{M:ch3:III.11}
\uses{mumford-lem-group-scheme-kernel,mumford-prop-group-scheme-lie}
\notready
\end{definition}

\begin{definition}[Hyperalgebra]
\label{mumford3-hyperalgebra}
The filtered duals of the local coordinate rings at the identity form a
convolution algebra of distributions.  Multiplication on the group supplies
the convolution product and ordinary multiplication supplies its coproduct.
\dcref{M:ch3:III.11}
\uses{mumford3-subgroup-kernel-neighborhoods}
\notready
\end{definition}

\begin{proposition}[Invariant differential operators]
\label{mumford3-invariant-differential-operators}
Each distribution in the hyperalgebra acts on functions as a left-invariant
differential operator, and convolution corresponds to composition.
\dcref{M:ch3:III.11}
\uses{mumford3-hyperalgebra,mumford3-invariant-field-extension}
\notready
\end{proposition}

\begin{proposition}[Free finite quotient]
\label{mumford3-free-quotient-flatness}
For a free action of a finite group scheme, $X\to X/G$ is finite locally free
of rank equal to the rank of $G$ and is a principal fppf torsor.
\dcref{M:ch3:III.12}
\uses{mumford-def-group-scheme-action,mumford-thm-finite-groupscheme-quotient}
\notready
\end{proposition}

\begin{definition}[Finite epimorphism]
\label{mumford3-finite-epimorphism}
A homomorphism of group schemes is an epimorphism here when it is faithfully
flat with the quotient universal property; in the finite setting its kernel is
a finite normal subgroup scheme.
\dcref{M:ch3:III.12}
\uses{mumford-lem-group-scheme-kernel}
\notready
\end{definition}

\begin{corollary}[Finite normal subgroups and quotients]
\label{mumford3-normal-finite-subgroup-correspondence}
Finite normal subgroup schemes correspond to finite quotient epimorphisms:
the subgroup is the scheme-theoretic kernel and the target represents the
quotient sheaf.
\dcref{M:ch3:III.12}
\uses{mumford3-finite-epimorphism,mumford-thm-finite-groupscheme-quotient}
\notready
\end{corollary}

\begin{definition}[Principal finite-group fibration]
\label{mumford3-principal-fibration}
A principal finite-group fibration is a finite locally free torsor
$U\to V$; its degree is the rank of the acting group scheme.
\dcref{M:ch3:III.12}
\uses{mumford3-free-quotient-flatness}
\notready
\end{definition}

\begin{theorem}[Euler characteristic of a finite torsor]
\label{mumford3-euler-characteristic-quotient}
For a principal finite-group fibration $\pi:U\to V$ and a coherent sheaf $F$
on $V$, one has
\[
 \chi(U,\pi^*F)=(\deg\pi)\chi(V,F).
\]
\dcref{M:ch3:III.12}
\uses{mumford3-principal-fibration,mumford-cor-flat-base-change}
\notready
\end{theorem}

\begin{remark}[Symmetric-group model of a finite map]
\label{mumford3-finite-morphism-symmetric-quotient}
Away from the collision locus, an ordered fibre product of a constant-degree
finite map is a principal symmetric-group cover; this construction reduces
several quotient calculations to the free case.
\dcref{M:ch3:III.12}
\uses{mumford3-principal-fibration}
\notready
\end{remark}

\begin{proposition}[Valued-point criterion for $K(L)$]
\label{mumford3-kernel-valued-point-criterion}
An $S$-point $x:S\to A$ factors through $K(L)$ exactly when
$t_x^*L_S\simeq L_S\otimes p_S^*N$ for some line bundle $N$ on $S$.
\dcref{M:ch3:III.13}
\uses{mumford-def-KL,mumford-thm-seesaw}
\notready
\end{proposition}

\begin{theorem}[Universal property of the dual]
\label{mumford3-poincare-universal-mapping}
A line bundle on $S\times A$, rigidified along $S\times\{0\}$ and fibrewise
algebraically trivial, is uniquely the pullback of the normalized Poincare
bundle along a morphism $S\to\Adual$.
\dcref{M:ch3:III.13}
\uses{mumford-thm-dual-any-characteristic,mumford-thm-seesaw}
\notready
\end{theorem}

\begin{theorem}[Cohomology of the Poincare bundle]
\label{mumford3-poincare-cohomology}
For $g=\dim A$, the normalized Poincare bundle on $\Adual\times A$ has a
single one-dimensional total cohomology contribution in degree $g$; equivalently
its derived pushforward is concentrated at the origin with the corresponding
shift.
\dcref{M:ch3:III.13}
\uses{mumford3-poincare-universal-mapping,mumford-thm-base-change-criterion}
\notready
\end{theorem}

\begin{corollary}[Structure-sheaf cohomology]
\label{mumford3-structure-sheaf-cohomology}
If $\dim A=g$, then $h^i(A,\cO_A)=\binom gi$ and the cohomology algebra is the
exterior algebra on $H^1(A,\cO_A)$.
\dcref{M:ch3:III.13}
\uses{mumford3-poincare-cohomology}
\notready
\end{corollary}

\begin{corollary}[Tangent space of the dual]
\label{mumford3-tangent-dual-h1}
There is a canonical identification
$\Lie(\Adual)\simeq H^1(A,\cO_A)$, compatible with pullback by homomorphisms.
\dcref{M:ch3:III.13}
\uses{mumford3-poincare-universal-mapping,mumford-prop-group-scheme-lie}
\notready
\end{corollary}

\begin{corollary}[Degree of the dual isogeny]
\label{mumford3-dual-isogeny-degree}
For an isogeny $f:A\to B$, the dual map $\widehat f:\Bdual\to\Adual$ is an
isogeny and $\deg\widehat f=\deg f$.
\dcref{M:ch3:III.13}
\uses{mumford-prop-biduality-any-characteristic,mumford-thm-isogeny-factorization}
\notready
\end{corollary}

\begin{proposition}[Divisorial duality criterion]
\label{mumford3-divisorial-correspondence}
A normalized line bundle on $A\times B$ determines mutually dual homomorphisms
$A\to\widehat B$ and $B\to\Adual$.  If either is an isomorphism, the bundle is
a Poincare bundle and $A,B$ are dual abelian varieties.
\dcref{M:ch3:III.13}
\uses{mumford-thm-cube-schemes,mumford3-poincare-universal-mapping}
\notready
\end{proposition}

\begin{theorem}[Representability of Cartier characters]
\label{mumford3-cartier-representability}
For finite commutative $G$, the functor
$S\mapsto\Hom_S(G_S,\Gm)$ is represented by the Cartier dual $G^D$, and the
evaluation pairing is universal.
\dcref{M:ch3:III.14}
\uses{mumford-def-cartier-dual}
\notready
\end{theorem}

\begin{example}[Basic Cartier duals]
\label{mumford3-cartier-examples}
Cartier duality exchanges the constant cyclic group $\Z/n\Z$ with $\mu_n$;
in characteristic $p$, it displays the different reduced and infinitesimal
behaviour of $\Z/p\Z$, $\mu_p$, and $\alpha_p$.
\dcref{M:ch3:III.14}
\uses{mumford-thm-cartier-biduality,mumford-prop-standard-finite-groups}
\notready
\end{example}

\begin{theorem}[Local and reduced components]
\label{mumford3-local-reduced-decomposition}
A finite commutative group scheme over a perfect field has canonical connected
and etale parts, and Cartier duality exchanges etale groups with groups of
multiplicative type.  The associated exact sequences need not split canonically.
\dcref{M:ch3:III.14}
\uses{mumford-thm-cartier-biduality}
\notready
\end{theorem}

\begin{proposition}[Primitive elements and Lie theory]
\label{mumford3-primitive-elements-lie}
Primitive elements in the dual Hopf algebra act as invariant derivations; this
identifies additive characters of the Cartier dual with $\Lie(G)$, compatibly
with the restricted $p$-operation.
\dcref{M:ch3:III.14}
\uses{mumford3-hyperalgebra,mumford-thm-cartier-biduality}
\notready
\end{proposition}

\begin{definition}[Height-one group scheme]
\label{mumford3-height-one-group}
In characteristic $p$, a finite group scheme has height one when it is supported
at the identity and every element of its maximal ideal has zero $p$th power.
\dcref{M:ch3:III.14}
\uses{mumford3-subgroup-kernel-neighborhoods}
\notready
\end{definition}

\begin{theorem}[Height-one groups and restricted Lie algebras]
\label{mumford3-height-one-equivalence}
Finite commutative height-one group schemes are classified by finite-dimensional
abelian restricted $p$-Lie algebras; subgroup schemes correspond to restricted
subalgebras.
\dcref{M:ch3:III.14}
\uses{mumford3-height-one-group,mumford3-primitive-elements-lie}
\notready
\end{theorem}

\begin{corollary}[Height-one actions]
\label{mumford3-height-one-action}
An action of a height-one commutative group scheme is equivalently a compatible
family of commuting derivations satisfying the corresponding restricted
$p$-power relations.
\dcref{M:ch3:III.14}
\uses{mumford3-height-one-equivalence,mumford3-invariant-differential-operators}
\notready
\end{corollary}

\begin{theorem}[Kernel of a dual isogeny]
\label{mumford3-dual-isogeny-kernel}
If $f:A\to B$ is an isogeny with kernel $K$, then
$\ker(\widehat f)$ is canonically Cartier dual to $K$.
\dcref{M:ch3:III.15}
\uses{mumford3-dual-isogeny-degree,mumford-thm-cartier-biduality}
\notready
\end{theorem}

\begin{definition}[Height-one isogeny]
\label{mumford3-height-one-isogeny}
An isogeny in characteristic $p$ is height one when its kernel is a height-one
finite group scheme.
\dcref{M:ch3:III.15}
\uses{mumford3-height-one-group,mumford-prop-abelian-quotient}
\notready
\end{definition}

\begin{theorem}[Height-one isogenies and $p$-Lie subalgebras]
\label{mumford3-height-one-isogeny-p-lie}
Height-one quotient isogenies of $A$ correspond to restricted $p$-Lie
subalgebras of $\Lie(A)$ through the Lie algebra of their kernels.
\dcref{M:ch3:III.15}
\uses{mumford3-height-one-equivalence,mumford3-height-one-isogeny}
\notready
\end{theorem}

\begin{theorem}[$p$-rank and Frobenius]
\label{mumford3-p-rank-lie-frobenius}
The $p$-rank is invariant under isogeny and duality and equals the dimension of
the semisimple part of Frobenius on the appropriate first cohomology/Lie data.
\dcref{M:ch3:III.15}
\uses{mumford-prop-p-rank,mumford3-tangent-dual-h1,
 mumford3-dual-isogeny-kernel}
\notready
\end{theorem}

\begin{theorem}[Restricted power and cohomological Frobenius]
\label{mumford3-lie-frobenius-compatibility}
Under $\Lie(\Adual)\simeq H^1(A,\cO_A)$, the restricted $p$-power operation is
compatible with the Frobenius action used to compute the $p$-rank.
\dcref{M:ch3:III.15}
\uses{mumford3-primitive-elements-lie,mumford3-tangent-dual-h1}
\notready
\end{theorem}

\begin{theorem}[Riemann--Roch and degree]
\label{mumford3-riemann-roch}
For $L=\cO_A(D)$ on a $g$-dimensional abelian variety,
\[
 \chi(L)=\frac{(D^g)}{g!},\qquad \deg(\phi_L)=\chi(L)^2.
\]
\dcref{M:ch3:III.16}
\uses{mumford-prop-euler-line-bundle,mumford-prop-phi-L}
\notready
\end{theorem}

\begin{definition}[Index of a nondegenerate line bundle]
\label{mumford3-index-definition}
A line bundle is nondegenerate when $\phi_L$ is an isogeny.  Its index $i(L)$
is the unique degree in which its coherent cohomology is nonzero.
\dcref{M:ch3:III.16}
\uses{mumford-thm-ample-finite-kernel,mumford-thm-line-bundle-index}
\notready
\end{definition}

\begin{theorem}[Real-root index polynomial]
\label{mumford3-index-polynomial-theorem}
For ample $H$ and nondegenerate $L$, the polynomial
$P(t)=\chi(H^{\otimes t}\otimes L)$ has real roots, counted with multiplicity,
and the sign convention recovers $i(L)$ from the number of positive roots.
\dcref{M:ch3:III.16}
\uses{mumford3-riemann-roch,mumford3-index-definition}
\notready
\end{theorem}

\begin{lemma}[Index growth bound]
\label{mumford3-index-growth-lemma}
Cohomology of tensor powers grows polynomially with the degree predicted by
Riemann--Roch; this bounds the possible jump of the index at a root of $P$.
\dcref{M:ch3:III.16}
\uses{mumford3-riemann-roch,mumford-thm-semicontinuity}
\notready
\end{lemma}

\begin{lemma}[Root-free invariance]
\label{mumford3-index-step-a}
Along a segment in the Neron--Severi space on which the Euler polynomial has no
root, the cohomological index is constant.
\dcref{M:ch3:III.16}
\uses{mumford3-index-polynomial-theorem,mumford-thm-semicontinuity}
\notready
\end{lemma}

\begin{lemma}[Two-variable index comparison]
\label{mumford3-index-step-b}
A root-free rectangle for the two-variable Euler polynomial identifies the
indices at its opposite endpoints, reducing the index theorem to one variable.
\dcref{M:ch3:III.16}
\uses{mumford3-index-step-a}
\notready
\end{lemma}

\begin{corollary}[Index under positive tensor powers]
\label{mumford3-index-power-corollary}
For every $n>0$, a nondegenerate $L$ satisfies $i(L^{\otimes n})=i(L)$.
\dcref{M:ch3:III.16}
\uses{mumford3-index-step-a}
\notready
\end{corollary}

\begin{proposition}[Subadditivity of index]
\label{mumford3-index-subadditivity}
When $L_1,L_2$, and $L_1\otimes L_2$ are nondegenerate,
$i(L_1\otimes L_2)\leq i(L_1)+i(L_2)$.
\dcref{M:ch3:III.16}
\uses{mumford3-index-step-b}
\notready
\end{proposition}

\begin{proposition}[Multiplicity bounds an index jump]
\label{mumford3-index-root-multiplicity-bound}
At a root of the index polynomial, the change in index is at most the
multiplicity of that root.
\dcref{M:ch3:III.16}
\uses{mumford3-index-growth-lemma,mumford3-index-step-b}
\notready
\end{proposition}

\begin{corollary}[Complex analytic index]
\label{mumford3-complex-index-corollary}
Over $\C$, the algebraic index is the number of negative eigenvalues of the
Hermitian form in the Appell--Humbert datum.
\dcref{M:ch3:III.16}
\uses{mumford3-index-polynomial-theorem,mumford-thm-appell-humbert}
\notready
\end{corollary}

\begin{lemma}[Separation of points]
\label{mumford3-support-separation}
Suitable translates of an ample divisor supply sections of a high tensor power
that separate any two distinct points of $A$.
\dcref{M:ch3:III.17}
\uses{mumford-thm-line-bundle-index,mumford-prop-square}
\notready
\end{lemma}

\begin{lemma}[Separation of tangent vectors]
\label{mumford3-tangent-separation}
High tensor powers of an ample line bundle separate nonzero tangent vectors.
In characteristic $p$, the proof uses the height-one subgroup generated by the
chosen vector.
\dcref{M:ch3:III.17}
\uses{mumford3-support-separation,mumford3-height-one-equivalence}
\notready
\end{lemma}

\begin{theorem}[Fourth and higher powers]
\label{mumford3-very-ample-power}
For an ample $L$, every $L^{\otimes n}$ with $n>3$ is very ample.
\dcref{M:ch3:III.17}
\uses{mumford3-support-separation,mumford3-tangent-separation,
 mumford-thm-high-power-very-ample}
\notready
\end{theorem}

\begin{remark}[Group-scheme structure package]
\label{mumford3-group-scheme}
The functorial group law recorded in the group-scheme definition is the
scheme-theoretic replacement for reasoning only with geometric points.
\dcref{M:ch3:III.11}
\uses{mumford-def-group-scheme,mumford3-functor-of-points}
\notready
\end{remark}

\begin{remark}[Restricted Lie package]
\label{mumford3-lie-algebra}
In characteristic $p$, $\Lie(G)$ carries its commutator bracket and the
restricted operation induced by $p$-fold composition of invariant derivations.
\dcref{M:ch3:III.11}
\uses{mumford-prop-group-scheme-lie,mumford3-invariant-field-extension}
\notready
\end{remark}

\begin{example}[Infinitesimal standard groups]
\label{mumford3-alpha-mu-examples}
The schemes $\alpha_p=\Spec k[T]/(T^p)$ and
$\mu_p=\Spec k[T]/(T^p-1)$ exhibit additive and multiplicative nonreduced
subgroups in characteristic $p$.
\dcref{M:ch3:III.11}
\uses{mumford-prop-standard-finite-groups}
\notready
\end{example}

\begin{remark}[Normal quotient package]
\label{mumford3-general-quotient-group-scheme}
Whenever the quotient by a normal subgroup scheme is representable, it inherits
a unique group law and is universal for invariant homomorphisms.
\dcref{M:ch3:III.11}
\uses{mumford3-normal-finite-subgroup-correspondence}
\notready
\end{remark}

\begin{remark}[Group-action package]
\label{mumford3-action}
Freeness is detected by the graph morphism $G\times X\to X\times X$, and
equivariant sheaves carry the cocycle needed for descent.
\dcref{M:ch3:III.12}
\uses{mumford-def-group-scheme-action}
\notready
\end{remark}

\begin{remark}[Finite quotient package]
\label{mumford3-finite-quotient-theorem}
The finite quotient theorem represents $X/G$ and separates representability
from the stronger free-torsor descent assertion.
\dcref{M:ch3:III.12}
\uses{mumford-thm-finite-groupscheme-quotient,mumford3-free-quotient-flatness}
\notready
\end{remark}

\begin{corollary}[Invariant pushforward]
\label{mumford3-invariant-pushforward}
For a finite quotient $\pi:X\to X/G$, the invariant subsheaf
$(\pi_*F)^G$ descends an equivariant $F$ in the free-torsor case.
\dcref{M:ch3:III.12}
\uses{mumford3-free-quotient-flatness}
\notready
\end{corollary}

\begin{remark}[Translation-kernel package]
\label{mumford3-kernel-line-bundle}
The functor $K(L)$ is represented by the scheme-theoretic kernel of $\phi_L$.
\dcref{M:ch3:III.13}
\uses{mumford-def-KL,mumford-prop-phi-L}
\notready
\end{remark}

\begin{remark}[Dual-construction package]
\label{mumford3-dual-construction}
The normalized Poincare bundle and the representing abelian variety together
constitute the construction of $\Adual$.
\dcref{M:ch3:III.13}
\uses{mumford-thm-dual-any-characteristic,mumford3-poincare-universal-mapping}
\notready
\end{remark}

\begin{remark}[$\phi_L$ package]
\label{mumford3-phi-l-morphism}
The theorem of the square makes $x\mapsto t_x^*L\otimes L^{-1}$ a homomorphism
whose kernel is $K(L)$.
\dcref{M:ch3:III.13}
\uses{mumford-prop-square,mumford-prop-phi-L}
\notready
\end{remark}

\begin{corollary}[Canonical biduality]
\label{mumford3-duality-hypothesis}
The Poincare correspondence identifies $A$ canonically with its bidual.
\dcref{M:ch3:III.13}
\uses{mumford-prop-biduality-any-characteristic,mumford3-divisorial-correspondence}
\notready
\end{corollary}

\begin{remark}[Cartier-duality package]
\label{mumford3-cartier-dual}
Cartier duality is the affine Hopf-algebra duality representing multiplicative
characters of finite commutative group schemes.
\dcref{M:ch3:III.14}
\uses{mumford-def-cartier-dual,mumford3-cartier-representability}
\notready
\end{remark}

\begin{definition}[$p$-rank]
\label{mumford3-p-rank}
The $p$-rank $f$ is determined by
$A[p](\bar k)\simeq(\Z/p\Z)^f$, with $0\leq f\leq\dim A$.
\dcref{M:ch3:III.15}
\uses{mumford-prop-p-rank}
\notready
\end{definition}

\begin{theorem}[Nondegenerate vanishing]
\label{mumford3-vanishing-theorem}
A nondegenerate line bundle has cohomology in one degree only; an ample bundle
has index zero.
\dcref{M:ch3:III.16}
\uses{mumford-thm-line-bundle-index,mumford3-index-definition}
\notready
\end{theorem}

\begin{corollary}[Structure-sheaf dimensions]
\label{mumford3-h0-structure-cohomology}
For $g=\dim A$, one has $h^i(A,\cO_A)=\binom gi$.
\dcref{M:ch3:III.16}
\uses{mumford3-structure-sheaf-cohomology}
\notready
\end{corollary}

\begin{corollary}[Projective realization]
\label{mumford3-projectivity-consequence}
A high very ample power of an ample line bundle realizes $A$ as a closed
projective subvariety.
\dcref{M:ch3:III.17}
\uses{mumford3-very-ample-power,mumford-cor-abelian-projective}
\notready
\end{corollary}

\section[Cohomology of line bundles]{Cohomology of line bundles}
\label{mumford-III16}
\dcref{M:ch3:III.16}

\begin{proposition}[Euler characteristic polynomial]
\label{mumford-prop-euler-line-bundle}
\dcref{M:ch3:III.16}
For a line bundle $L$ on a $g$-dimensional abelian variety, $\chi(L)$ depends
only on its Neron--Severi class and
\[
 \chi(L)=\frac{c_1(L)^g}{g!},\qquad \chi(L^{\otimes n})=n^g\chi(L).
\]
\uses{mumford-prop-pic-ns-sequence,mumford-thm-semicontinuity}
\notready
\end{proposition}

\begin{theorem}[Index and vanishing]
\label{mumford-thm-line-bundle-index}
\dcref{M:ch3:III.16}
If $L$ is nondegenerate, exactly one $H^i(A,L)$ is nonzero; its index is the
algebraic index attached to the numerical class (over $\C$ it is the number of
negative eigenvalues of the associated Hermitian form), and its
dimension is $|\chi(L)|$.  In particular, if $L$ is ample then
$H^i(A,L)=0$ for $i>0$ and $h^0(A,L)=\chi(L)>0$.
\uses{mumford-prop-euler-line-bundle,mumford-thm-ample-finite-kernel}
\notready
\end{theorem}

\begin{corollary}[Translation invariance of cohomology]
\label{mumford-cor-translation-cohomology}
\dcref{M:ch3:III.16}
For every $a\in A$, translation induces isomorphisms
$H^i(A,L)\simeq H^i(A,t_a^*L)$.  Cohomology dimensions are constant on the
translation orbit of a line bundle.
\uses{mumford-lem-abelian-translations,mumford-thm-line-bundle-index}
\notready
\end{corollary}

\section[Very ample line bundles]{Very ample line bundles}
\label{mumford-III17}
\dcref{M:ch3:III.17}

\begin{theorem}[High powers are very ample]
\label{mumford-thm-high-power-very-ample}
If $L$ is ample on an abelian variety, then $L^{\otimes n}$ is very ample for
every integer $n>3$.  The borderline $n=3$
requires the separate point- and tangent-separation argument and is not
asserted here.  The complete linear system defines a closed immersion
\[
 A\hookrightarrow\PP(H^0(A,L^{\otimes n})^\vee).
\]
\dcref{M:ch3:III.17}
\uses{mumford-thm-line-bundle-index,mumford-thm-cube-schemes}
\notready
\end{theorem}

\begin{corollary}[Projectivity and finite generation]
\label{mumford-cor-abelian-projective}
\dcref{M:ch3:III.17}
Every abelian variety is projective, and its homogeneous coordinate ring for a
high enough power of any ample line bundle is finitely generated.
\uses{mumford-thm-high-power-very-ample,mumford-def-abelian-variety}
\notready
\end{corollary}

% Source-faithful assembly: Mumford, Abelian Varieties, Chapter III,
% pages 88--120 (Horizon transcription pages 0099--0131).

\label{mumford-III10-source}
\dcref{M:ch3:III.10}

\begin{proposition}[Fibres of a morphism from an abelian variety]
\label{mumford-prop-abelian-fibre-kernel}
\dcref{M:ch3:III.10}
Let $f:X\to Y$ be a morphism of varieties with $X$ an abelian variety. If
$F_x$ is the connected component of the fibre $f^{-1}(f(x))$ containing $x$,
then there is a closed connected subgroup $F\subset X$ such that
$F_x=x+F$ for every $x$.
\source{mumford-abelian-varieties:page-0099}
\end{proposition}
\begin{proof}
For fixed $x$, apply the rigidity lemma to
$\phi:X\times F_x\to Y$, $\phi(z,w)=f(z+w)$, since $F_x$ is complete and
connected and $\phi(\{e\}\times F_x)$ is constant. Hence
$f(z-x+F_x)=f(z)$, so connectedness gives
$F_z\supset z-x+F_x$. Interchanging $x,z$ gives equality. Taking
$F=F_e$ yields $F_z=z+F$. If $u\in F$, then
$F_{-u}=-u+F$ contains $e$, hence equals $F_e=F$. Thus $-u+F=F$ for all
$u\in F$, proving that $F$ is a subgroup; it is closed and connected by
construction.
\end{proof}

\begin{theorem}[Effective divisors and their stabilizers]
\label{mumford-thm-effective-divisor-stabilizer}
\dcref{M:ch3:III.10}
\uses{mumford-prop-abelian-fibre-kernel}
For an effective divisor $D$ on an abelian variety $X$, let
$H(D)=\{x\mid T_x^*D=D\}$ (equality of divisors), let $L=L(D)$, and let
$f:X\to\mathbf P(H^0(X,L^2))$ be the morphism defined by the base-point-free
bundle $L^2$. If $F(D)=\ker f$, then
\[
H(D)\text{ is Zariski closed},\qquad H(D)^0=K(L)^0=F(D).
\]
\source{mumford-abelian-varieties:page-0099}
\emph{The source states this theorem without proof.}
\end{theorem}

\begin{proposition}[Maximal triviality subscheme]
\label{mumford-prop-maximal-triviality-scheme}
\dcref{M:ch3:III.10}
\uses{mumford-thm-seesaw}
Let $X$ be a complete variety, $Y$ any scheme and $L$ a line bundle on
$X\times Y$. There exists a unique closed subscheme $Y_1\hookrightarrow Y$
such that:
\begin{enumerate}
\item if $L_1$ is the restriction of $L$ to $X\times Y_1$, then
there is a line bundle $M_1$ on $Y_1$ and an isomorphism
$p_2^*M_1\simeq L_1$;
\item if $f:Z\to Y$ and $p_2^*K\simeq(1_X\times f)^*L$ for a line bundle
$K$ on $Z$, then $f$ factors through $Y_1$.
\end{enumerate}
\source{mumford-abelian-varieties:page-0100}
\source{mumford-abelian-varieties:page-0101}
\source{mumford-abelian-varieties:page-0102}
\end{proposition}
\begin{proof}
Uniqueness follows because the two closed immersions factor through one
another. If $p_2^*M_1\simeq L_1$, the Kunneth formula gives
$M_1\simeq p_{2,*}L_1$; thus it is enough to require that this direct image
be invertible and that the natural map $p_2^*p_{2,*}L_1\to L_1$ be an
isomorphism. The assertion is local on $Y$: local subschemes agree on
overlaps by uniqueness.

Take $Y=\operatorname{Spec}A$ and, after shrinking, a free complex
$0\to A^0\xrightarrow{\phi}A^1\to\cdots$ computing direct images of $L$
universally. If $M=\operatorname{coker}(A^1\xrightarrow{\phi}A^0)$, then for
every $A$-algebra $B$,
\[
0\to\operatorname{Hom}_B(M\otimes_A B,B)\to B^0\xrightarrow{\phi_B}B^1
\]
is exact. Hence
$p_{2,*}(1_X\times f)^*L\simeq\operatorname{Hom}_A(M,B)$.
Let $F$ be the closed set of points where $L_y$ is trivial. Outside $F$ the
empty subscheme works. At $y\in F$,
\[
1=\dim H^0(X,L_y)=\dim_k M/\mathfrak m_yM,
\]
so Nakayama gives, after shrinking, $M\simeq A/\mathfrak a$. For the
subscheme defined by $\mathfrak a$, the direct image is
$\operatorname{Hom}_A(A/\mathfrak a,A/\mathfrak a)\simeq A/\mathfrak a$.
The evaluation map
\[
p_2^*p_{2,*}L_1\xrightarrow{\lambda}L_1
\]
is an isomorphism on the fibre over $y$: its fibre map is surjective because
\(\operatorname{Hom}_A(A/\mathfrak a,A/\mathfrak a)\to
\operatorname{Hom}_A(A/\mathfrak a,A/\mathfrak m_y)\) is surjective and
$L_y$ is trivial. The non-isomorphism locus is closed, and its projection is
closed and avoids $y$; shrinking once more gives (a).

For (b), take $Z=\operatorname{Spec}B$ affine and trivialize $K$. Then
$p_{2,*}(1_X\times f)^*L\simeq B$, while the universal complex gives
$B\simeq\operatorname{Hom}_A(A/\mathfrak a,B)$. Therefore
$\mathfrak aB=0$, so $A\to B$ factors through $A/\mathfrak a$.
\end{proof}

\begin{theorem}[Theorem of the cube, scheme-theoretic form]
\label{mumford-thm-cube-schemes}
\dcref{M:ch3:III.10}
\uses{mumford-prop-maximal-triviality-scheme}
Let $X,Y$ be complete varieties, $Z$ a connected scheme, and $L$ a line
bundle on $X\times Y\times Z$. If the restrictions to
\(\{x_0\}\times Y\times Z$, $X\times\{y_0\}\times Z$ and
$X\times Y\times\{z_0\}$ are trivial, then $L$ is trivial.
\source{mumford-abelian-varieties:page-0102}
\source{mumford-abelian-varieties:page-0103}
\source{mumford-abelian-varieties:page-0104}
\end{theorem}
\begin{proof}
Let $Z'$ be the maximal closed subscheme over which $L$ is trivial. It is
nonempty, since it contains $z_0$. It suffices, by connectedness, to show
that every point of $Z'$ has an open neighbourhood in $Z'$ equal to an open
neighbourhood in $Z$. At $z_0$, write $\mathfrak m$ for the maximal ideal
of $\mathcal O_{Z,z_0}$ and $I$ for the ideal of $Z'$. If $I\ne0$, Krull's
theorem gives $n>0$ with $\mathfrak m^n\supset I$ but
$\mathfrak m^{n+1}\not\supset I$. Put $\mathfrak a_1=\mathfrak m^{n+1}+I$;
choose $\mathfrak a_2$ with
$\mathfrak a_1\supset\mathfrak a_2\supset\mathfrak m^{n+1}$ and
$\dim_k\mathfrak a_1/\mathfrak a_2=1$. Thus
$\mathfrak a_1=\mathfrak a_2+k a$, with $\mathfrak a_1\supset I$ but
$\mathfrak a_2\not\supset I$.

Let $Z_i$ be the one-point subscheme defined by $\mathfrak a_i$ (and let
$Z_0=\{z_0\}$). The exact sequence
\[
0\to\mathcal O_{Z_0}\xrightarrow{a}\mathcal O_{Z_2}
\to\mathcal O_{Z_1}\to0
\]
induces
\[
0\to L_0\xrightarrow{a}L_2\to L_1\to0.
\]
Both $L_0$ and $L_1$ are trivial. If $s$ is the section of $L_1$ induced by
a trivialization, $L_2$ is trivial exactly when $s$ lifts to a section of
$L_2$: a lift gives a map from the structure sheaf which is an isomorphism
on the closed fibre, while a trivialization makes restriction on global
sections surjective.

Fix a trivialization of $L_0$. The obstruction to lifting $s$ is
$\xi\in H^1(X\times Y,\mathcal O_{X\times Y})$. The two assumed trivial
restrictions show that the images of $\xi$ under
\[
H^1(X\times Y,\mathcal O)\to H^1(X,\mathcal O_X),\qquad
H^1(X\times Y,\mathcal O)\to H^1(Y,\mathcal O_Y)
\]
are zero. The Kunneth formula identifies these two maps with the two
projections from
$H^1(X,\mathcal O_X)\oplus H^1(Y,\mathcal O_Y)$, so $\xi=0$. Thus $L_2$
is trivial, contradicting $\mathfrak a_2\not\supset I$. Hence $I=0$.
\end{proof}

\section{Basic theory of group schemes}
\label{mumford-III11-source}
\dcref{M:ch3:III.11}

\begin{definition}[Group scheme and functor of points]
\label{mumford-def-group-scheme}
\dcref{M:ch3:III.11}
A group scheme is a scheme $G$ with morphisms $m:G\times G\to G$,
$e:\operatorname{Spec}k\to G$, and $i:G\to G$ satisfying associativity,
identity, and inverse diagrams. Equivalently, $G(S)=\operatorname{Hom}_k(S,G)$
is a group, functorially in $S$. The functor $X\mapsto\underline X$ is fully
faithful (Yoneda).
\source{mumford-abelian-varieties:page-0104}
\source{mumford-abelian-varieties:page-0105}
\source{mumford-abelian-varieties:page-0106}
\end{definition}

\begin{proposition}[Lie algebra of a group scheme]
\label{mumford-prop-group-scheme-lie}
\dcref{M:ch3:III.11}
\uses{mumford-def-group-scheme}
For a group scheme $G$, every tangent vector at $e$ extends uniquely to a
left-invariant vector field. The left-invariant vector fields form the Lie
algebra of $G$ under the Poisson bracket, and in characteristic $p$ under
the $p$-th power operation.
\source{mumford-abelian-varieties:page-0107}
\source{mumford-abelian-varieties:page-0108}
\source{mumford-abelian-varieties:page-0109}
\source{mumford-abelian-varieties:page-0110}
\end{proposition}
\begin{proof}
A vector field is a derivation $D:\mathcal O_X\to\mathcal O_X$, equivalently
$\mathcal O_X\to\Omega_X\to\mathcal O_X$. Tangent vectors at $x$ are
$\operatorname{Hom}_{\mathcal O_{X,x}}(\Omega_{X,x},k)$, and hence linear
forms on $\mathfrak m_x/\mathfrak m_x^2$. Put
$\Lambda=k[\epsilon]/(\epsilon^2)$. A derivation $D:A\to B$ is equivalent
to a homomorphism $A\to B\otimes_k\Lambda$, $a\mapsto a+(Da)\epsilon$.
Thus a vector field is an infinitesimal automorphism over $\Lambda$.

For a group scheme, left invariance says that this automorphism commutes with
right multiplication. If $\widetilde t:\operatorname{Spec}\Lambda\to G$ is
the value at the identity, the commutative diagram forces the automorphism to
be right multiplication by $\widetilde t$, and conversely. This proves the
canonical identification of left-invariant vector fields with $T_eG$.
The commutator $[D_1,D_2]=D_1D_2-D_2D_1$ and, in characteristic $p$, $D^p$
are again vector fields and preserve left invariance.
\end{proof}

\begin{remark}[Lie identities and commutative groups]
\label{mumford-rem-lie-identities}
\dcref{M:ch3:III.11}
\uses{mumford-prop-group-scheme-lie}
The bracket is bilinear, alternating, and satisfies Jacobi. In characteristic
$p$, $\operatorname{ad}(X^p)=(\operatorname{ad}X)^p$ and
\[
(X+Y)^p=X^p+Y^p+F_p(\operatorname{ad}X,\operatorname{ad}Y)Y.
\]
If $G$ is commutative, the bracket is zero: using
$k[\epsilon,\epsilon']/ (\epsilon^2,\epsilon'^2)$, the commutator of the
two infinitesimal translations is the translation by the commutator of two
$S$-valued points, which is the identity.
\source{mumford-abelian-varieties:page-0110}
\source{mumford-abelian-varieties:page-0111}
\source{mumford-abelian-varieties:page-0112}
\end{remark}

\begin{theorem}[Characteristic-zero smoothness]
\label{mumford-thm-abelian-smooth}
\dcref{M:ch3:III.11}
\uses{mumford-prop-group-scheme-lie}
Every group scheme over a field of characteristic zero is smooth and reduced.
\source{mumford-abelian-varieties:page-0112}
\source{mumford-abelian-varieties:page-0113}
\end{theorem}
\begin{proof}
More generally, let $x$ be a point of a characteristic-zero scheme $X$ and
suppose vector fields $D_1,\ldots,D_n$, with
$n=\dim_k\mathfrak m_x/\mathfrak m_x^2$, give independent tangent vectors.
Choose $x_i\in\mathfrak m_x$ with $(D_ix_j)(x)=\delta_{ij}$. Since
$D_i(\mathfrak m_x^r)\subset\mathfrak m_x^{r-1}$, the derivations extend to
$\widehat{\mathcal O}_x$. Define
\[
\alpha:k[[t_1,\ldots,t_n]]\to\widehat{\mathcal O}_x,\quad t_i\mapsto x_i,
\]
and
\[
\beta(f)=\sum_{\nu\ge0}\frac{D^\nu f}{\nu!}(x)t^\nu,
\quad D^\nu=D_1^{\nu_1}\cdots D_n^{\nu_n}.
\]
Leibniz and induction show that $\beta$ is a continuous homomorphism.
Both maps are surjective: $\alpha$ because the $x_i$ generate the maximal
ideal, and $\beta$ because $\beta(x_i)\equiv t_i$ modulo the square of the
maximal ideal. Hence $\beta\alpha$ is an automorphism, so $\alpha$ is an
isomorphism. The completed local ring is regular, proving smoothness.
\end{proof}

\begin{definition}[Subgroup schemes and kernels]
\label{mumford-lem-group-scheme-kernel}
\dcref{M:ch3:III.11}
\uses{mumford-def-group-scheme}
A closed subscheme $H\subset G$ is a subgroup scheme if multiplication on
$H\times H$ factors through $H$. The fibre over the identity of a homomorphism
of group schemes is its kernel and is a closed subgroup scheme.
In characteristic $p$, with $\mathfrak m$ the maximal ideal at $e$, the
subscheme $G_n=\operatorname{Spec}(\mathcal O_e/\mathfrak m^{(p^n)})$ is a
subgroup scheme and $\Lie(G_n)=\Lie(G)$ for $n\ge1$.
\source{mumford-abelian-varieties:page-0113}
\source{mumford-abelian-varieties:page-0114}
\end{definition}
\begin{proof}
For $f\in\mathfrak m$, write $m^*f=g+h$ in the local ring at $(e,e)$,
with $g$ in the sum of the two maximal ideals and $h$ a unit. In
characteristic $p$, $m^*(f^{p^n})$ lies in the ideal generated by the two
$p^n$-power ideals, so multiplication factors through $G_n$. The statement
about Lie algebras is immediate from the definition.
\end{proof}

\section{Left-invariant differential operators}
\label{mumford-III11-hyperalgebra}
\dcref{M:ch3:III.11}

\begin{definition}[Hyperalgebra]
\label{mumford-def-hyperalgebra}
\dcref{M:ch3:III.11}
\uses{mumford-def-group-scheme}
Put
\[
H_x=\operatorname{Hom}_{\mathrm{cont}}(\mathcal O_{x,G},k),\qquad
H=\bigoplus_{x\in G}H_x
 =\varinjlim_{Z\subset G\ {\text{finite}}}\Gamma(\mathcal O_Z)^*.
\]
The convolution is
\[
L_1*L_2(f)=L_1\otimes L_2(m^*f).
\]
The elements $\delta_x$ are convolution identities at points,
$\delta_e*L=L*\delta_e=L$, and evaluation at $1$ is the augmentation.
\source{mumford-abelian-varieties:page-0115}
\source{mumford-abelian-varieties:page-0116}
\end{definition}

\begin{proposition}[Invariant differential operators]
\label{mumford-prop-hyperalgebra-operators}
\dcref{M:ch3:III.11}
\uses{mumford-def-hyperalgebra}
Each $L\in H$ defines a left-invariant differential operator
\[
D_L(f)=(L\otimes1)m^*(f),\qquad D_Lf(e)=L(f),
\]
and $D_{L_1*L_2}=D_{L_1}\circ D_{L_2}$. If $G$ is commutative, $H$ is
commutative and the Lie bracket is zero.
\source{mumford-abelian-varieties:page-0116}
\source{mumford-abelian-varieties:page-0117}
\source{mumford-abelian-varieties:page-0118}
\end{proposition}
\begin{proof}
If $L$ is supported on a finite subscheme $Z$, the construction factors
through $G\times Z$ and is therefore a differential operator. Associativity
of $m$ gives the composition formula. Cocommutativity of $m^*$ for a
commutative group scheme gives commutativity of convolution.
\end{proof}

\section{Quotients by finite group schemes}
\label{mumford-III12-source}
\dcref{M:ch3:III.12}

\begin{definition}[Action and freeness]
\label{mumford-def-group-scheme-action}
\dcref{M:ch3:III.12}
\uses{mumford-def-group-scheme}
An action is a morphism $\mu:G\times X\to X$ satisfying the unit and
associativity diagrams. A morphism is invariant if $f\mu=fp_2$. The action
is free if $(\mu,p_2):G\times X\to X\times X$ is a closed immersion.
A $G$-linearization of a coherent sheaf $\mathcal F$ is an isomorphism
$p_2^*\mathcal F\simeq\mu^*\mathcal F$ satisfying the corresponding
associativity diagram and restricting to the identity at $e$.
\source{mumford-abelian-varieties:page-0119}
\source{mumford-abelian-varieties:page-0120}
\source{mumford-abelian-varieties:page-0121}
\source{mumford-abelian-varieties:page-0122}
\end{definition}

\begin{theorem}[Quotient by a finite group scheme]
\label{mumford-thm-finite-groupscheme-quotient}
\dcref{M:ch3:III.12}
\uses{mumford-def-group-scheme-action}
Let a finite group scheme $G$ act on $X$, with every orbit contained in an
affine open. There is a quotient $(Y,\pi)$ whose underlying topological
space is the orbit quotient and for which
$\mathcal O_Y\simeq\pi_*\mathcal O_X^G$. It is unique, finite and
surjective, and has the universal property for invariant morphisms.
If the action is free, $\pi$ is flat of degree $n=\dim_kR$ for
$G=\operatorname{Spec}R$, $G\times X\simeq X\times_YX$, and pullback is an
equivalence between coherent sheaves on $Y$ and coherent $G$-sheaves on $X$.
\source{mumford-abelian-varieties:page-0122}
\source{mumford-abelian-varieties:page-0123}
\end{theorem}
\begin{proof}
For (A), reduce to $X=\operatorname{Spec}A$. Let
$B=A^G=\{a\mid\mu^*(a)=1\otimes a\}$. The norm
$\operatorname{Nm}_A:R\otimes_kA\to A$ defines
$N(a)=\operatorname{Nm}_A(\mu^*(a))$. If
$\phi(a)=1\otimes a$ and
$\psi(\xi\otimes\eta\otimes a)=(m^*\xi\otimes1)(1\otimes\eta\otimes a)$,
functoriality and invariance of norm under the $R\otimes A$-algebra
automorphism $\psi$ give
\[
\mu^*N=\operatorname{Nm}_{R\otimes A}(1\otimes\phi)\mu^*
=\phi\operatorname{Nm}_A\mu^*=\phi N.
\]
Thus $N(A)\subset B$. For $a\in A$, the characteristic polynomial
$\chi_a(T)=N(T-a)=T^n+s_1T^{n-1}+\cdots+s_n$ has invariant coefficients.
Since $\mu^*(a)-a$ vanishes on the quotient by $\epsilon\otimes1$,
$\chi_a(a)=0$. Hence $A$ is integral over $B$, so $B$ is finitely generated
and $\pi:\operatorname{Spec}A\to\operatorname{Spec}B$ is finite and
surjective. The norm separates orbits. Finally the invariant sheaf is the
kernel of
\[
\pi_*\mathcal O_X\longrightarrow\pi_*\mathcal O_X\otimes_kR,
\qquad f\longmapsto\mu^*(f)-f\otimes1,
\]
which proves the sheaf assertion.

For (B), the canonical pullback isomorphism
$(g f)^*\mathcal F\simeq f^*g^*\mathcal F$ satisfies its associativity
diagram; since $\pi\mu=\pi p_2$, it gives the natural action on
$\pi^*\mathcal F$. For a $G$-sheaf with module $M$, define invariants
$M^G$ and the natural maps
\[
\mathcal F\to\pi_*(\pi^*\mathcal F)^G,qquad
A\otimes_BM^G\to M.
\]
It remains affine to prove these are isomorphisms.

Freeness makes
\[
\lambda:A\otimes_BA\to R\otimes_kA,\qquad
\lambda(a_1\otimes a_2)=\mu^*(a_1)(1\otimes a_2)
\]
surjective. Localize so that $B$ is local and $A$ semilocal. There are
$a_1,\ldots,a_n$ such that $\mu^*(a_i)$ is an $A$-basis of $R\otimes A$.
Then
\[
\mu^*(a)=\sum_i(1\otimes\lambda_i)\mu^*(a_i)
\Longleftrightarrow a=\sum_i\lambda_i a_i\text{ and }\lambda_i\in B.
\]
This identifies $A$ as a free, hence faithfully flat, $B$-module, proves
injectivity of $\lambda$, and gives $A\otimes_BM^G\simeq M$. If $M$ is
projective over $A$, faithful flatness shows $M^G$ is $B$-flat; finite
presentation makes it $B$-projective.
\end{proof}

\begin{proof}[Details of the affine descent step]
The implication in the displayed basis criterion from right to left follows
by applying $\mu^*$ and using $\mu^*(\lambda_i)=1\otimes\lambda_i$ for
$\lambda_i\in B$. Conversely, apply $1\otimes\mu^*$ and
$(1\otimes\mu^*)(\mu^*a)=(m^*\otimes1)(\mu^*a)$ to the expansion
$\mu^*(a)=\sum_i(1\otimes\lambda_i)\mu^*(a_i)$. Independence of the basis
$\mu^*(a_i)$ gives $\lambda_i\in B$, and $\epsilon\otimes1$ gives
$a=\sum_i\lambda_i a_i$. The same calculation gives
$A\otimes_BA\simeq R\otimes_kA$. For a $G$-sheaf with module $M$, write the
action as $\tau:A\otimes_BM\to M\otimes_BA$ and set
\[
N=\{m\in M\mid\tau(1\otimes m)=m\otimes1\}.
\]
Flatness identifies $N\otimes_BA$ with the kernel of
\[
M\otimes_BA\to M\otimes_BA\otimes_BA,\quad
m\otimes a\mapsto m\otimes1\otimes a-\tau(1\otimes m)\otimes a.
\]
 Associativity identifies this kernel with $\tau(1\otimes M)$, and faithful
 flatness gives $N\otimes_BA\simeq M$.
\source{mumford-abelian-varieties:page-0124}
\source{mumford-abelian-varieties:page-0125}
\source{mumford-abelian-varieties:page-0126}
\source{mumford-abelian-varieties:page-0127}
\source{mumford-abelian-varieties:page-0128}
\end{proof}

\begin{definition}[Epimorphism of group schemes]
\label{mumford-def-group-scheme-epimorphism}
\dcref{M:ch3:III.12}
A homomorphism $f:X\to Y$ is an epimorphism if it is surjective and
$f^*:\mathcal O_Y\to f_*\mathcal O_X$ is injective.
\source{mumford-abelian-varieties:page-0128}
\end{definition}

\begin{corollary}[Finite normal quotients]
\label{mumford-cor-finite-normal-quotient}
\dcref{M:ch3:III.12}
\uses{mumford-thm-finite-groupscheme-quotient}
If a finite normal subgroup scheme $G\subset X$ acts by right translations,
then $X/G$ is a group scheme, $\pi:X\to X/G$ is an epimorphism, and
$G=\ker(\pi)$. Conversely, an epimorphism with finite kernel is the quotient
by its kernel.
\source{mumford-abelian-varieties:page-0128}
\source{mumford-abelian-varieties:page-0129}
\source{mumford-abelian-varieties:page-0130}
\end{corollary}
\begin{proof}
Multiplication descends because $\pi\circ m$ is $G\times G$-invariant.
The identity $G\times X\simeq X\times_{X/G}X$ gives
$x\in\ker\pi\Longleftrightarrow\pi(x)=\pi(e)\Longleftrightarrow x\in G(S)$.
Conversely factor through $X/G\to Y$. It is finite; translated affine opens
and Nakayama reduce isomorphy to residue fields. Its fibres are translates of
the trivial kernel, hence one reduced point.
\end{proof}

\begin{corollary}[Base change for equivariant sheaves]
\label{mumford-cor-quotient-sheaf-base-change}
\dcref{M:ch3:III.12}
\uses{mumford-thm-finite-groupscheme-quotient}
If $Y=X/G$ and $\mathcal G$ is a coherent $G$-sheaf on $X$, then
\[
\pi^*(\pi_*\mathcal G)\simeq\mathcal G\otimes_kR,
\qquad G=\operatorname{Spec}R.
\]
\source{mumford-abelian-varieties:page-0129}
\source{mumford-abelian-varieties:page-0130}
\source{mumford-abelian-varieties:page-0131}
\end{corollary}
\begin{proof}
Affine base change gives the natural pullback isomorphism. Identifying the
two pullbacks through $G\times X\simeq X\times_YX$ and using the action
identifies it with $\mathcal G\otimes_kR$.
\end{proof}

% Source-faithful assembly: Mumford, Abelian Varieties, Chapter III,
% Horizon transcription pages 0132--0176 (with quotient continuation pages
% 0127--0131 assembled in ch03-source-part1.tex).

\label{mumford-III12-associated-source}
\dcref{M:ch3:III.12}

\begin{definition}[Fibration with finite fibre]
\label{mumford-def-associated-finite-fibre}
\dcref{M:ch3:III.12}
Let a finite group scheme $G$ act freely on $X$, with quotient $X/G$, and
let $F$ be a finite scheme with a $G$-action. The induced free action on
$X\times F$ has quotient
\[
U=(X\times F)/G,
\]
and the natural morphism $\pi:U\to V=X/G$ is called the fibration with
fibre $F$ associated to the principal $G$-bundle $X\to X/G$. It is finite
and flat; its degree is the rank of $\pi_*\mathcal O_U$ over
$\mathcal O_V$.
\source{mumford-abelian-varieties:page-0132}
\uses{mumford-thm-finite-groupscheme-quotient}
\end{definition}

\begin{theorem}[Euler characteristic of an associated fibration]
\label{mumford-thm-euler-associated-fibration}
\dcref{M:ch3:III.12}
\uses{mumford-def-associated-finite-fibre}
If $\pi:U\to V$ is a finite-fibre fibration associated to a principal
$G$-bundle, then for every coherent sheaf $\mathcal F$ on $V$,
\[
\chi(\pi^*\mathcal F)=(\deg\pi)\chi(\mathcal F).
\]
\source{mumford-abelian-varieties:page-0132}
\source{mumford-abelian-varieties:page-0133}
\end{theorem}
\begin{proof}
It is enough to treat the case $V=U/G$ for a free action, since
$(X\times F)\to(X\times F)/G\to X/G$ reduces the general case to the
composite and first morphism. Suppose the assertion fails, and choose a
counterexample $\mathcal F$ minimal by support. Let $\mathcal J$ annihilate
$\mathcal F$ and write $V'$ for its support, $U'=\pi^{-1}(V')$. The quotient
proposition shows that $U'\to V'$ remains a principal $G$-space. Thus we
may assume the assertion holds for every coherent sheaf with proper support.
Exact sequences and flatness then show it also holds for extensions whenever
it holds for two terms.

If $V$ is reducible, a short exact sequence with both terms supported on
proper closed subsets gives a contradiction. If the nilpotent ideal
$\mathcal J$ of $V$ is nonzero, the exact sequence
\[
0\to\mathcal J\mathcal F\to\mathcal F\to
\mathcal F/\mathcal J\mathcal F\to0
\]
does the same. Hence assume $V$ reduced and irreducible. If $r$ is the
generic rank of $\mathcal F$, there is an ideal $\mathcal J$ and an
injection $\mathcal F^r\to\mathcal F$ with proper-support cokernel.
Consequently it suffices to prove the formula for $\mathcal O_V$.

Apply it to $\pi_*\mathcal O_U$, a coherent sheaf of nonzero rank. By the
projection formula,
\[
\begin{aligned}
\chi(\pi^*\pi_*\mathcal O_U)
 &=\chi(\mathcal O_V\otimes_{\mathcal O_V}\pi_*\mathcal O_U)\\
 &=(\deg\pi)\chi(\mathcal O_V)
 =(\deg\pi)\chi(\pi_*\mathcal O_U),
\end{aligned}
\]
which proves the assertion.
\end{proof}

\begin{remark}[Finite étale maps as associated spaces]
\label{mumford-rem-symmetric-associated-space}
\dcref{M:ch3:III.12}
Every finite étale morphism $f:U\to V$ of constant degree $n$ is an
associated finite-fibre fibration for a principal $\Sigma(n)$-space. In the
$n$-fold fibre product $U\times_V\cdots\times_VU$, let $P$ be the open and
closed locus of tuples with pairwise distinct entries. Then $P\to V$ is a
principal $\Sigma(n)$-space. If $F$ is the reduced $n$-point scheme with
the natural permutation action, the invariant map
\[
P\times F\longrightarrow V,
\qquad ((x_1,\ldots,x_n),i)\longmapsto x_i
\]
has quotient $V$ and identifies the associated space with $U$.
\source{mumford-abelian-varieties:page-0133}
\source{mumford-abelian-varieties:page-0134}
\uses{mumford-thm-euler-associated-fibration}
\end{remark}

\section{The dual abelian variety in any characteristic}
\label{mumford-III13-source}
\dcref{M:ch3:III.13}

\begin{definition}[Scheme-theoretic stabilizer of a line bundle]
\label{mumford-def-KL}
\dcref{M:ch3:III.13}
For a line bundle $L$ on an abelian variety $X$, put
\[
M=m^*L\otimes p_1^*L^{-1}\otimes p_2^*L^{-1}
\]
on $X\times X$. The group scheme $K(L)\subset X$ is the maximal closed
subscheme for which $M|_{K(L)\times X}$ is trivial. Equivalently, for every
scheme $S$ and $f:S\to X$, one has $f\in K(L)(S)$ exactly when
\[
T_f^*L_S\simeq L_S\otimes p_2^*N
\]
for a line bundle $N$ on $S$.
\source{mumford-abelian-varieties:page-0134}
\source{mumford-abelian-varieties:page-0135}
\end{definition}
\begin{proof}
The composite $X\times S\xrightarrow{T_f}X\times S\to X$ is
$m\circ(1_X\times f)$, so
$T_f^*L_S\simeq(1_X\times f)^*m^*L$. Restricting a putative isomorphism
to $\{0\}\times S$ identifies $N$ with $f^*L$. Hence the displayed
condition is equivalent to triviality of $(1_X\times f)^*M$, which is the
defining universal property of $K(L)$. In particular $K(L)$ is a subgroup
scheme of $X$.
\end{proof}

\begin{construction}[Dual quotient and normalized Poincare bundle]
\label{mumford-thm-dual-any-characteristic}
\label{mumford-prop-abelian-quotient}
\dcref{M:ch3:III.13}
\uses{mumford-def-KL,mumford-prop-maximal-triviality-scheme,
 mumford-thm-finite-groupscheme-quotient}
Choose an ample line bundle $L$ on $X$. Then $K(L)$ is finite. The quotient
\[
\pi:X\longrightarrow\widehat X=X/K(L)
\]
is an abelian variety. The bundle $M$ above admits a canonical
$K(L)$-linearization and descends uniquely to a normalized line bundle $P$ on
$\widehat X\times X$. Its restrictions to $\{0\}\times X$ and
$\widehat X\times\{0\}$ are trivial, and
\[
\widehat X\xrightarrow{\sim}\operatorname{Pic}^0X
\]
identifies the fibre of $P$ over $\alpha$ with the corresponding algebraically
trivial line bundle on $X$.
\source{mumford-abelian-varieties:page-0135}
\source{mumford-abelian-varieties:page-0136}
\end{construction}
\begin{proof}
For $x\in K(L)(S)$, write $T_x^*L_S\simeq L_S\otimes L_0$ with $L_0$ from
$S$. Then translation by $(x,0)$ preserves $M_S$. Any two lifts to $M_S$
differ by a global unit; the restriction map from $X_S\times_SX_S$ to
$X_S\times_S\{0\}$ is an isomorphism on units. Rigidifying along the second
factor therefore selects a unique lift, and these lifts form a group action.
Faithfully flat descent for the finite quotient gives $P$ and its uniqueness.
The map $X\to\operatorname{Pic}^0X$, $x\mapsto T_x^*L\otimes L^{-1}$, is
constant on $K(L)$ and has kernel $K(L)$, so the induced map from $\widehat X$
is the displayed isomorphism.
\end{proof}

\begin{theorem}[Universal Poincare mapping property]
\label{mumford-thm-poincare-universal-mapping}
\dcref{M:ch3:III.13}
\uses{mumford-prop-maximal-triviality-scheme,mumford-cor-structure-sheaf-cohomology}
Let $S$ be a scheme and $L$ a line bundle on $S\times X$, trivial on
$S\times\{0\}$, whose restriction to every fibre $\{s\}\times X$ lies in
$\operatorname{Pic}^0X$. There is a unique morphism $\phi:S\to\widehat X$
such that $L\simeq(\phi\times1_X)^*P$.
\source{mumford-abelian-varieties:page-0136}
\source{mumford-abelian-varieties:page-0137}
\source{mumford-abelian-varieties:page-0138}
\source{mumford-abelian-varieties:page-0139}
\source{mumford-abelian-varieties:page-0140}
\end{theorem}
\begin{proof}
Put $M=p_{23}^*P\otimes p_{13}^*L^{-1}$ on
$S\times\widehat X\times X$ and let $\Gamma_S$ be its maximal triviality
subscheme. Uniqueness and existence reduce to proving
$\Gamma_S\to S$ is an isomorphism. By localization and base change assume
$S=\operatorname{Spec}B$ is finite local and twist $L$ so its closed fibre
is trivial. The direct images along $S\times\widehat X\times X\to S\times X$
have discrete support, so Leray gives free $B$-modules
\[
H^p(S\times\widehat X\times X,M)
\simeq H^0(S\times X,R^pp_{13,*}M).
\]
The direct images along $S\times\widehat X\times X\to S\times\widehat X$
are supported at $(s,0)$ and are computed by a finite free complex
$0\to K_0\to\cdots\to K_g\to0$ over
$A=B\otimes_k\mathcal O_{0,\widehat X}$.

We use the following regular-local-ring lemma: if $\mathcal O$ is regular of
dimension $g$ and a length-$g$ complex of finite free modules has artinian
cohomology, then $H^i=0$ for $i<g$. For $g>0$, choose
$x\in\mathfrak M\setminus\mathfrak M^2$, reduce the complex modulo $x$,
and use the long exact cohomology sequence and induction on $g$; Nakayama
then gives the vanishing. Applying the lemma and its dual to the complex
above gives an artinian terminal module $K\simeq A/\mathfrak Q$, with
$\mathfrak Q\cap B=0$. For every $\mathfrak M$-primary ideal $\mathfrak b$,
\[
H^0(V(\mathfrak b)\times X,M)
\simeq\operatorname{Hom}_A(A/\mathfrak Q,A/\mathfrak b).
\]
The evaluation map is surjective after reduction at the closed point, hence
$M$ is trivial over $V(\mathfrak Q)\times X$ and
$\Gamma_S=V(\mathfrak Q)$. Its fibre is the reduced point $(s,0)$, so
$A/(\mathfrak Q+\mathfrak M_A)=k$ and $B\to A/\mathfrak Q$ is an
isomorphism. Thus $\Gamma_S\to S$ is an isomorphism, proving the universal
mapping property.
\end{proof}

\begin{corollary}[Cohomology of the Poincare bundle]
\label{mumford-cor-poincare-cohomology}
\dcref{M:ch3:III.13}
\uses{mumford-thm-poincare-universal-mapping}
For an abelian variety $X$ of dimension $g$ and its dual $\widehat X$,
\[
H^i(\widehat X\times X,P)=
\begin{cases}0&i\ne g,\\ k&i=g.\end{cases}
\]
\source{mumford-abelian-varieties:page-0140}
\source{mumford-abelian-varieties:page-0141}
\end{corollary}
\begin{proof}
With $S=\operatorname{Spec}k$ and the trivial bundle in the universal
mapping proof, the resulting complex is a free resolution of $k$ over the
regular local ring $\mathcal O_{0,\widehat X}$. Comparing it with the
Koszul resolution on a basis $x_1,\ldots,x_g$ of the maximal ideal modulo
its square gives the asserted cohomology. Explicitly, the Koszul differential
is
\[
d_p(e_{i_1}\wedge\cdots\wedge e_{i_p})=
\sum_{j=1}^p(-1)^j x_{i_j}e_{i_1}\wedge\cdots\widehat e_{i_j}\cdots\wedge e_{i_p}.
\]
\end{proof}

\begin{corollary}[Structure-sheaf cohomology]
\label{mumford-cor-structure-sheaf-cohomology}
\dcref{M:ch3:III.13}
\uses{mumford-cor-poincare-cohomology}
For $\dim X=g$,
\[
\dim_kH^p(X,\mathcal O_X)=\binom gp.
\]
\source{mumford-abelian-varieties:page-0141}
\end{corollary}
\begin{proof}
The cohomology is that of the Koszul complex tensored with $k$; all its
differentials vanish, and the rank of its $p$-cochains is $\binom gp$.
\end{proof}

\begin{corollary}[Tangent space of the dual]
\label{mumford-cor-tangent-dual-h1}
\dcref{M:ch3:III.13}
\uses{mumford-thm-poincare-universal-mapping}
There is a canonical isomorphism
$T_0\widehat X\simeq H^1(X,\mathcal O_X)$.
\source{mumford-abelian-varieties:page-0141}
\source{mumford-abelian-varieties:page-0142}
\end{corollary}
\begin{proof}
For $S=\operatorname{Spec}k[\epsilon]/(\epsilon^2)$, the universal property
identifies $T_0\widehat X$ with the kernel of restriction from line bundles
on $S\times X$ trivial on the closed fibre. The exact sequence
\[
1\to1+\epsilon\mathcal O_X\to\mathcal O_{S\times X}^*\to
\mathcal O_X^*\to1,
\qquad1+\epsilon\mathcal O_X\simeq\mathcal O_X,
\]
gives the result.
\end{proof}

\begin{corollary}[Dual isogenies]
\label{mumford-cor-dual-isogeny-degree}
\dcref{M:ch3:III.13}
\uses{mumford-thm-poincare-universal-mapping,mumford-thm-euler-associated-fibration}
If $f:X\to Y$ is an isogeny, there is a unique homomorphism
$\widehat f:\widehat Y\to\widehat X$ with
\[
(1\times\widehat f)^*P_X\simeq(f\times1)^*P_Y,
\]
and $\deg f=\deg\widehat f$.
\source{mumford-abelian-varieties:page-0141}
\source{mumford-abelian-varieties:page-0142}
\end{corollary}
\begin{proof}
The universal property gives $\widehat f$. Applying the Euler
characteristic formula for a finite flat associated fibre space to the two
pullbacks gives
\[
\chi((1\times\widehat f)^*P_X)=\deg\widehat f\,\chi(P_X),\qquad
\chi((f\times1)^*P_Y)=\deg f\,\chi(P_Y).
\]
Since both Poincare bundles have Euler characteristic $(-1)^g$, the degrees
are equal.
\end{proof}

\begin{corollary}[The morphism associated to a line bundle]
\label{mumford-cor-line-bundle-morphism}
\label{mumford-prop-phi-L}
\dcref{M:ch3:III.13}
\uses{mumford-thm-poincare-universal-mapping,mumford-prop-maximal-triviality-scheme}
For every line bundle $L$ on $X$, $\phi_L:X\to\operatorname{Pic}^0X\simeq
\widehat X$ is a morphism and its scheme-theoretic kernel is $K(L)$.
\source{mumford-abelian-varieties:page-0142}
\end{corollary}
\begin{proof}
The universal property applied to
$m^*L\otimes p_1^*L^{-1}\otimes p_2^*L^{-1}$ gives the morphism. The
definition of $K(L)$ as the maximal subscheme on which this bundle is
trivial is exactly the scheme-theoretic kernel.
\end{proof}

\begin{proposition}[Divisorial correspondences]
\label{mumford-prop-divisorial-correspondence}
\dcref{M:ch3:III.13}
\uses{mumford-thm-poincare-universal-mapping,mumford-thm-euler-associated-fibration}
Let $Q$ be a line bundle on $X\times Y$, with trivial restrictions to the
two coordinate factors, and $\dim X=\dim Y$. The following are equivalent:
\begin{enumerate}
\item no nonzero subscheme of $X$ makes $Q$ trivial;
\item no nonzero subscheme of $Y$ makes $Q$ trivial;
\item $|\chi(Q)|=1$.
\end{enumerate}
When they hold, $Y\simeq\widehat X$ and $X\simeq\widehat Y$.
\source{mumford-abelian-varieties:page-0142}
\source{mumford-abelian-varieties:page-0143}
\end{proposition}
\begin{proof}
The universal property gives $f:Y\to\widehat X$ with
$Q=(1_X\times f)^*P$. Condition (2) says that $f$ has trivial kernel. Equal
dimensions then make $f$ an isogeny, and
$|\chi(Q)|=\deg f\,|\chi(P)|=\deg f$. Conversely, if $f$ has positive
dimensional kernel, finite subgroups of arbitrarily large order $d$ in the
kernel make $Q$ descend through $X\times Y/F$, so the Euler characteristic
is divisible by every such $d$ and is zero. This proves the equivalence.
\end{proof}

\begin{corollary}[Duality hypothesis]
\label{mumford-thm-duality-hypothesis}
\label{mumford-prop-biduality-any-characteristic}
\dcref{M:ch3:III.13}
The canonical morphism $X\to\widehat{\widehat X}$ defined by the Poincare
bundle is an isomorphism.
\source{mumford-abelian-varieties:page-0143}
\uses{mumford-prop-divisorial-correspondence}
\end{corollary}
\begin{proof}
The Poincare bundle satisfies condition (2) of the preceding proposition,
and hence also (1), so the induced morphism is an isomorphism.
\end{proof}

\section{Duality of finite commutative group schemes}
\label{mumford-III14-source}
\dcref{M:ch3:III.14}

\begin{definition}[Cartier dual]
\label{mumford-def-cartier-dual}
\dcref{M:ch3:III.14}
For a finite commutative group scheme $G=\operatorname{Spec}R$ in
characteristic $p>0$, the dual group scheme is
$\widehat G=\operatorname{Spec}R^*$, where the dual of the group-law
coproduct is the multiplication on $R^*$ and the dual of multiplication on
$R$ is its coproduct.
\source{mumford-abelian-varieties:page-0143}
\source{mumford-abelian-varieties:page-0144}
\end{definition}

\begin{theorem}[Cartier dual represents characters]
\label{mumford-thm-cartier-duality}
\dcref{M:ch3:III.14}
\uses{mumford-def-cartier-dual}
For every scheme $S$,
\[
\widehat G(S)\simeq\operatorname{Hom}_S(G_S,\mathbb G_{m,S}),
\]
functorially in $S$.
\source{mumford-abelian-varieties:page-0144}
\source{mumford-abelian-varieties:page-0145}
\source{mumford-abelian-varieties:page-0146}
\end{theorem}
\begin{proof}
For $S=\operatorname{Spec}A$, a homomorphism to $\mathbb G_m$ is an
$\alpha\in R\otimes A$ satisfying
$\mu_R(\alpha)=\alpha\otimes\alpha$ and $\epsilon(\alpha)=1$.
The latter condition implies invertibility, using the inverse map. Since
$R\otimes A\simeq\operatorname{Hom}_A((R\otimes A)^*,A)$, these elements
are precisely algebra homomorphisms $A^*\otimes A\to A$, i.e. $A$-points of
$\operatorname{Spec}R^*$. The construction is natural and respects group
laws. Taking $S=\widehat G$ gives the universal bilinear character
$\widehat G\times G\to\mathbb G_m$.
\end{proof}

\begin{proposition}[Local/reduced decomposition]
\label{mumford-prop-cartier-local-reduced}
\dcref{M:ch3:III.14}
\uses{mumford-thm-cartier-duality}
Every finite commutative group scheme has a unique product decomposition
$G_{r,r}\times G_{r,l}\times G_{l,r}\times G_{l,l}$ according as it and
its Cartier dual are reduced or local. Groups of type $(r,r)$ are products
of cyclic groups of order prime to $p$; groups of type $(r,l)$ are products
of cyclic $p$-groups and type $(l,r)$ are their duals.
\source{mumford-abelian-varieties:page-0147}
\end{proposition}
\begin{proof}
If $G$ is reduced, it is uniquely expressible as a product $G_1\times G_2$,
where $G_1$ has order prime to $p$ and $G_2$ is a $p$-group. By duality,
$\widehat G_1$ is reduced and $\widehat G_2$ is local. When $G$ is local,
splitting $\widehat G$ into local and reduced parts and dualizing back proves
the analogous assertion. The only groups of type $(r,r)$ are reduced groups
of order prime to $p$, hence products of cyclic prime-power groups with
primes distinct from $p$. The only groups of type $(r,l)$ are $p$-groups,
hence products of $\mathbb Z/p^{n_i}\mathbb Z$'s; the groups of type $(l,r)$
are their duals. Applying these decompositions to the four possible types
gives the asserted unique product decomposition.
\end{proof}

\begin{proposition}[Primitive elements and the Lie algebra]
\label{mumford-prop-cartier-primitives}
\dcref{M:ch3:III.14}
\uses{mumford-thm-cartier-duality,mumford-prop-group-scheme-lie}
\[
\operatorname{Hom}_{\mathrm{Gp.Sch}}(\widehat G,\mathbb G_a)
\simeq\{\alpha\in R^*:s^*\alpha=\alpha\otimes1+1\otimes\alpha\}
\simeq\Lie(G).
\]
The $p$-power operation corresponds to composition with Frobenius.
\source{mumford-abelian-varieties:page-0148}
\source{mumford-abelian-varieties:page-0149}
\end{proposition}
\begin{proof}
For $\alpha(1)=0$ and $\alpha(\mathfrak M^2)=0$, the transpose of $\alpha$
is a derivation. Primitive elements are exactly these invariant derivations,
and the coproduct calculation gives the displayed bijections.
\end{proof}

\begin{definition}[Height one]
\label{mumford-def-height-one-group}
\dcref{M:ch3:III.14}
A finite group scheme is of height one if it has one point $e$ and
$x^p=0$ for every $x$ in the maximal ideal at $e$.
\source{mumford-abelian-varieties:page-0150}
\end{definition}

\begin{theorem}[Height-one group schemes and $p$-Lie algebras]
\label{mumford-thm-height-one-equivalence}
\dcref{M:ch3:III.14}
\uses{mumford-prop-cartier-primitives}
The functor $G\mapsto\Lie G$ is an equivalence between finite commutative
height-one group schemes and finite-dimensional $p$-Lie algebras.
\source{mumford-abelian-varieties:page-0150}
\source{mumford-abelian-varieties:page-0151}
\source{mumford-abelian-varieties:page-0152}
\end{theorem}
\begin{proof}
For a $p$-Lie algebra $\mathfrak g$, set
$U(\mathfrak g)=S(\mathfrak g)/\langle\alpha^{(p)}-\alpha^p\rangle$ and
$G(\mathfrak g)=\operatorname{Spec}U(\mathfrak g)^*$. The coproduct
$s(\alpha)=1\otimes\alpha+\alpha\otimes1$ makes this a finite group
scheme of height one. Primitive elements identify its Lie algebra with
$\mathfrak g$. Conversely, the inclusion $\Lie G\to R^*$ extends to a
bialgebra map $U(\Lie G)\to R^*$; its transpose is a group morphism.
The differential is an isomorphism, hence the morphism is a closed immersion
by Nakayama, and both coordinate rings have dimension
$p^{\dim\Lie G}$, so it is an isomorphism.
\end{proof}

\begin{corollary}[Actions of height-one groups]
\label{mumford-cor-height-one-actions}
\dcref{M:ch3:III.14}
\uses{mumford-thm-height-one-equivalence}
For a commutative height-one $G$ with Lie algebra $\mathfrak g$, an action on
$X$ is equivalent to derivations $D_\alpha$ satisfying
\[
[D_\alpha,D_\beta]=0,\qquad D_{\alpha^{(p)}}=D_\alpha^p.
\]
Moreover multiplication by $p$ on $G$ is zero.
\source{mumford-abelian-varieties:page-0152}
\source{mumford-abelian-varieties:page-0153}
\end{corollary}
\begin{proof}
The relations define a homomorphism from $U(\mathfrak g)$ to differential
operators. Transposing it gives
$\mathcal O_X\to R\otimes\mathcal O_X$; the unit and composition diagrams
are exactly the action diagrams. The assertion about multiplication by $p$
follows because it kills the Lie algebra and the height-one equivalence is
faithful.
\end{proof}

\begin{corollary}[Semisimple/nilpotent decomposition]
\label{mumford-cor-p-lie-semisimple-nilpotent}
\dcref{M:ch3:III.14}
\uses{mumford-thm-height-one-equivalence}
Any vector space with a $p$-linear operation decomposes uniquely as
$V=V_s\oplus V_n$, with a basis of fixed vectors on $V_s$ and nilpotent
$p$-operation on $V_n$. For a height-one group this is the decomposition
$\Lie G_{l,r}\oplus\Lie G_{l,l}$.
\source{mumford-abelian-varieties:page-0153}
\source{mumford-abelian-varieties:page-0154}
\end{corollary}
\begin{proof}
For a height-one group scheme, the local/reduced decomposition gives
\[
G=G_{l,r}\times G_{l,l}.
\]
Both factors are again of height one. Since $G_{l,r}$ is killed by $p$, it
is isomorphic to $\mu_p^n$ for some $n$. As $\Lie(\mu_p)$ has a generator
$e$ with $e^{(p)}=e$, the induced decomposition
\[
\Lie G=\Lie G_{l,r}\oplus\Lie G_{l,l}=\mathfrak g_1\oplus\mathfrak g_2
\]
gives a basis $e_1,\ldots,e_n$ of $\mathfrak g_1$ with
$e_i^{(p)}=e_i$. Since $G_{l,l}$ is local and $\mathfrak g_2$ is contained
in the maximal ideal of $\Gamma(\mathcal O_{G_{l,l}})$, every
$\alpha\in\mathfrak g_2$ satisfies $\alpha^{(p^m)}=0$ for $m$ sufficiently
large. Thus the displayed decomposition is invariant under the $p$-linear
operation, with the first summand having a basis of fixed vectors and the
second having nilpotent $p$-operation. The height-one equivalence identifies
these summands with $\Lie G_{l,r}$ and $\Lie G_{l,l}$, respectively; the
uniqueness follows from the corresponding uniqueness of the group-scheme
decomposition.
\end{proof}

\section{Applications to abelian varieties}
\label{mumford-III15-source}
\dcref{M:ch3:III.15}

\begin{theorem}[Kernel of the dual isogeny]
\label{mumford-thm-dual-isogeny-kernel}
\dcref{M:ch3:III.15}
\uses{mumford-thm-cartier-duality,mumford-prop-translation-quotient-isogeny}
If $f:X\to Y$ is an isogeny with kernel $K$ and dual map
$\widehat f:\widehat Y\to\widehat X$ with kernel $K'$, then
$K'\simeq\widehat K$ canonically.
\source{mumford-abelian-varieties:page-0154}
\source{mumford-abelian-varieties:page-0155}
\source{mumford-abelian-varieties:page-0156}
\end{theorem}
\begin{proof}
For a line bundle $L$ on $Y$,
\[
\phi_{f^*L}(x)=\widehat f(\phi_L(f(x))).
\]
Thus $\widehat K(S)$ is the kernel of pullback between families of line
bundles on $S\times Y$ and $S\times X$. Since $S\times Y$ is the quotient
of $S\times X$ by the free action of $K$, these are liftings of the action
to $S\times X\times\mathbb A^1$. Completeness of $X$ makes a linear lift
independent of $x$, so it has the form
\[
k:(s,x,\alpha)\longmapsto(s,x+k,\chi(k,s)\alpha)
\]
for a character $\chi:K\times S\to\mathbb G_m$. Cartier duality identifies
these with $\widehat K(S)$, naturally in $S$.
\end{proof}

\begin{definition}[Height-one isogeny]
\label{mumford-def-height-one-isogeny}
\dcref{M:ch3:III.15}
\uses{mumford-def-height-one-group}
An isogeny $f:X\to Y$ is of height one if $k(X)^p\subset k(Y)$.
This is equivalent to its kernel being a height-one group scheme.
\source{mumford-abelian-varieties:page-0156}
\end{definition}
\begin{proof}
For a height-one isogeny, integral closure gives
$\mathcal O_{Y,0}\supset\{a^p:a\in\mathcal O_{X,0}\}$, so the kernel has
height one. Conversely, invariants of the height-one kernel on affine opens
are exactly the functions coming from $Y$.
\end{proof}

\begin{theorem}[Height-one isogenies and $p$-Lie subalgebras]
\label{mumford-thm-height-one-isogeny}
\dcref{M:ch3:III.15}
\uses{mumford-thm-height-one-equivalence}
Height-one isogenies out of $X$, up to isomorphism, correspond one-to-one to
$p$-Lie subalgebras of $\Lie X$.
\source{mumford-abelian-varieties:page-0157}
\end{theorem}
\begin{proof}
Such isogenies are determined by their height-one kernels, which are
subgroup schemes of $X_p$. The height-one equivalence identifies these with
$p$-Lie subalgebras of $\Lie X_p=\Lie X$.
\end{proof}

\begin{theorem}[Frobenius and the Hasse--Witt operation]
\label{mumford-thm-lie-dual-frobenius}
\dcref{M:ch3:III.15}
\uses{mumford-cor-tangent-dual-h1}
Under $\Lie\widehat X\simeq H^1(X,\mathcal O_X)$, the $p$-power operation
on $\Lie\widehat X$ is the Frobenius map on $H^1(X,\mathcal O_X)$.
\source{mumford-abelian-varieties:page-0158}
\source{mumford-abelian-varieties:page-0159}
\source{mumford-abelian-varieties:page-0160}
\source{mumford-abelian-varieties:page-0161}
\end{theorem}
\begin{proof}
For $D$ represented by an infinitesimal automorphism over
$k[\epsilon]/(\epsilon^2)$, take $p$ copies over
$k[\epsilon_1,\ldots,\epsilon_p]/(\epsilon_i^2)$. Their composite is
$1+s_1D+s_2D^2+\cdots+s_pD^p$. Specializing the elementary symmetric
functions by $s_1\mapsto0$, $s_p\mapsto\epsilon$ gives $D^{(p)}$.
For a group scheme this is translation by the $p$-power of the tangent
point. A tangent vector of the dual represented by a cocycle
$\{1+\epsilon f_{ij}\}$ therefore has $p$-power represented by
$\{1+\epsilon f_{ij}^p\}$, exactly Frobenius on $H^1(X,\mathcal O_X)$.
\end{proof}

\section{Cohomology of line bundles}
\label{mumford-III16-source}
\dcref{M:ch3:III.16}

\begin{theorem}[Riemann--Roch]
\label{mumford-thm-riemann-roch}
\dcref{M:ch3:III.16}
\uses{mumford-prop-degree-hilbert,mumford-thm-cube-varieties}
For $L\simeq\mathcal O_X(D)$ on a $g$-dimensional abelian variety,
\[
\chi(L)=\frac{(D^g)}{g!},\qquad \chi(L)^2=\deg\phi_L.
\]
\source{mumford-abelian-varieties:page-0161}
\source{mumford-abelian-varieties:page-0162}
\source{mumford-abelian-varieties:page-0163}
\end{theorem}
\begin{proof}
Twisting by $\operatorname{Pic}^0X$ does not change Euler characteristic.
For symmetric $L$, $n_X^*(L^m)\simeq L^{mn^2}$, so homogeneity gives
$\chi(L^n)=a(L)n^g/g!$. For very ample $L_i=\mathcal O(D_i)$, the polynomial
$g!\chi(L_1^{n_1}\otimes L_2^{n_2})$ equals
$((n_1D_1+n_2D_2)^g)$; taking $n_1=1,n_2=-1$ yields the first formula.

If $K(L)$ is finite, pullback of the Poincare bundle gives
\[
\chi(m^*L\otimes p_1^*L^{-1}\otimes p_2^*L^{-1})=(-1)^g\chi(L)^2.
\]
The quotient $X\times X\to X\times\widehat X$ has degree $\deg\phi_L$,
so the same expression is $(-1)^g\deg\phi_L$. If $K(L)$ is not finite,
 finite subgroups of arbitrarily large order force both quantities to vanish.
\end{proof}

\begin{remark}[Analytic degree and Pfaffian]
\label{mumford-source-pfaffian-degree}
\dcref{M:ch3:III.16}
Over $\mathbf C$, for $L=L(H,\alpha)$ with $K(L)$ finite,
\[
 \deg\phi_L=\operatorname{order}K(L)
 =\operatorname{order}(U^\perp/U)=\det(E(u_i,u_j)),
 \qquad |\chi(L)|=\sqrt{\det(E(u_i,u_j))}.
\]
Thus $|\chi(L)|$ is the Pfaffian of the skew matrix $(E(u_i,u_j))$ up to
sign, since $\operatorname{pf}(A)^2=\det A$.
\source{mumford-abelian-varieties:page-0165}
\end{remark}

\begin{theorem}[Vanishing and index]
\label{mumford-thm-line-bundle-index}
\dcref{M:ch3:III.16}
\uses{mumford-thm-riemann-roch,mumford-thm-cube-varieties}
If $K(L)$ is finite, there is a unique $i(L)$ with
$H^p(X,L)=0$ for $p\ne i(L)$ and $H^{i(L)}(X,L)\ne0$, and
$i(L^{-1})=g-i(L)$.
\source{mumford-abelian-varieties:page-0161}
\source{mumford-abelian-varieties:page-0164}
\end{theorem}
\begin{proof}
The Cartesian diagram for $1\times\phi_L$ and flatness gives
\[
\dim H^q(X\times X,m^*L\otimes p_1^*L^{-1})=
\begin{cases}0&q\ne g,\\\deg\phi_L&q=g.\end{cases}
\]
Kunneth therefore gives
\[
\sum_{i=0}^qh^i(L)h^{q-i}(L^{-1})=
\begin{cases}0&q\ne g,\\\deg\phi_L&q=g.\end{cases}
\]
Nonnegativity forces exactly one nonzero group on each side and their
indices sum to $g$.
\end{proof}

\begin{lemma}[Polynomial growth of cohomology]
\label{mumford-lem-index-growth}
\dcref{M:ch3:III.16}
For a projective $r$-fold and line bundles $L_1,\ldots,L_k$, there is $c$
such that
\[
\dim H^i(L_1^{a_1}\otimes\cdots\otimes L_k^{a_k})
<c(1+|a|^r).
\]
\source{mumford-abelian-varieties:page-0166}
\source{mumford-abelian-varieties:page-0167}
\source{mumford-abelian-varieties:page-0168}
\end{lemma}
\begin{proof}
Twist by a sufficiently ample bundle to reduce to very ample bundles and
induct on $\dim X+k$. A hyperplane-section exact sequence compares the
cohomology for consecutive exponents with cohomology on a variety of
dimension $r-1$. The inductive bound is $c(1+|a|^{r-1})$; summing over the
exponent gives the asserted $c'(1+|a|^r)$, with negative exponents handled
by the reversed exact sequence.
\end{proof}

\begin{theorem}[Index polynomial]
\label{mumford-thm-index-polynomial}
\dcref{M:ch3:III.16}
If $L$ is ample and $M$ non-degenerate on a $g$-fold, the polynomial
$P(t)=\chi(L^t\otimes M)$ has all roots real, and $i(M)$ is the number of
positive roots counted with multiplicity.
\source{mumford-abelian-varieties:page-0166}
\source{mumford-abelian-varieties:page-0168}
\source{mumford-abelian-varieties:page-0169}
\source{mumford-abelian-varieties:page-0170}
\source{mumford-abelian-varieties:page-0171}
\uses{mumford-lem-index-growth,mumford-thm-line-bundle-index}
\end{theorem}
\begin{proof}
Step A: if $P(1,t)\ne0$ for $0<t<1$, then
$i(L)=i(L\otimes H)$. Otherwise choose the first exponent at which the
index changes. The hyperplane exact sequence gives cohomology on a
dimension $g-1$ section at least $N^gP(1,a/N)$, contradicting the growth
lemma as $N$ tends to infinity.

Step B: for $F(s,t)=\chi(L_1^s\otimes L_2^t)$, nonvanishing of
$F(t,1-t)$ on $(0,1)$ and Step A applied after inserting a very ample $L_3$
give equality of the indices of $L_1$ and $L_2$.

Step C: if all three of $L_1,L_2,L_1\otimes L_2$ are non-degenerate, apply
the map $(x,y)\mapsto x-y$ and Leray to obtain
$i(L_1\otimes L_2)\le i(L_1)+i(L_2)$. Step D compares the indices along a
segment whose Euler polynomial has a unique zero of multiplicity $\lambda$;
the hyperplane exact sequences and the growth lemma give
\(0<i(L_2)-i(L_1)\le\lambda\).

For completeness, the final induction in the source takes hyperplane powers
$H^\alpha$ and proves
\[
H^p(H^\alpha,L_1^k\otimes L_2^l)=0\quad(p<i_2-\alpha-1)
\]
from the exact sequence
\[
0\to L_1^{k-1}\otimes L_2^{l+1}|_{H^{\alpha-1}}
\to L_1^k\otimes L_2^l|_{H^{\alpha-1}}
\to L_1^k\otimes L_2^l|_{H^\alpha}\to0.
\]
The resulting injection and the growth estimate yield
\[
\left|f\left(\frac{r}{N},\frac{s}{N}\right)\right|<\frac{c}{N^{i_2-i_1}},
\qquad
\left|f\left(\frac{r}{N},\frac{s}{N}\right)\right|>\frac{c'}{N^\lambda},
\]
so $i_2-i_1\le\lambda$ and the theorem follows.
\end{proof}

\begin{remark}[Completion of the index root count]
\label{mumford-rem-index-root-count-conclusion}
\dcref{M:ch3:III.16}
\uses{mumford-thm-index-polynomial}
For $P(n,m)=\chi(L^n\otimes M^m)$, choose $q>0$ and integers $r_i$ with
$q^{-1}(r_i-1)<t_i<q^{-1}r_i$, where $t_i$ are the real roots of
$P(t,1)$. By the preceding index comparisons,
\[
i(r_k)\le i(r_k-1)=i(r_{k-1})\le\cdots\le i(r_1-1)=i(0),
\]
and $i(r_i-1)-i(r_i)\le\lambda_i$. For large positive $r$, $i(r)=0$,
and for large negative $r$, $i(r)=g$. Hence
\[
g=i(\text{very negative }r)-i(\text{very positive }r)\le\sum_i\lambda_i.
\]
Since $P$ has degree at most $g$, equality holds; $i(0)=i(M)$ is the sum
of multiplicities of positive roots.
\source{mumford-abelian-varieties:page-0172}
\source{mumford-abelian-varieties:page-0173}
\end{remark}

\begin{corollary}[Complex index and eigenvalues]
\label{mumford-cor-complex-index-negative-eigenvalues}
\dcref{M:ch3:III.16}
\uses{mumford-thm-index-polynomial}
If $X=V/U$ and $L=L(H,\alpha)$ is non-degenerate, then $i(L)$ is the
number of negative eigenvalues of $H$. Choosing an ample
$L_0=L(H_0,\alpha_0)$,
\[
\chi(L_0^n\otimes L)=\operatorname{pf}(nE_0+E),
\qquad E=\operatorname{Im}H.
\]
Diagonalizing relative to $H_0$, $H(e_i,e_j)=\lambda_i\delta_{ij}$, the
Pfaffian is $\prod_i(n+\lambda_i)$, proving the assertion.
\source{mumford-abelian-varieties:page-0173}
\source{mumford-abelian-varieties:page-0174}
\end{corollary}

\section{Very ample line bundles}
\label{mumford-III17-source}
\dcref{M:ch3:III.17}

\begin{theorem}[Very ampleness of powers]
\label{mumford-thm-high-power-very-ample}
\dcref{M:ch3:III.17}
\uses{mumford-thm-index-polynomial,mumford-cor-complex-index-negative-eigenvalues}
For any ample line bundle $L$ on an abelian variety $X$, $L^n$ is very ample
if $n>3$.
\source{mumford-abelian-varieties:page-0174}
\source{mumford-abelian-varieties:page-0175}
\source{mumford-abelian-varieties:page-0176}
\end{theorem}
\begin{proof}
It suffices to prove the assertion for $L^3$. Choose an effective divisor
$D$ without multiple components. For $x,y\in X$,
\[
T_x^*D+T_y^*D+T_{-x-y}^*D\in|3D|.
\]
We establish: (1) for $x_0\ne x_1$, some $D'\in|3D|$ contains $x_0$ but
not $x_1$; (2) every tangent vector at $x_0$ is separated by some
$D'\in|3D|$. By translation assume $x_0=0$.

If (1) failed, then $\operatorname{Supp}D=\operatorname{Supp}D-x_1$, so
$x_1\in K(L)$. Quotienting by the finite group generated by $x_1$ and
comparing dimensions of sections gives a contradiction. Thus (1) holds.

If (2) failed for a nonzero tangent vector $t$, the invariant vector field
$T$ would be tangent to $D$ everywhere. Locally, $T(\phi)=\alpha\phi$.
In characteristic $0$ this forces $t=0$. In characteristic $p$, let
$H\subset K(L)$ be the smallest subgroup containing $t$; $D$ is invariant
under translations by $H$.

Let $X'=X/H$, $D'=D/H$. The quotient $\pi:X\to X'$ is flat and
surjective, $D'$ is a divisor, and $D=\pi^*D'$. Thus
\[
\mathcal O_X(-D)\simeq
\mathcal O_{X'}(-D')\otimes_{\mathcal O_{X'}}\mathcal O_X.
\]
Comparing dimensions of sections on $X$ and $X'$ gives a contradiction.
Therefore (2) holds.
\end{proof}

\label{mumford-IV18}
\dcref{M:ch4:IV.18}

\begin{theorem}[Etale covers inherit the abelian structure]
\label{mumford-thm-etale-cover-abelian-structure}
Let $A$ be an abelian variety and let $u:Y\to A$ be a connected finite etale
cover with a chosen point above $0$.  There is a unique group law on $Y$ for
which that point is zero and $u$ is a homomorphism; $u$ is then a separable
isogeny.
\dcref{M:ch4:IV.18}
\uses{mumford-def-abelian-variety,mumford-prop-abelian-quotient}
\notready
\end{theorem}

\begin{lemma}[Graph construction for an etale cover]
\label{mumford-lem-etale-cover-graph}
Pull back the graph of multiplication on $A$ along $u\times u\times u$.
The component through the selected zero projects isomorphically to
$Y\times Y$; its third projection supplies the multiplication in
Theorem~$\ref{mumford-thm-etale-cover-abelian-structure}$.  The
fibre-irreducibility step is an external input.
\dcref{M:ch4:IV.18}
\uses{mumford-thm-etale-cover-abelian-structure}
\notready
\end{lemma}

\begin{definition}[Tate module]
\label{mumford-def-tate-module}
\dcref{M:ch4:IV.18}
Let $A$ be an abelian variety over an algebraically closed field and let
$\ell\ne\operatorname{char}(k)$.  Its $\ell$-adic Tate module is
\[
 T_\ell(A)=\varprojlim_n A[\ell^n](k),
\]
with transition maps multiplication by $\ell$.  It is a free $\Zell$-module
of rank $2\dim A$.
\uses{mumford-prop-multiplication-n,mumford-thm-abelian-smooth,
 mumford-thm-etale-cover-abelian-structure}
\notready
\end{definition}

\begin{proposition}[Etale coverings and torsion]
\label{mumford-prop-etale-coverings-av}
Every connected finite etale cover of $A$ is the quotient by a finite subgroup
of translations (equivalently, it is a separable isogeny after choosing a
point over the origin).  The prime-to-$p$ part of the
geometric fundamental group is
\[
 \pi_1(A)^{(p')}\simeq\prod_{\ell\ne p}\Zell^{\,2\dim A},
\]
and in characteristic zero this is the full profinite completion of
$H_1(A(\C),\Z)$.
\dcref{M:ch4:IV.18}
\uses{mumford-def-tate-module,mumford-prop-abelian-quotient}
\notready
\end{proposition}

\begin{proposition}[Galois action]
\label{mumford-prop-galois-tate-action}
\dcref{M:ch4:IV.18}
If $A$ is defined over a field $K$, the absolute Galois group $G_K$ acts
continuously on $T_\ell(A)$, giving a representation
\[
 \rho_{A,\ell}:G_K\to\Aut_{\Zell}(T_\ell(A)).
\]
Every homomorphism of abelian varieties over $K$ is $G_K$-equivariant on Tate
modules.
\uses{mumford-def-tate-module}
\notready
\end{proposition}

\section[Structure of Hom(X, dual X)]{Structure of homomorphisms into the dual}
\label{mumford-IV19}
\dcref{M:ch4:IV.19}

\begin{definition}[Hom groups up to isogeny]
\label{mumford-def-hom-up-to-isogeny}
\dcref{M:ch4:IV.19}
For abelian varieties $A,B$, set
\[
 \Hom^0(A,B)=\Hom(A,B)\otimes_\Z\Q,\qquad
 \End^0(A)=\End(A)\otimes_\Z\Q.
\]
Composition makes abelian varieties and these rational Hom groups into a
category in which every isogeny is invertible.
\uses{mumford-thm-isogeny-factorization}
\notready
\end{definition}

\begin{theorem}[Tate-module faithfulness]
\label{mumford-thm-hom-tate-injective}
For $\ell\ne\operatorname{char}(k)$, the natural map
\[
 \Hom(A,B)\otimes\Zell\longrightarrow
 \Hom_{\Zell}(T_\ell(A),T_\ell(B))
\]
is injective.  Consequently $\Hom(A,B)$ is torsion-free and finitely
generated, hence free abelian of finite rank.
\dcref{M:ch4:IV.19}
\uses{mumford-def-tate-module,mumford-def-hom-up-to-isogeny}
\notready
\end{theorem}

\begin{theorem}[Poincare complete reducibility]
\label{mumford-thm-poincare-complete-reducibility}
If $B\subset A$ is an abelian subvariety, there is an abelian subvariety
$C\subset A$ such that $B\cap C$ is finite and $B+C=A$.  Thus $A$ is isogenous
to $B\times C$, and every abelian variety is isogenous to a product of simple
ones.
\dcref{M:ch4:IV.19}
\uses{mumford-def-polarization,mumford-thm-ample-finite-kernel}
\notready
\end{theorem}

\begin{corollary}[Endomorphism algebra of a simple variety]
\label{mumford-cor-simple-endomorphism-algebra}
\dcref{M:ch4:IV.19}
If $A$ is simple, $\End^0(A)$ is a finite-dimensional division algebra over
$\Q$.  If its center is $K$, and its rank over $K$ is $d^2$, then
$d^2[K:\Q]$ divides $(2\dim A)^2$; in characteristic zero the complex
multiplication condition is the existence of a commutative subfield of degree
$2\dim A$.
\uses{mumford-thm-poincare-complete-reducibility,mumford-thm-hom-tate-injective}
\notready
\end{corollary}

\begin{remark}[Neron--Severi/Rosati package]
\label{mumford-iv20-ns-rosati-symmetric}
After tensoring with $\Q$, the Neron--Severi group identifies with the
Rosati-symmetric endomorphisms.
\dcref{M:ch4:IV.20}
\uses{mumford-iv20-riemann-form-homomorphism-criterion,mumford-prop-pic-ns-sequence}
\notready
\end{remark}

\section{Supporting dependency interfaces}
\label{mumford-IV-coverage-register}
The following nodes expose proof interfaces and examples used by the duality and
l-adic constructions.  Detailed proofs are treated as external inputs where
the available evidence is insufficient for reconstruction.

\begin{lemma}[Fibre irreducibility]
\label{mumford-iv18-fiber-irreducibility-lemma}
For a proper smooth morphism with a section, the fibre through the selected
point is irreducible; an idempotent in the completed local ring would otherwise
contradict locality.
\dcref{M:ch4:IV.18}
\uses{mumford-lem-etale-cover-graph}
\notready
\end{lemma}

\begin{remark}[Isogeny quasi-inverse]
\label{mumford-iv18-isogeny-quasi-inverse}
Every isogeny admits a quasi-inverse after tensoring Hom with $\Q$, with
integral composites equal to multiplication by a positive integer.
\dcref{M:ch4:IV.18}
\uses{mumford-thm-isogeny-factorization}
\notready
\end{remark}

\begin{definition}[Fundamental-group inverse system]
\label{mumford-iv18-fundamental-group-inverse-system}
The inverse limit of deck groups of pointed finite etale covers defines
$\pi_1(A)$.  Its prime-to-$p$ part is the product of the Tate modules, and in
characteristic zero it is the profinite completion of the analytic lattice.
\dcref{M:ch4:IV.18}
\uses{mumford-thm-etale-cover-abelian-structure,mumford-def-tate-module}
\notready
\end{definition}

\begin{definition}[Hom up to isogeny]
\label{mumford-iv19-hom-up-to-isogeny}
$\Hom^0(A,B)=\Hom(A,B)\otimes_\Z\Q$ and
$\End^0(A)=\End(A)\otimes_\Z\Q$ form the isogeny category.
\dcref{M:ch4:IV.19}
\uses{mumford-def-hom-up-to-isogeny,mumford-iv18-isogeny-quasi-inverse}
\notready
\end{definition}

\begin{proposition}[Complex Hom lattice]
\label{mumford-iv19-complex-hom-lattice}
For complex uniformizations, an algebraic homomorphism lifts to a complex-linear
map carrying one period lattice into the other; hence Hom is a finitely
generated lattice of rank at most $4\dim A\dim B$.
\dcref{M:ch4:IV.19}
\uses{mumford-prop-torus-homomorphisms,mumford-iv19-hom-up-to-isogeny}
\notready
\end{proposition}

\begin{definition}[The l-adic Hom representation]
\label{mumford-iv19-ladic-representation}
Restriction to torsion gives
\[
 \Hom(A,B)\longrightarrow\Hom_{\Zell}(T_\ell A,T_\ell B),
\]
compatible with composition and Galois action.
\dcref{M:ch4:IV.19}
\uses{mumford-def-tate-module,mumford-prop-galois-tate-action}
\notready
\end{definition}

\begin{theorem}[Endomorphism characteristic polynomial]
\label{mumford-iv19-end-characteristic-polynomial}
For $u\in\End(A)$ there is a monic $P_u\in\Z[t]$ of degree $2\dim A$,
independent of $\ell$, with $P_u(T_\ell u)=0$ and
$\deg(n-u)=P_u(n)$.
\dcref{M:ch4:IV.19}
\uses{mumford-thm-hom-tate-injective,mumford-iv19-ladic-representation}
\notready
\end{theorem}

\begin{theorem}[Simple endomorphism algebra]
\label{mumford-iv19-simple-endomorphism-algebra}
For a simple $A$, $\End^0(A)$ is semisimple (a division algebra in the simple
case), and its center/index satisfy the dimension divisibility constraints
coming from the characteristic polynomial.
\dcref{M:ch4:IV.19}
\uses{mumford-iv19-end-characteristic-polynomial,
 mumford-thm-poincare-complete-reducibility}
\notready
\end{theorem}

\begin{definition}[Tate pairing]
\label{mumford-iv20-tate-pairing}
The Poincare bundle supplies compatible perfect pairings
$A[\ell^n]\times\Adual[\ell^n]\to\mu_{\ell^n}$ and an inverse-limit pairing
$T_\ell A\times T_\ell\Adual\to\Zell(1)$.
\dcref{M:ch4:IV.20}
\uses{mumford-def-weil-pairing-ladic}
\notready
\end{definition}

\begin{definition}[Riemann form]
\label{mumford-iv20-riemann-form-definition}
The alternating form associated with a line bundle is the Tate-module form
obtained from the pairing and $T_\ell(\phi_L)$, after a choice of Tate-twist
generator when an additive value is desired.
\dcref{M:ch4:IV.20}
\uses{mumford-def-riemann-form-algebraic,mumford-iv20-tate-pairing}
\notready
\end{definition}

\begin{theorem}[Skew-symmetry criterion]
\label{mumford-iv20-riemann-form-skew}
The Tate-module form attached to $u:A\to\Adual$ is alternating exactly when
$u$ is represented by a line bundle; ampleness makes it a polarization form.
\dcref{M:ch4:IV.20}
\uses{mumford-iv20-riemann-form-definition,mumford-thm-riemann-form-hom}
\notready
\end{theorem}

\begin{theorem}[Riemann-form homomorphism criterion]
\label{mumford-iv20-riemann-form-homomorphism-criterion}
Skew forms on the Tate module correspond to homomorphisms into the dual, and
the image of $\NS(A)$ is the Rosati-symmetric part of $\End^0(A)$.
\dcref{M:ch4:IV.20}
\uses{mumford-iv20-riemann-form-skew,mumford-prop-pic-ns-sequence}
\notready
\end{theorem}

\begin{theorem}[Exterior-product generator]
\label{mumford-iv20-riemann-wedge-generator}
Exterior powers of a Riemann form generate the top alternating line and recover
intersection numbers and Euler characteristics.
\dcref{M:ch4:IV.20}
\uses{mumford3-riemann-roch,mumford-iv20-riemann-form-definition}
\notready
\end{theorem}

\begin{theorem}[Degree determinant formula]
\label{mumford-iv20-degree-determinant}
The degree of an endomorphism is the determinant of its action on a Tate module;
the same determinant description applies to the associated Riemann form.
\dcref{M:ch4:IV.20}
\uses{mumford-iv19-end-characteristic-polynomial,mumford-iv20-tate-pairing}
\notready
\end{theorem}

\begin{theorem}[Albert classification interface]
\label{mumford-iv21-albert-classification}
A simple rational endomorphism algebra with its Rosati-positive involution is
of one of Albert's four types, subject to the center and Schur-index bounds.
\dcref{M:ch4:IV.21}
\uses{mumford-thm-rosati-positive,mumford-iv19-simple-endomorphism-algebra}
\notready
\end{theorem}

\begin{theorem}[Weil eigenvalues and point counts]
\label{mumford-iv21-weil-rational-point-count}
For $A/\Fq$, Frobenius eigenvalues have complex absolute value $q^{1/2}$,
occur in reciprocal pairs, and
$\#A(\mathbb{F}_{q^n})=\prod_i(1-\omega_i^n)$.
\dcref{M:ch4:IV.21}
\uses{mumford-def-frobenius-polynomial,mumford-thm-frobenius-semisimple}
\notready
\end{theorem}

\begin{theorem}[Finite-field rational-point finiteness]
\label{mumford-iv21-lang-rational-point}
The finite-field point-count and Frobenius estimates supply the finiteness
inputs used in the endomorphism and torsion arguments.
\dcref{M:ch4:IV.21}
\uses{mumford-iv21-weil-rational-point-count}
\notready
\end{theorem}

\begin{theorem}[Torsion restriction]
\label{mumford-iv21-serre-torsion-restriction}
For a nonzero endomorphism of an abelian variety, restriction to sufficiently
large prime-to-characteristic torsion is nontrivial; this makes the Tate action
faithful.
\dcref{M:ch4:IV.21}
\uses{mumford-thm-hom-tate-injective}
\notready
\end{theorem}

\begin{corollary}[Endomorphism type restrictions]
\label{mumford-iv21-endomorphism-type-table}
The Albert type, center degree, and Schur index of a simple factor satisfy the
dimension restrictions imposed by its positive Rosati involution.
\dcref{M:ch4:IV.21}
\uses{mumford-iv21-albert-classification}
\notready
\end{corollary}

\begin{example}[CM type over $\C$]
\label{mumford-iv22-cm-complex-example}
A complex abelian variety with a commutative endomorphism field of degree twice
its dimension is of CM type; its Riemann form is constrained by the CM action.
\dcref{M:ch4:IV.22}
\uses{mumford-iv19-simple-endomorphism-algebra,mumford-thm-riemann-comparison}
\notready
\end{example}

\begin{example}[Elliptic endomorphisms in characteristic $p$]
\label{mumford-iv22-elliptic-weierstrass-example}
Elliptic curves have rational endomorphism algebra $\Q$, an imaginary
quadratic field, or a quaternion algebra in the supersingular case.
\dcref{M:ch4:IV.22}
\uses{mumford-ex-elliptic-endomorphisms}
\notready
\end{example}

\begin{theorem}[Deuring equivalences]
\label{mumford-iv22-deuring-equivalences}
For elliptic curves over finite fields, the endomorphism and Frobenius
polynomial criteria give the standard ordinary/supersingular isogeny
equivalences.
\dcref{M:ch4:IV.22}
\uses{mumford-iv21-weil-rational-point-count,mumford-thm-frobenius-isogeny-criterion}
\notready
\end{theorem}

\begin{theorem}[CM and finite-field isogeny]
\label{mumford-iv22-cm-finite-field-isogeny}
Equality of the Frobenius polynomial is equivalent to isogeny over a finite
field, including the CM and supersingular elliptic examples.
\dcref{M:ch4:IV.22}
\uses{mumford-thm-frobenius-isogeny-criterion,mumford-iv22-deuring-equivalences}
\notready
\end{theorem}

\begin{lemma}[Theta-group prime-order commutativity]
\label{mumford-iv23-theta-group-triviality}
For a finite theta group of prime exponent, the commutator pairing controls
whether a subgroup is central and whether the extension splits locally.
\dcref{M:ch4:IV.23}
\uses{mumford-def-theta-group,mumford-prop-theta-commutator}
\notready
\end{lemma}

\begin{theorem}[Line-bundle theta group]
\label{mumford-iv23-line-bundle-theta-group}
Automorphisms of a line bundle over translations form the central extension
$1\to\Gm\to\mathcal G(L)\to K(L)\to1$.
\dcref{M:ch4:IV.23}
\uses{mumford-def-theta-group}
\notready
\end{theorem}

\begin{definition}[Divisor description of a theta group]
\label{mumford-iv23-divisor-description}
Choosing a divisor representative for $L$ identifies theta-group elements with
translation/divisor pairs and makes the commutator explicit.
\dcref{M:ch4:IV.23}
\uses{mumford-iv23-line-bundle-theta-group}
\notready
\end{definition}

\begin{theorem}[Theta lifting and descent]
\label{mumford-iv23-isogeny-lifting-theorem}
Descent of $L$ along an isogeny is equivalent to lifting its kernel into the
theta group; the descended bundle has the expected pullback.
\dcref{M:ch4:IV.23}
\uses{mumford-iv23-line-bundle-theta-group,mumford-prop-abelian-quotient}
\notready
\end{theorem}

\begin{theorem}[Power criterion for line bundles]
\label{mumford-iv23-power-criterion}
For nondegenerate $L$, containment of $A[n]$ in $K(L)$ is equivalent to $L$
being an $n$th tensor power after the corresponding descent obstruction
vanishes.
\dcref{M:ch4:IV.23}
\uses{mumford-iv23-isogeny-lifting-theorem,mumford-prop-multiplication-n}
\notready
\end{theorem}

\begin{theorem}[Maximal isotropic theta subgroup]
\label{mumford-iv23-maximal-isotropic-theorem}
For a nondegenerate theta group, a maximal isotropic subgroup equals its
commutator orthogonal and has square-root order in $K(L)$; this controls
principal polarizations and the irreducible theta representation.
\dcref{M:ch4:IV.23}
\uses{mumford-prop-theta-commutator,mumford-thm-theta-representation}
\notready
\end{theorem}

\begin{definition}[Analytic theta extension]
\label{mumford-iv24-analytic-theta-extension}
For a complex torus and Hermitian form $H$, automorphisms of the factor of
automorphy form a central Heisenberg extension whose commutator is determined
by $\operatorname{Im}H$ on the lattice.
\dcref{M:ch4:IV.24}
\uses{mumford-thm-appell-humbert,mumford-def-theta-group}
\notready
\end{definition}

\begin{theorem}[Analytic/l-adic pairing comparison]
\label{mumford-iv24-analytic-ladic-comparison}
Under the comparison between the analytic lattice and the Tate module, the
analytic theta commutator agrees with the Poincare pairing up to the fixed sign
convention.
\dcref{M:ch4:IV.24}
\uses{mumford-thm-riemann-comparison,mumford-iv20-tate-pairing}
\notready
\end{theorem}

\begin{theorem}[Analytic Rosati positivity]
\label{mumford-iv24-analytic-rosati}
For a positive Hermitian form, the Rosati involution is the Hermitian adjoint;
its trace form is positive definite, giving the analytic proof of Rosati
positivity.
\dcref{M:ch4:IV.24}
\uses{mumford-thm-riemann-comparison,mumford-thm-rosati-positive}
\notready
\end{theorem}

\begin{remark}[Serre--Lang structure theorem]
\label{mumford-iv18-etale-covering-abelian-structure}
The Serre--Lang theorem asserts that every connected finite etale cover in the
etale-covering construction acquires the abelian-variety structure displayed
in Theorem~$\ref{mumford-thm-etale-cover-abelian-structure}$.
\dcref{M:ch4:IV.18}
\uses{mumford-thm-etale-cover-abelian-structure}
\notready
\end{remark}

\begin{remark}[Etale graph-pullback construction]
\label{mumford-iv18-etale-graph-pullback}
The pulled-back multiplication graph and its distinguished component implement
the group law on the cover.
\dcref{M:ch4:IV.18}
\uses{mumford-lem-etale-cover-graph}
\notready
\end{remark}

\begin{remark}[Complete reducibility package]
\label{mumford-iv19-poincare-complete-reducibility}
Every abelian subvariety has an isogeny complement, so an abelian variety is
isogenous to a product of simple factors.
\dcref{M:ch4:IV.19}
\uses{mumford-thm-poincare-complete-reducibility}
\notready
\end{remark}

\begin{remark}[Finite-generation and injectivity package]
\label{mumford-iv19-hom-finite-generation-injectivity}
Hom groups are torsion-free finitely generated and their l-adic realization is
faithful for every prime away from the characteristic.
\dcref{M:ch4:IV.19}
\uses{mumford-thm-hom-tate-injective,mumford-iv19-complex-hom-lattice}
\notready
\end{remark}

\begin{remark}[Rosati trace package]
\label{mumford-iv21-rosati-positive-trace}
The reduced-trace pairing $(u,v)\mapsto\Trd(u^\dagger v)$ is positive
definite on the real endomorphism algebra.
\dcref{M:ch4:IV.21}
\uses{mumford-thm-rosati-positive}
\notready
\end{remark}

\begin{remark}[Theta-group definition]
\label{mumford-iv23-theta-group-definition}
The theta group is the central extension of $K(L)$ by scalar automorphisms of
the line bundle $L$.
\dcref{M:ch4:IV.23}
\uses{mumford-def-theta-group,mumford-iv23-line-bundle-theta-group}
\notready
\end{remark}

\section{Riemann forms}
\label{mumford-IV20}
\dcref{M:ch4:IV.20}

\begin{definition}[The $\ell$-adic Weil pairing]
\label{mumford-def-weil-pairing-ladic}
\dcref{M:ch4:IV.20}
For $\ell\ne\operatorname{char}(k)$, the Poincare bundle induces compatible
perfect pairings
\[
 e_{\ell^n}:A[\ell^n]\times\Adual[\ell^n]\to\mu_{\ell^n}.
\]
Their inverse limit is a perfect $\Zell$-bilinear pairing
$T_\ell(A)\times T_\ell(\Adual)\to\Zell(1)$.
\uses{mumford-prop-weil-pairing,mumford-def-tate-module}
\notready
\end{definition}

\begin{definition}[Riemann form of a polarization]
\label{mumford-def-riemann-form-algebraic}
\dcref{M:ch4:IV.20}
For a polarization $\lambda:A\to\Adual$, the finite-level multiplicative
pairings are
\[
 e_{\ell^n}^{\lambda}(x,y)=e_{\ell^n}(x,\lambda(y))
\]
on $A[\ell^n]\times A[\ell^n]$; their inverse limit is a pairing with values
in $\Zell(1)$.  After choosing a compatible generator of the Tate twist (or
passing to the associated additive lattice), this gives an alternating
$\Zell$-valued form.  It is nondegenerate over $\Qell$ and positive exactly
when $\lambda$ comes from an ample line bundle.
\uses{mumford-def-polarization,mumford-def-weil-pairing-ladic}
\notready
\end{definition}

\begin{theorem}[Homomorphisms represented by Riemann forms]
\label{mumford-thm-riemann-form-hom}
For $u:A\to\Adual$, the bilinear form
$(x,y)\mapsto e_\ell(x,u(y))$ is skew-symmetric if and only if
$u=\phi_L$ for a line bundle $L$ on $A$.  If $L$ is ample, this form is a
polarization Riemann form.
\dcref{M:ch4:IV.20}
\uses{mumford-prop-phi-L,mumford-def-weil-pairing-ladic}
\notready
\end{theorem}

\section[Positivity of Rosati]{Positivity of the Rosati involution}
\label{mumford-IV21}
\dcref{M:ch4:IV.21}

\begin{definition}[Rosati involution]
\label{mumford-def-rosati}
\dcref{M:ch4:IV.21}
For a polarization $\lambda:A\to\Adual$, the Rosati involution on
$\End^0(A)$ is
\[
 u^\dagger=\lambda^{-1}\circ\widehat u\circ\lambda.
\]
It is a positive involution: $u^\dagger u$ has positive reduced trace for
$u\ne0$.
\uses{mumford-def-polarization,mumford-prop-biduality-any-characteristic}
\notready
\end{definition}

\begin{theorem}[Trace-form positivity]
\label{mumford-thm-rosati-positive}
Using the reduced trace on each simple factor, the bilinear form
\[
 (u,v)\longmapsto\Trd_{\End^0(A)/\Q}(u^\dagger v)
\]
is symmetric and positive definite on $\End^0(A)\otimes_\Q\R$.  The
Rosati-symmetric subspace identifies with $\NS(A)\otimes\Q$, and ample classes
are exactly its positive elements.
\dcref{M:ch4:IV.21}
\uses{mumford-def-rosati,mumford-thm-riemann-form-hom,mumford-prop-pic-ns-sequence}
\notready
\end{theorem}

\begin{corollary}[Semisimplicity up to isogeny]
\label{mumford-cor-semisimple-endomorphism}
\dcref{M:ch4:IV.21}
The algebra $\End^0(A)$ is semisimple, and its simple factors are division
algebras equipped with positive involutions induced by Rosati.  The isogeny
decomposition of $A$ is unique up to permutation and isogeny of factors.
\uses{mumford-thm-rosati-positive,mumford-thm-poincare-complete-reducibility}
\notready
\end{corollary}

\section{Examples}
\label{mumford-IV22}
\dcref{M:ch4:IV.22}

\begin{example}[Elliptic curves]
\label{mumford-ex-elliptic-endomorphisms}
\dcref{M:ch4:IV.22}
For an elliptic curve $E$, $\End^0(E)$ is either $\Q$, an imaginary quadratic
field (complex multiplication), or a quaternion division algebra in the
supersingular characteristic-$p$ case.  The Rosati involution is complex
conjugation in the middle case and the standard positive involution in the
quaternionic case.
\uses{mumford-cor-simple-endomorphism-algebra,mumford-def-rosati}
\notready
\end{example}

\begin{example}[Products and matrix algebras]
\label{mumford-ex-product-endomorphisms}
\dcref{M:ch4:IV.22}
If $A=B^r$ with $B$ simple, then
$\End^0(A)\simeq M_r(\End^0(B))$ and the product polarization induces the
adjoint-transpose Rosati involution.  Non-isogenous simple factors give a
product decomposition of the endomorphism algebra.
\uses{mumford-cor-semisimple-endomorphism,mumford-thm-poincare-complete-reducibility}
\notready
\end{example}

\section[Theta groups]{The theta group of a line bundle}
\label{mumford-IV23}
\dcref{M:ch4:IV.23}

\begin{definition}[Theta group]
\label{mumford-def-theta-group}
\dcref{M:ch4:IV.23}
For a line bundle $L$ on $A$, the theta group $\mathcal G(L)$ is the group
scheme whose $S$-points are pairs $(x,\varphi)$ with $x\in K(L)(S)$ and
$\varphi:L_S\xrightarrow{\sim}t_x^*L_S$.  There is an exact sequence
\[
 1\longrightarrow\Gm\longrightarrow\mathcal G(L)\longrightarrow K(L)
 \longrightarrow1.
\]
\uses{mumford-def-KL}
\notready
\end{definition}

\begin{proposition}[Theta commutator]
\label{mumford-prop-theta-commutator}
\dcref{M:ch4:IV.23}
The commutator in the theta group is the alternating pairing
\[
 e^L:K(L)\times K(L)\to\Gm
\]
induced by the biextension of $L$.  If $L$ is nondegenerate, this pairing is
perfect and $|K(L)|$ is a square.
\uses{mumford-def-theta-group,mumford-def-biextension}
\notready
\end{proposition}

\begin{theorem}[Theta representation]
\label{mumford-thm-theta-representation}
When $L$ is ample, $\mathcal G(L)$ acts on $H^0(A,L)$.  Every irreducible
representation on which the central $\Gm$ acts by its tautological character
has dimension $h^0(A,L)$ and is unique up to isomorphism; the natural action on
$H^0(A,L)$ is that representation.
\dcref{M:ch4:IV.23}
\uses{mumford-prop-theta-commutator,mumford-thm-line-bundle-index}
\notready
\end{theorem}

\section[Complex comparison]{The complex case}
\label{mumford-IV24}
\dcref{M:ch4:IV.24}

\begin{theorem}[Analytic and algebraic Riemann forms agree]
\label{mumford-thm-riemann-comparison}
For a complex abelian variety $A(\C)=V/\Lambda$ and an ample line bundle $L$,
the algebraic Riemann form obtained from the Weil pairing is the integral
alternating form $\operatorname{Im}H$ in the Appell--Humbert description of the
analytic bundle.  Under this identification, the algebraic Rosati involution
is the adjoint involution for the positive Hermitian form $H$.
\dcref{M:ch4:IV.24}
\uses{mumford-thm-riemann-form-hom,mumford-thm-rosati-positive,mumford-thm-appell-humbert}
\notready
\end{theorem}

\begin{corollary}[Complex polarization dictionary]
\label{mumford-cor-complex-polarization-dictionary}
\dcref{M:ch4:IV.24}
Polarizations of $A$ correspond to positive integral Riemann forms on
$(V,\Lambda)$, principal polarizations to unimodular forms, and the theta
group of $L$ is the analytic Heisenberg extension attached to the finite
symplectic module $K(L)$.
\uses{mumford-thm-riemann-comparison,mumford-thm-theta-representation}
\notready
\end{corollary}

\label{mumford-AppI-setup}
\dcref{M:appI:I}

\begin{convention}[Finite-field arithmetic]
\label{mumford-conv-tate-fields}
\dcref{M:appI:I}
Let $k_0$ be a finite field, let $\bar k_0$ be an algebraic closure, and let
$A,B$ be abelian varieties defined over $k_0$.  For a prime $\ell\ne
\operatorname{char}(k_0)$, all Tate modules and Hom groups in this chapter
are taken over $\bar k_0$ with their natural Frobenius action.
\notready
\end{convention}

\begin{lemma}[Rationality of prime-to-$p$ torsion]
\label{mumford-lem-torsion-defined-over-finite-field}
\dcref{M:appI:I}
For an abelian variety over a finite field, every prime-to-$p$ torsion point is
defined over a finite extension, and Frobenius acts continuously on
$T_\ell(A)$.  The action on $A[\ell^n]$ is compatible with the Weil pairing.
\uses{mumford-conv-tate-fields,mumford-def-tate-module,mumford-prop-galois-tate-action}
\notready
\end{lemma}

\section{Tate's homomorphism theorem}
\label{mumford-AppI-tate-hom}
\dcref{M:appI:I}

\begin{theorem}[Tate isomorphism over a finite field]
\label{mumford-thm-tate-hom-isomorphism}
For abelian varieties $A,B$ over a finite field $k_0$ and every prime
$\ell\ne\operatorname{char}(k_0)$, the natural map
\[
 \Hom_{k_0}(A,B)\otimes_\Z\Zell
 \xrightarrow{\ \sim\ }
 \Hom_{\Zell[F]}(T_\ell(A),T_\ell(B))
\]
is an isomorphism, where $F$ denotes geometric Frobenius.
\dcref{M:appI:I}
\uses{mumford-lem-torsion-defined-over-finite-field,mumford-thm-hom-tate-injective}
\notready
\end{theorem}

\begin{lemma}[Frobenius-fixed homomorphisms]
\label{mumford-lem-frobenius-fixed-hom}
\dcref{M:appI:I}
The image of $\Hom_{k_0}(A,B)$ in
$\Hom_{\Zell}(T_\ell(A),T_\ell(B))$ is exactly the subgroup fixed by Frobenius.
After tensoring with $\Qell$, the fixed subspace is finite-dimensional and
has the same dimension as $\Hom_{k_0}(A,B)\otimes\Qell$.
\uses{mumford-thm-tate-hom-isomorphism}
\notready
\end{lemma}

\section{Frobenius and characteristic polynomials}
\label{mumford-AppI-frobenius}
\dcref{M:appI:I}

\begin{definition}[Frobenius polynomial]
\label{mumford-def-frobenius-polynomial}
\dcref{M:appI:I}
For $A/k_0$ of dimension $g$, let $F_A$ be Frobenius and define
\[
 P_A(T)=\det(T-F_A\mid V_\ell(A)),\qquad
 V_\ell(A)=T_\ell(A)\otimes_{\Zell}\Qell.
\]
This monic polynomial has integer coefficients independent of $\ell$ and degree
$2g$.
\uses{mumford-def-tate-module,mumford-conv-tate-fields}
\notready
\end{definition}

\begin{theorem}[Frobenius criterion for isogeny]
\label{mumford-thm-frobenius-isogeny-criterion}
\dcref{M:appI:I}
For abelian varieties $A,B$ over $k_0$, the following are equivalent:
\begin{enumerate}
\item $A$ and $B$ are $k_0$-isogenous;
\item $V_\ell(A)$ and $V_\ell(B)$ are isomorphic as $\Qell[F]$-modules;
\item $P_A(T)=P_B(T)$.
\end{enumerate}
More generally, $B$ is isogenous to an abelian subvariety of $A$ exactly when
$P_B$ divides $P_A$.
\uses{mumford-def-frobenius-polynomial,mumford-thm-tate-hom-isomorphism,mumford-thm-poincare-complete-reducibility}
\notready
\end{theorem}

\begin{theorem}[Semisimplicity of Frobenius]
\label{mumford-thm-frobenius-semisimple}
\dcref{M:appI:I}
The Frobenius action on $V_\ell(A)$ is semisimple.  Its eigenvalues are
algebraic integers with absolute value $\sqrt{|k_0|}$ under every complex
embedding, and $P_A$ satisfies the functional equation forced by the Weil
pairing.
\uses{mumford-def-frobenius-polynomial,mumford-def-weil-pairing-ladic}
\notready
\end{theorem}

\begin{corollary}[Finite-field endomorphism algebra]
\label{mumford-cor-finite-field-end-algebra}
\dcref{M:appI:I}
The algebra $\End^0_{k_0}(A)$ is the Frobenius-centralizer in
$\End_{\Qell}(V_\ell(A))$.  If $A$ is simple, $\Q[F_A]$ is a field and the
endomorphism algebra is a central division algebra over its center containing
that field.
\uses{mumford-thm-tate-hom-isomorphism,mumford-thm-frobenius-semisimple,mumford-cor-simple-endomorphism-algebra}
\notready
\end{corollary}

\begin{remark}[Tate theorem proof interface]
\label{mumford-app1-tate-main-theorem}
The finite-field Tate homomorphism theorem is the central assertion of this
chapter; its proof interfaces are recorded in the supporting register.
\dcref{M:appI:I}
\uses{mumford-thm-tate-hom-isomorphism,mumford-app1-step-verification-finite-field}
\notready
\end{remark}

\section{Supporting proof interfaces}
\label{mumford-AppI-coverage-register}
The theorem statement and its finite-field proof architecture are separated
here so that every dependency remains visible even where a detailed proof is
treated as an external input.

\begin{definition}[Galois-equivariant Tate map]
\label{mumford-app1-tate-map-and-galois-invariants}
Restriction of a homomorphism over $k_0$ to prime-to-$p$ torsion gives a
Galois-equivariant map
\[
 \Zell\otimes\Hom_{k_0}(A,B)\longrightarrow
 \Hom_{\Zell[G]}(T_\ell A,T_\ell B).
\]
\dcref{M:appI:I}
\uses{mumford-def-tate-module,mumford-prop-galois-tate-action}
\notready
\end{definition}

\begin{remark}[Reduction to endomorphisms]
\label{mumford-app1-step-reduction-endomorphisms}
Products reduce Tate's Hom assertion to the endomorphism algebra of one
abelian variety; the invariant Hom space is then a commutant.
\dcref{M:appI:I}
\uses{mumford-app1-tate-map-and-galois-invariants}
\notready
\end{remark}

\begin{remark}[Independence of the prime]
\label{mumford-app1-step-independence-l}
The dimension of the Frobenius-invariant commutant is independent of the
auxiliary prime $\ell$; this is the comparison step in the proof.
\dcref{M:appI:I}
\uses{mumford-def-frobenius-polynomial,mumford-app1-step-reduction-endomorphisms}
\notready
\end{remark}

\begin{convention}[Finite isogeny-model hypothesis]
\label{mumford-app1-hypothesis-finite-isogeny-models}
For a fixed polarized numerical type over a finite field, only finitely many
$\ell$-power isogeny models occur up to isomorphism.
\dcref{M:appI:I}
\notready
\end{convention}

\begin{lemma}[Finite polarized models]
\label{mumford-app1-finite-field-finiteness-lemma}
Bounded projective embeddings and finiteness of the base field give finitely many
models of the fixed polarized type.
\dcref{M:appI:I}
\uses{mumford-app1-hypothesis-finite-isogeny-models}
\notready
\end{lemma}

\begin{remark}[Stable torsion quotients]
\label{mumford-app1-step-descent-torsion-quotients}
Galois-stable Tate submodules define finite quotient varieties; the quotient
group law and a descended polarization are constructed before the commutant
calculation.
\dcref{M:appI:I}
\uses{mumford-app1-finite-field-finiteness-lemma,mumford-prop-abelian-quotient}
\notready
\end{remark}

\begin{lemma}[Galois descent of finite quotients]
\label{mumford-app1-quotient-descent-lemma}
A finite quotient by a Galois-stable subgroup descends to the finite base field,
with its induced abelian-variety structure.
\dcref{M:appI:I}
\uses{mumford-app1-step-descent-torsion-quotients}
\notready
\end{lemma}

\begin{lemma}[Descent of line bundles]
\label{mumford-app1-line-bundle-galois-descent-lemmas}
Galois-invariant divisor and line-bundle classes descend after the finite
extension used to define the quotient model.
\dcref{M:appI:I}
\uses{mumford-app1-quotient-descent-lemma}
\notready
\end{lemma}

\begin{remark}[Commutant calculation]
\label{mumford-app1-step-commutant-isomorphism}
Under the finite-model hypothesis, the commutant of the Frobenius action has
the same dimension as the image of the geometric Hom group.
\dcref{M:appI:I}
\uses{mumford-app1-step-independence-l,mumford-app1-line-bundle-galois-descent-lemmas}
\notready
\end{remark}

\begin{remark}[Finite-field verification]
\label{mumford-app1-step-verification-finite-field}
The finite-field model lemma verifies the finite-isogeny-model hypothesis and
closes the proof of Tate's isomorphism.
\dcref{M:appI:I}
\uses{mumford-app1-finite-field-finiteness-lemma,mumford-app1-step-commutant-isomorphism}
\notready
\end{remark}

\begin{lemma}[Polynomial primes]
\label{mumford-app1-polynomial-prime-lemma}
A nonconstant integral polynomial has roots modulo infinitely many primes after
passing to a suitable residue factor; this supplies split auxiliary primes.
\dcref{M:appI:I}
\uses{mumford-app1-step-independence-l}
\notready
\end{lemma}

\begin{lemma}[Linear-algebra commutant formula]
\label{mumford-app1-linear-algebra-commutant-lemma}
If semisimple operators have characteristic polynomials
$\prod p^{m(p)}$ and $\prod p^{n(p)}$, then the intertwiner space has dimension
$\sum_p m(p)n(p)\deg p$.
\dcref{M:appI:I}
\uses{mumford-app1-polynomial-prime-lemma}
\notready
\end{lemma}

\begin{theorem}[Invariant form of Tate's theorem]
\label{mumford-app1-tate-theorem-finite-field-invariant-form}
The finite-field Hom group is exactly the Frobenius-fixed part of the l-adic
Hom space, integrally and after tensoring with $\Qell$.
\dcref{M:appI:I}
\uses{mumford-thm-tate-hom-isomorphism,mumford-app1-linear-algebra-commutant-lemma}
\notready
\end{theorem}

\begin{theorem}[Finite-field equivalences]
\label{mumford-app1-finite-field-equivalences}
For abelian varieties over $k_0$, equality/divisibility of Frobenius
polynomials is equivalent to the corresponding isogeny and subvariety
criteria, and determines the Hom rank.
\dcref{M:appI:I}
\uses{mumford-thm-frobenius-isogeny-criterion,mumford-app1-tate-theorem-finite-field-invariant-form}
\notready
\end{theorem}

\begin{corollary}[Simple factors and supersingular elliptic curves]
\label{mumford-app1-simple-factor-structure}
Poincare decomposition plus the Frobenius criterion gives simple-factor
uniqueness up to isogeny and the mutual isogeny of supersingular elliptic
curves over an algebraic closure.
\dcref{M:appI:I}
\uses{mumford-app1-finite-field-equivalences,mumford-thm-poincare-complete-reducibility}
\notready
\end{corollary}

\label{mumford-AppII-statement}
\dcref{M:appII:II}

\begin{convention}[Arithmetic setting]
\label{mumford-conv-mordell-weil}
\dcref{M:appII:II}
Let $K$ be a number field and let $A/K$ be an abelian variety.  Write
$A(K)$ for its group of $K$-rational points and fix a symmetric ample line
bundle $L$ on $A$.
\notready
\end{convention}

\begin{theorem}[Mordell--Weil]
\label{mumford-thm-mordell-weil}
The group $A(K)$ is finitely generated.
\dcref{M:appII:II}
\uses{mumford-conv-mordell-weil,mumford-thm-weak-mordell-weil,
 mumford-thm-mordell-weil-descent}
\notready
\end{theorem}

\begin{proposition}[Quadratic canonical height]
\label{mumford-prop-canonical-height}
There is a function $\hat h_L:A(\overline K)\to\R$ and a symmetric bilinear
pairing $\langle\ ,\ \rangle_L$ on $A(\overline K)$ modulo torsion such that
\[
 \hat h_L(nx)=n^2\hat h_L(x),\qquad
 \langle x,y\rangle_L=\tfrac12(\hat h_L(x+y)-\hat h_L(x)-\hat h_L(y)),
\]
and $\hat h_L(x)\ge0$, with equality precisely for torsion points.  It differs
from a Weil height attached to $L$ by a bounded function.
\dcref{M:appII:II}
\uses{mumford-conv-mordell-weil,mumford-lem-height-parallelogram}
\notready
\end{proposition}

\begin{lemma}[Parallelogram identity]
\label{mumford-lem-height-parallelogram}
\dcref{M:appII:II}
For a symmetric line bundle and a Weil height $h_L$, the cube identity yields
\[
 h_L(x+y)+h_L(x-y)-2h_L(x)-2h_L(y)=O(1)
\]
uniformly in $x,y$.  The sequence $4^{-r}h_L(2^rx)$ is then Cauchy; its limit
defines the canonical height, and polarization of the defect gives the
associated bilinear pairing.
\uses{mumford-thm-cube-schemes}
\notready
\end{lemma}

\section{Weak Mordell--Weil theorem}
\label{mumford-AppII-weak}
\dcref{M:appII:II}

\begin{proposition}[Kummer injection]
\label{mumford-prop-kummer-injection}
\dcref{M:appII:II}
For every integer $n>1$, the Kummer map gives an injection
\[
 A(K)/nA(K)\hookrightarrow H^1(K,A[n]).
\]
Its image is described by local divisibility conditions at the places of $K$.
\uses{mumford-prop-multiplication-n,mumford-def-cartier-dual}
\notready
\end{proposition}

\begin{lemma}[Finite Kummer quotient]
\label{mumford-lem-finite-kummer-quotient}
\dcref{M:appII:II}
For fixed $n$, the subgroup of $H^1(K,A[n])$ satisfying the unramified and
integrality conditions outside a finite set of places is finite.  Hence
$A(K)/nA(K)$ is finite.
\uses{mumford-prop-kummer-injection}
\notready
\end{lemma}

\begin{theorem}[Weak Mordell--Weil]
\label{mumford-thm-weak-mordell-weil}
For every integer $n>1$, $A(K)/nA(K)$ is finite.
\dcref{M:appII:II}
\uses{mumford-lem-finite-kummer-quotient}
\notready
\end{theorem}

\section{Descent and finite generation}
\label{mumford-AppII-descent}
\dcref{M:appII:II}

\begin{lemma}[Northcott property]
\label{mumford-lem-northcott-abelian}
\dcref{M:appII:II}
For a projective embedding supplied by a symmetric ample line bundle, points
of bounded degree over $K$ and bounded Weil height form a finite set.  The same
holds for the canonical height because it differs from a Weil height by a
bounded amount.
\uses{mumford-prop-canonical-height,mumford-thm-high-power-very-ample}
\notready
\end{lemma}

\begin{proposition}[Finite descent set]
\label{mumford-prop-finite-descent-set}
\dcref{M:appII:II}
Choose $n>1$ and representatives $x_1,\ldots,x_r$ for $A(K)/nA(K)$.  There is a
constant $C$ such that every class has a representative $x_i$ with
$\hat h_L(x_i)\le C$; subtracting suitable multiples of $n$ decreases the
height unless the point lies in a finite Northcott set.
\uses{mumford-thm-weak-mordell-weil,mumford-lem-northcott-abelian}
\notready
\end{proposition}

\begin{lemma}[Finite rational torsion]
\label{mumford-lem-rational-torsion-finite}
\dcref{M:appII:II}
The torsion points in $A(K)$ have canonical height zero and therefore lie in a
bounded-height set of bounded degree.  Northcott's theorem makes this set
finite, so $A(K)_{\mathrm{tors}}$ is finite.
\uses{mumford-prop-canonical-height,mumford-lem-northcott-abelian}
\notready
\end{lemma}

\begin{theorem}[Descent conclusion]
\label{mumford-thm-mordell-weil-descent}
\dcref{M:appII:II}
The finite descent set together with the finite torsion subgroup generates
$A(K)$.  Therefore $A(K)$ is a finitely generated abelian group.
\uses{mumford-prop-finite-descent-set,mumford-lem-rational-torsion-finite,
 mumford-prop-canonical-height}
\begin{proof}
Let $\Gamma$ be the subgroup generated by the finite set of representatives
and $A(K)_{\mathrm{tors}}$.  For any $x\in A(K)$, repeatedly replace $x$ by a
representative of its class modulo $nA(K)$ and divide the remaining difference
by $n$.  The quadratic height relation shows that the height of the remainder
strictly decreases unless it is in the bounded finite set from Northcott.
Induction on the height therefore expresses $x$ in $\Gamma$.
\end{proof}
\notready
\end{theorem}

\begin{corollary}[Finite torsion]
\label{mumford-cor-finite-torsion}
\dcref{M:appII:II}
The torsion subgroup $A(K)_{\mathrm{tors}}$ is finite.
\uses{mumford-lem-rational-torsion-finite}
\notready
\end{corollary}

\begin{remark}[Mordell--Weil proof interface]
\label{mumford-app2-mordell-weil-theorem}
The finite-generation theorem combines the weak quotient, canonical height, and
finite descent interfaces.
\dcref{M:appII:II}
\uses{mumford-thm-mordell-weil,mumford-app2-final-descent}
\notready
\end{remark}

\section{Supporting arithmetic interfaces}
\label{mumford-AppII-coverage-register}
The arithmetic interfaces in this register make the weak theorem, height
construction, and descent dependencies explicit.  Detailed proofs are treated
as external inputs where necessary.

\begin{proposition}[Finite weak quotient target]
\label{mumford-app2-weak-quotient-finite}
For each $n>1$, finiteness of $A(K)/nA(K)$ is the weak Mordell--Weil target used
by descent.
\dcref{M:appII:II}
\uses{mumford-thm-weak-mordell-weil}
\notready
\end{proposition}

\begin{proposition}[Height pairing target]
\label{mumford-app2-height-pairing-target}
The canonical height is quadratic, nonnegative for a symmetric ample bundle,
and positive modulo torsion on $A(K)$.
\dcref{M:appII:II}
\uses{mumford-prop-canonical-height,mumford-lem-rational-torsion-finite}
\notready
\end{proposition}

\begin{proposition}[Abstract descent criterion]
\label{mumford-app2-abstract-descent}
An abelian group with finite quotient by $n$ and a positive quadratic height with
finite bounded sets is finitely generated.
\dcref{M:appII:II}
\uses{mumford-thm-weak-mordell-weil,mumford-app2-height-pairing-target,
 mumford-lem-northcott-abelian}
\notready
\end{proposition}

\begin{lemma}[Division points and Kummer cocycle]
\label{mumford-app2-kummer-fundamental-lemma}
After adjoining an $n$-division point of $x\in A(K)$, the differences
$\sigma(z)-z$ define a cocycle with values in $A[n]$, independent of the
chosen division point up to coboundary.
\dcref{M:appII:II}
\uses{mumford-prop-kummer-injection}
\notready
\end{lemma}

\begin{lemma}[Finite division kernel]
\label{mumford-app2-finite-division-kernel}
The kernel of multiplication by $n$ is finite, and the Kummer cocycle vanishes
exactly when $x$ is divisible by $n$ in $A(K)$.
\dcref{M:appII:II}
\uses{mumford-prop-multiplication-n,mumford-app2-kummer-fundamental-lemma}
\notready
\end{lemma}

\begin{lemma}[Good model over an arithmetic open]
\label{mumford-app2-model-over-open}
After removing finitely many primes from the ring of integers of $K$, $A$ and
its ample bundle extend to a proper model with smooth group fibres.
\dcref{M:appII:II}
\uses{mumford-conv-mordell-weil}
\notready
\end{lemma}

\begin{corollary}[Etale division away from $n$]
\label{mumford-app2-etale-division-corollary}
On the good model, multiplication by $n$ is etale outside the finite set of
places dividing $n$ and the bad-reduction set.
\dcref{M:appII:II}
\uses{mumford-app2-model-over-open,mumford-prop-multiplication-n}
\notready
\end{corollary}

\begin{lemma}[Unramified Kummer classes]
\label{mumford-app2-arithmetic-unramified-classes}
Kummer classes unramified outside a fixed finite set of places form a finite
subgroup of $H^1(K,A[n])$; this uses finiteness of unit and ideal-class
quotients.
\dcref{M:appII:II}
\uses{mumford-app2-etale-division-corollary,mumford-prop-kummer-injection}
\notready
\end{lemma}

\begin{definition}[Normalized absolute values]
\label{mumford-app2-normalized-absolute-values}
Choose normalized absolute values on $K$ so that the product formula holds, and
define the projective height by the weighted sum of local logarithmic maxima.
\dcref{M:appII:II}
\notready
\end{definition}

\begin{proposition}[Projective height properties]
\label{mumford-app2-projective-height-properties}
The projective height is invariant under scaling, functorial under finite field
extension, and satisfies the standard bounded-error inequalities for products
and morphisms.
\dcref{M:appII:II}
\uses{mumford-app2-normalized-absolute-values}
\notready
\end{proposition}

\begin{proposition}[Northcott in projective space]
\label{mumford-app2-northcott-proposition}
Points of bounded degree and bounded projective height over a number field form
a finite set.
\dcref{M:appII:II}
\uses{mumford-app2-projective-height-properties}
\notready
\end{proposition}

\begin{definition}[Height of a line bundle]
\label{mumford-app2-line-bundle-height}
An embedding associated with an ample line bundle $L$ pulls the projective
height back to a Weil height $h_L$ on $A(\overline K)$.
\dcref{M:appII:II}
\uses{mumford-app2-projective-height-properties,mumford-thm-high-power-very-ample}
\notready
\end{definition}

\begin{proposition}[Comparison of equivalent heights]
\label{mumford-app2-height-comparison-proposition}
Heights attached to linearly equivalent bundles differ by a bounded function;
tensor products add heights up to bounded error.
\dcref{M:appII:II}
\uses{mumford-app2-line-bundle-height}
\notready
\end{proposition}

\begin{lemma}[Approximate quadraticity]
\label{mumford-app2-approximate-quadratic-lemma}
For symmetric $L$, the cube relation gives a uniform bounded defect in the
parallelogram identity for $h_L$.
\dcref{M:appII:II}
\uses{mumford-app2-height-comparison-proposition,mumford-thm-cube-schemes}
\notready
\end{lemma}

\begin{theorem}[Tate height construction]
\label{mumford-app2-tate-height}
The limit of the normalized heights $4^{-r}h_L(2^rx)$ exists and is a quadratic
height satisfying $\widehat h_L(nx)=n^2\widehat h_L(x)$.
\dcref{M:appII:II}
\uses{mumford-app2-approximate-quadratic-lemma,mumford-prop-canonical-height}
\notready
\end{theorem}

\begin{proposition}[Height positivity and finiteness]
\label{mumford-app2-height-positivity-finiteness}
For rational points, the canonical height is positive away from torsion, and
Northcott makes every bounded-height subset finite.
\dcref{M:appII:II}
\uses{mumford-app2-tate-height,mumford-app2-northcott-proposition}
\notready
\end{proposition}

\begin{remark}[Final descent step]
\label{mumford-app2-final-descent}
Choose representatives for the finite quotient modulo $n$ and repeatedly divide
the remainder.  The quadratic height decreases outside the finite Northcott
set, so induction gives a finite generating set.
\dcref{M:appII:II}
\uses{mumford-app2-abstract-descent,mumford-thm-mordell-weil-descent}
\notready
\end{remark}

